import path from 'node:path';
import { existsSync, readFileSync } from 'node:fs';
import { brotliCompressSync, constants as zlibConstants, gzipSync } from 'node:zlib';
import fg from 'fast-glob';
import type {
  BundleFileReport,
  BundleReport,
  DuplicateDependencyReport,
  Finding,
  HeavyDependencyReport,
  ModuleAttribution,
  ResolvedCodeUsageMapConfig,
} from '../types.js';
import type { ProjectDetection } from '../integrations/detect.js';
import type { StaticAnalysisResult } from '../static/types.js';
import type { SourceCollection } from '../static/source-files.js';
import { createFinding } from '../static/finding-utils.js';
import { hashString, toPosix } from '../util/fs.js';
import { loadSourceMapFromFile, packageFromSource, type SourceMapIndex } from '../sourcemap/parse.js';

export interface BundleAnalysisResult {
  report: BundleReport;
  findings: Finding[];
  sourceMapIndexes: SourceMapIndex[];
  warnings: string[];
  cssFiles: string[];
  jsFiles: string[];
}

interface BuildAsset {
  file: string;
  relativeToBuild: string;
  buildRoot: string;
  type: 'js' | 'css';
  rawBytes: number;
  gzipBytes: number;
  brotliBytes: number;
  initial: boolean;
  routes: Set<string>;
  text?: string;
  index?: SourceMapIndex;
  modules: ModuleAttribution[];
  notes: string[];
}

const MAX_COMPRESS_BYTES = 100 * 1024 * 1024;
const MAX_TEXT_BYTES = 60 * 1024 * 1024;

function compressionSizes(buffer: Buffer, file: string, warnings: string[]): { gzip: number; brotli: number } {
  if (buffer.length > MAX_COMPRESS_BYTES) {
    warnings.push(`Compression skipped for ${file} because it exceeds ${MAX_COMPRESS_BYTES} bytes.`);
    return { gzip: 0, brotli: 0 };
  }
  try {
    return {
      gzip: gzipSync(buffer, { level: 9 }).length,
      brotli: brotliCompressSync(buffer, {
        params: {
          [zlibConstants.BROTLI_PARAM_QUALITY]: 9,
        },
      }).length,
    };
  } catch {
    warnings.push(`Compression failed for ${file}.`);
    return { gzip: 0, brotli: 0 };
  }
}

function routeFromHtml(relativeHtml: string): string {
  const withoutExt = relativeHtml.replace(/\.html?$/i, '');
  if (withoutExt === 'index' || withoutExt.endsWith('/index')) {
    const dir = withoutExt.replace(/\/?index$/, '');
    return `/${dir}`.replace(/\/+/g, '/');
  }
  return `/${withoutExt}`.replace(/\/+/g, '/');
}

function discoverBuildDirs(
  root: string,
  config: ResolvedCodeUsageMapConfig,
  detection: ProjectDetection,
): string[] {
  const configured = config.build.dir
    ? Array.isArray(config.build.dir)
      ? config.build.dir
      : [config.build.dir]
    : [];
  const dirs = (configured.length > 0 ? configured : detection.buildDirs)
    .map((dir) => path.resolve(root, dir))
    .filter((dir) => existsSync(dir));
  const unique = [...new Set(dirs)];
  // Prefer the nested .next/static directory when both it and .next exist.
  return unique.filter((dir) => {
    const parent = path.basename(path.dirname(dir));
    if (path.basename(dir) === '.next' && unique.some((other) => other === path.join(dir, 'static'))) {
      return false;
    }
    void parent;
    return true;
  });
}

function isRelevantBuildFile(file: string, buildRoot: string): boolean {
  const relative = toPosix(path.relative(buildRoot, file));
  if (path.basename(buildRoot) === '.next') {
    return relative.startsWith('static/') && !relative.includes('/server/');
  }
  if (path.basename(buildRoot) === 'static' && path.basename(path.dirname(buildRoot)) === '.next') {
    return !relative.includes('/server/');
  }
  if (relative.includes('/node_modules/')) return false;
  return /\.(js|mjs|cjs|css)$/i.test(file);
}

function resolveAssetUrl(
  url: string,
  htmlFile: string,
  buildRoot: string,
  fileSet: Set<string>,
): string | undefined {
  const clean = url.replace(/[?#].*$/, '');
  if (!clean || /^(?:https?:)?\/\//i.test(clean) || clean.startsWith('data:')) return undefined;
  const candidates = new Set<string>();
  if (clean.startsWith('/')) {
    candidates.add(path.resolve(buildRoot, `.${clean}`));
  } else {
    candidates.add(path.resolve(path.dirname(htmlFile), clean));
    candidates.add(path.resolve(buildRoot, clean));
  }
  for (const candidate of candidates) {
    if (fileSet.has(path.normalize(candidate))) return path.normalize(candidate);
  }
  return undefined;
}

function extractHtmlAssets(html: string): { scripts: string[]; styles: string[]; preloads: string[] } {
  const scripts: string[] = [];
  const styles: string[] = [];
  const preloads: string[] = [];
  const tagRegex = /<(script|link)\b([^>]*)>/gi;
  let match: RegExpExecArray | null;
  while ((match = tagRegex.exec(html)) !== null) {
    const tag = (match[1] ?? '').toLowerCase();
    const attrs = match[2] ?? '';
    const src = /\bsrc\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i.exec(attrs);
    const href = /\bhref\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i.exec(attrs);
    const rel = /\brel\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/i.exec(attrs);
    if (tag === 'script' && src) {
      scripts.push(src[1] ?? src[2] ?? src[3] ?? '');
    } else if (tag === 'link' && href) {
      const hrefValue = href[1] ?? href[2] ?? href[3] ?? '';
      const relValue = (rel?.[1] ?? rel?.[2] ?? rel?.[3] ?? '').toLowerCase();
      if (relValue.includes('stylesheet')) styles.push(hrefValue);
      else if (relValue.includes('modulepreload') || relValue.includes('preload')) preloads.push(hrefValue);
    }
  }
  return { scripts, styles, preloads };
}

function readJsonSafe<T>(file: string): T | undefined {
  try {
    return JSON.parse(readFileSync(file, 'utf8')) as T;
  } catch {
    return undefined;
  }
}

interface ManifestAsset {
  file: string;
  initial: boolean;
  routes: string[];
  buildRoot: string;
}

function applyViteManifest(
  file: string,
  buildRoot: string,
  assetsByFile: Map<string, BuildAsset>,
  buildAssetByRelative: Map<string, BuildAsset>,
): ManifestAsset[] | undefined {
  const manifest = readJsonSafe<Record<string, {
    file?: string;
    css?: string[];
    imports?: string[];
    dynamicImports?: string[];
    isEntry?: boolean;
  }>>(file);
  if (!manifest) return undefined;
  const results: ManifestAsset[] = [];
  const visited = new Set<string>();

  const visit = (key: string, initial: boolean, route?: string): void => {
    if (visited.has(`${key}|${initial}`)) return;
    visited.add(`${key}|${initial}`);
    const entry = manifest[key];
    if (!entry) return;
    const keyRoute = key.endsWith('.html') ? routeFromHtml(key) : route ?? '/';
    for (const css of entry.css ?? []) {
      const relative = toPosix(css);
      const asset = buildAssetByRelative.get(relative) ?? assetsByFile.get(path.resolve(buildRoot, relative));
      if (asset) {
        if (initial) asset.initial = true;
        asset.routes.add(keyRoute);
        results.push({ file: asset.file, initial, routes: [keyRoute], buildRoot });
      }
    }
    if (entry.file) {
      const relative = toPosix(entry.file);
      const asset = buildAssetByRelative.get(relative) ?? assetsByFile.get(path.resolve(buildRoot, relative));
      if (asset) {
        if (initial) asset.initial = true;
        asset.routes.add(keyRoute);
        results.push({ file: asset.file, initial, routes: [keyRoute], buildRoot });
      }
    }
    for (const imported of entry.imports ?? []) visit(imported, initial);
    for (const dynamic of entry.dynamicImports ?? []) visit(dynamic, false);
  };

  for (const [key, entry] of Object.entries(manifest)) {
    if (entry.isEntry || key.endsWith('.html')) visit(key, true);
  }
  return results;
}

function applyCodeUsageBuildManifest(
  file: string,
  buildRoot: string,
  root: string,
  assetsByFile: Map<string, BuildAsset>,
  buildAssetByRelative: Map<string, BuildAsset>,
): ManifestAsset[] | undefined {
  const manifest = readJsonSafe<{
    schemaVersion?: number;
    buildTool?: string;
    chunks?: Array<{
      file?: string;
      entry?: boolean;
      initial?: boolean;
      css?: string[];
      routes?: string[];
      modules?: Array<{ id?: string; bytes?: number }>;
    }>;
    routes?: Array<{ route?: string; files?: string[]; initial?: boolean }>;
  }>(file);
  if (!manifest || !Array.isArray(manifest.chunks)) return undefined;

  const results: ManifestAsset[] = [];
  const fileAsset = (relative: string): BuildAsset | undefined => {
    const normalized = toPosix(relative).replace(/^\/+/, '');
    return buildAssetByRelative.get(normalized) ?? assetsByFile.get(path.resolve(buildRoot, normalized));
  };
  const attach = (asset: BuildAsset, routes: string[], initial: boolean): void => {
    if (initial) asset.initial = true;
    for (const route of routes) asset.routes.add(route);
    results.push({ file: asset.file, initial, routes, buildRoot });
  };

  for (const route of manifest.routes ?? []) {
    if (!route.route) continue;
    for (const fileReference of route.files ?? []) {
      const asset = fileAsset(fileReference);
      if (asset) attach(asset, [route.route], route.initial !== false);
    }
  }

  for (const chunk of manifest.chunks) {
    if (!chunk.file) continue;
    const routes = Array.isArray(chunk.routes) ? chunk.routes.filter((route) => route.length > 0) : ['/'];
    const asset = fileAsset(chunk.file);
    if (asset) {
      attach(asset, routes, chunk.initial === true || chunk.entry === true);
      if (asset.modules.length === 0 && Array.isArray(chunk.modules)) {
        asset.modules = chunk.modules
          .filter((module): module is { id: string; bytes?: number } => Boolean(module.id))
          .map((module) => {
            let clean = (module.id ?? '').split('!').pop() ?? module.id ?? '';
            clean = clean.replace(/^webpack:\/\/[^/]*\/?/, '').replace(/[?#].*$/, '');
            const absolute = path.isAbsolute(clean) ? clean : path.resolve(root, clean);
            const display = absolute.startsWith(root) ? toPosix(path.relative(root, absolute)) : clean;
            const packageInfo = packageFromSource(display);
            return {
              sourceFile: display,
              ...(packageInfo.packageName ? { packageName: packageInfo.packageName } : {}),
              ...(packageInfo.version ? { version: packageInfo.version } : {}),
              bytes: module.bytes ?? 0,
              mappingSegments: 0,
            };
          })
          .sort((a, b) => b.bytes - a.bytes);
      }
    }
    for (const css of chunk.css ?? []) {
      const cssAsset = fileAsset(css);
      if (cssAsset) attach(cssAsset, routes, chunk.initial === true || chunk.entry === true);
    }
  }
  return results;
}

function applyNextManifest(
  file: string,
  buildRoot: string,
  assetsByFile: Map<string, BuildAsset>,
  buildAssetByRelative: Map<string, BuildAsset>,
): ManifestAsset[] | undefined {
  const manifest = readJsonSafe<{
    pages?: Record<string, string[]>;
    app?: Record<string, string[]>;
    rootMainFiles?: string[];
    pagesChunks?: Record<string, string[]>;
  }>(file);
  if (!manifest) return undefined;
  if (!('pages' in manifest) && !('app' in manifest) && !('rootMainFiles' in manifest)) return undefined;
  const results: ManifestAsset[] = [];
  const mark = (route: string, chunks: string[], initial: boolean): void => {
    for (const chunk of chunks) {
      const candidates = [
        path.resolve(buildRoot, chunk),
        path.resolve(buildRoot, 'static', chunk),
        path.resolve(path.dirname(buildRoot), chunk),
        path.resolve(path.dirname(buildRoot), 'static', chunk),
      ];
      let asset: BuildAsset | undefined;
      for (const candidate of candidates) {
        asset = assetsByFile.get(path.normalize(candidate)) ?? buildAssetByRelative.get(toPosix(path.relative(buildRoot, candidate)));
        if (asset) break;
      }
      if (!asset) continue;
      if (initial) asset.initial = true;
      asset.routes.add(route);
      results.push({ file: asset.file, initial, routes: [route], buildRoot });
    }
  };
  for (const [route, chunks] of Object.entries(manifest.pages ?? {})) {
    mark(route, chunks, route === '/' || route === '/_app' || route === '/_document');
  }
  for (const [route, chunks] of Object.entries(manifest.pagesChunks ?? {})) {
    mark(route, chunks, route === '/' || route === '/_app');
  }
  for (const [route, chunks] of Object.entries(manifest.app ?? {})) {
    mark(route, chunks, route === '/' || route === '/_app' || route === '/layout');
  }
  mark('/', manifest.rootMainFiles ?? [], true);
  return results;
}

/** Discovers build outputs, measures sizes, decodes source maps and attributes code. */
export function analyzeBundles(options: {
  root: string;
  config: ResolvedCodeUsageMapConfig;
  detection: ProjectDetection;
  files: SourceCollection;
  staticResult: StaticAnalysisResult;
  signal?: AbortSignal;
}): BundleAnalysisResult {
  const { root, config, detection, signal } = options;
  const warnings: string[] = [];
  const buildDirs = discoverBuildDirs(root, config, detection);

  if (buildDirs.length === 0) {
    const report: BundleReport = {
      available: false,
      buildDirs: [],
      files: [],
      totals: {
        rawBytes: 0,
        gzipBytes: 0,
        brotliBytes: 0,
        jsRawBytes: 0,
        cssRawBytes: 0,
        initialRawBytes: 0,
        lazyRawBytes: 0,
      },
      initialFileIds: [],
      lazyFileIds: [],
      duplicateDependencies: [],
      heavyDependencies: [],
      mappingCoverage: { jsFiles: 0, mappedJsFiles: 0, cssFiles: 0, mappedCssFiles: 0, mappedPercent: 0 },
      notes: ['No build output directory was detected. Build the application or set build.dir to analyze bundles.'],
    };
    return { report, findings: [], sourceMapIndexes: [], warnings, cssFiles: [], jsFiles: [] };
  }

  const patterns = buildDirs.map((dir) => `${toPosix(path.relative(root, dir))}/**/*.{js,mjs,cjs,css}`);
  let discovered: string[] = [];
  try {
    discovered = fg.sync(patterns, {
      cwd: root,
      absolute: true,
      onlyFiles: true,
      unique: true,
      dot: true,
      ignore: ['**/*.map', '**/node_modules/**', '**/.git/**'],
    }).map((file) => path.normalize(file));
  } catch (error) {
    warnings.push(`Build file discovery failed: ${error instanceof Error ? error.message : String(error)}`);
  }

  const buildRootFor = (file: string): string => {
    let best = buildDirs[0] ?? root;
    for (const dir of buildDirs) {
      if (file.startsWith(dir) && dir.length > best.length) best = dir;
    }
    return best;
  };

  const assetsByFile = new Map<string, BuildAsset>();
  const buildAssetByRelative = new Map<string, BuildAsset>();

  for (const file of discovered) {
    if (signal?.aborted) throw new Error('Bundle analysis aborted');
    const buildRoot = buildRootFor(file);
    if (!isRelevantBuildFile(file, buildRoot)) continue;
    if (assetsByFile.has(file)) continue;
    const type = path.extname(file).toLowerCase() === '.css' ? 'css' : 'js';
    let buffer: Buffer;
    try {
      buffer = readFileSync(file);
    } catch {
      warnings.push(`Could not read build asset ${toPosix(path.relative(root, file))}.`);
      continue;
    }
    const compressed = compressionSizes(buffer, toPosix(path.relative(root, file)), warnings);
    const text = buffer.length <= MAX_TEXT_BYTES ? buffer.toString('utf8') : undefined;
    const asset: BuildAsset = {
      file,
      relativeToBuild: toPosix(path.relative(buildRoot, file)),
      buildRoot,
      type,
      rawBytes: buffer.length,
      gzipBytes: compressed.gzip,
      brotliBytes: compressed.brotli,
      initial: false,
      routes: new Set<string>(),
      ...(text ? { text } : {}),
      modules: [],
      notes: [],
    };
    if (text) {
      const mapWarnings: string[] = [];
      if (config.analysis.sourceMaps && config.sourceMaps.enabled) {
        const index = loadSourceMapFromFile(
          file,
          text,
          root,
          mapWarnings,
          config.sourceMaps.maxMappingsPerFile,
        );
        asset.index = index;
        asset.modules = index.attribution;
        warnings.push(...mapWarnings.map((warning) => `${toPosix(path.relative(root, file))}: ${warning}`));
        if (index.kind !== 'none') asset.notes.push(`Source map: ${index.kind}`);
      }
    } else {
      asset.notes.push('Text/source-map analysis skipped because the file is too large.');
    }
    assetsByFile.set(file, asset);
    buildAssetByRelative.set(asset.relativeToBuild, asset);
  }

  // HTML entry assets and routes.
  const htmlFiles = fg.sync(
    buildDirs.map((dir) => `${toPosix(path.relative(root, dir))}/**/*.{html,htm}`),
    {
      cwd: root,
      absolute: true,
      onlyFiles: true,
      unique: true,
      dot: true,
      ignore: ['**/node_modules/**'],
    },
  ).map((file) => path.normalize(file));
  const fileSet = new Set(assetsByFile.keys());
  for (const htmlFile of htmlFiles) {
    const buildRoot = buildRootFor(htmlFile);
    const route = routeFromHtml(toPosix(path.relative(buildRoot, htmlFile)));
    let html = '';
    try {
      html = readFileSync(htmlFile, 'utf8');
    } catch {
      continue;
    }
    const extracted = extractHtmlAssets(html);
    for (const reference of [...extracted.scripts, ...extracted.styles, ...extracted.preloads]) {
      const assetFile = resolveAssetUrl(reference, htmlFile, buildRoot, fileSet);
      if (!assetFile) continue;
      const asset = assetsByFile.get(assetFile);
      if (!asset) continue;
      asset.initial = true;
      asset.routes.add(route);
    }
  }

  // Manifests.
  let manifestUsed: string | undefined;
  for (const buildRoot of buildDirs) {
    for (const name of [
      'code-usage-map.vite.json',
      'code-usage-map.webpack.json',
      'code-usage-map.manifest.json',
    ]) {
      const candidate = path.join(buildRoot, name);
      if (!existsSync(candidate)) continue;
      const applied = applyCodeUsageBuildManifest(candidate, buildRoot, root, assetsByFile, buildAssetByRelative);
      if (applied) {
        manifestUsed = candidate;
        break;
      }
    }
    if (manifestUsed) break;
  }
  if (config.build.manifest && existsSync(config.build.manifest)) {
    const manifestDirectory = path.dirname(config.build.manifest);
    const manifestRoot =
      buildDirs[0] ??
      (path.basename(manifestDirectory) === '.vite' ? path.dirname(manifestDirectory) : manifestDirectory);
    const custom = applyCodeUsageBuildManifest(
      config.build.manifest,
      manifestRoot,
      root,
      assetsByFile,
      buildAssetByRelative,
    );
    const vite = custom
      ? undefined
      : applyViteManifest(config.build.manifest, manifestRoot, assetsByFile, buildAssetByRelative);
    const next = custom || vite
      ? undefined
      : applyNextManifest(config.build.manifest, manifestRoot, assetsByFile, buildAssetByRelative);
    if (custom || vite || next) manifestUsed = config.build.manifest;
  }
  for (const buildRoot of buildDirs) {
    if (manifestUsed) break;
    const manifests = [
      path.join(buildRoot, '.vite', 'manifest.json'),
      path.join(buildRoot, 'manifest.json'),
      path.join(buildRoot, 'build-manifest.json'),
      path.join(buildRoot, 'app-build-manifest.json'),
      path.join(path.dirname(buildRoot), '.next', 'build-manifest.json'),
      path.join(path.dirname(buildRoot), '.next', 'app-build-manifest.json'),
    ].filter((file) => existsSync(file));
    for (const manifest of manifests) {
      const vite = applyViteManifest(manifest, buildRoot, assetsByFile, buildAssetByRelative);
      const next = vite ? undefined : applyNextManifest(manifest, buildRoot, assetsByFile, buildAssetByRelative);
      if (vite || next) {
        manifestUsed = manifest;
        break;
      }
    }
    if (manifestUsed) break;
  }

  // Follow static imports from initial JavaScript. Bundlers split shared code
  // into unlinked chunks; HTML alone does not reveal those initial chunks.
  const initialQueue = [...assetsByFile.values()].filter((asset) => asset.initial && asset.type === 'js');
  const initialVisited = new Set<string>();
  while (initialQueue.length > 0) {
    const asset = initialQueue.shift();
    if (!asset || !asset.text || initialVisited.has(asset.file)) continue;
    initialVisited.add(asset.file);
    const importRegex = /\b(?:import|export)\s*(?:[^'"();]*?\bfrom\s*)?["']([^"']+)["']/g;
    let imported: RegExpExecArray | null;
    while ((imported = importRegex.exec(asset.text)) !== null) {
      const specifier = imported[1];
      if (!specifier || !specifier.startsWith('.')) continue;
      const clean = specifier.replace(/[?#].*$/, '');
      const targetFile = path.resolve(path.dirname(asset.file), clean);
      const target =
        assetsByFile.get(path.normalize(targetFile)) ??
        buildAssetByRelative.get(toPosix(path.relative(asset.buildRoot, targetFile)));
      if (!target || initialVisited.has(target.file)) continue;
      target.initial = true;
      for (const route of asset.routes) target.routes.add(route);
      if (target.type === 'js') initialQueue.push(target);
    }
  }

  const files: BundleFileReport[] = [...assetsByFile.values()]
    .map((asset) => {
      const index = asset.index;
      const mappedBytes = index?.mappedBytes ?? 0;
      const relativePath = toPosix(path.relative(root, asset.file));
      return {
        id: `b_${hashString(relativePath, 12)}`,
        file: asset.file,
        relativePath,
        type: asset.type,
        rawBytes: asset.rawBytes,
        gzipBytes: asset.gzipBytes,
        brotliBytes: asset.brotliBytes,
        initial: asset.initial,
        routes: [...asset.routes].sort(),
        ...(index?.sourceMapFile ? { sourceMapFile: index.sourceMapFile } : {}),
        ...(index ? { sourceMapKind: index.kind } : {}),
        mapped: Boolean(index && index.kind !== 'none'),
        mappedBytes,
        unmappedBytes: Math.max(0, asset.rawBytes - mappedBytes),
        modules: asset.modules,
        notes: [
          ...asset.notes,
          ...(index?.warnings ?? []),
          ...(index && index.kind === 'none' ? ['No source map found.'] : []),
        ],
      } satisfies BundleFileReport;
    })
    .sort((a, b) => b.rawBytes - a.rawBytes);

  const initialFiles = files.filter((file) => file.initial);
  const lazyFiles = files.filter((file) => !file.initial);
  const jsFiles = files.filter((file) => file.type === 'js');
  const cssFiles = files.filter((file) => file.type === 'css');
  const mappedJs = jsFiles.filter((file) => file.mapped).length;
  const mappedCss = cssFiles.filter((file) => file.mapped).length;

  const totals = {
    rawBytes: files.reduce((sum, file) => sum + file.rawBytes, 0),
    gzipBytes: files.reduce((sum, file) => sum + file.gzipBytes, 0),
    brotliBytes: files.reduce((sum, file) => sum + file.brotliBytes, 0),
    jsRawBytes: jsFiles.reduce((sum, file) => sum + file.rawBytes, 0),
    cssRawBytes: cssFiles.reduce((sum, file) => sum + file.rawBytes, 0),
    initialRawBytes: initialFiles.reduce((sum, file) => sum + file.rawBytes, 0),
    lazyRawBytes: lazyFiles.reduce((sum, file) => sum + file.rawBytes, 0),
  };

  // Package attribution.
  const packages = new Map<string, { bytes: number; files: Set<string>; versions: Set<string> }>();
  for (const file of files) {
    for (const module of file.modules) {
      if (!module.packageName) continue;
      const current = packages.get(module.packageName) ?? { bytes: 0, files: new Set<string>(), versions: new Set<string>() };
      current.bytes += module.bytes;
      current.files.add(file.relativePath);
      if (module.version) current.versions.add(module.version);
      packages.set(module.packageName, current);
    }
  }

  const duplicateDependencies: DuplicateDependencyReport[] = [...packages.entries()]
    .filter(([, info]) => info.versions.size > 1)
    .map(([packageName, info]) => ({
      packageName,
      versions: [...info.versions].sort(),
      locations: [...info.files],
      source: 'source-map' as const,
    }));

  const heavyDependencies: HeavyDependencyReport[] = [...packages.entries()]
    .map(([packageName, info]) => ({
      packageName,
      bytes: info.bytes,
      files: [...info.files],
    }))
    .sort((a, b) => b.bytes - a.bytes)
    .slice(0, 12);

  const findings: Finding[] = [];
  for (const dependency of heavyDependencies.slice(0, 6)) {
    if (dependency.bytes < 40_000) continue;
    const file = files.find((candidate) => candidate.type === 'js' && dependency.files.includes(candidate.relativePath));
    if (!file) continue;
    findings.push(
      createFinding({
        root,
        category: 'heavy-dependency',
        status: 'unknown',
        confidence: 'high',
        title: `Heavy dependency "${dependency.packageName}" (${Math.round(dependency.bytes / 1024)} KB attributed)`,
        description:
          'Source-map attribution places this package in the JS bundle. Attribution is approximate and may include shared runtime helpers. Use bundle analysis and runtime coverage before choosing a replacement.',
        file: file.file,
        line: 1,
        column: 1,
        symbol: dependency.packageName,
        symbolKind: 'dependency',
        dependency: {
          packageName: dependency.packageName,
          dependencyType: 'dependency',
          reason: 'Source-map module attribution exceeds the heavy-dependency threshold.',
        },
        size: {
          bundleAttributedBytes: dependency.bytes,
          basis: 'Approximate mapped bundle bytes; overlapping attribution is not additive with other findings.',
        },
        evidence: [
          {
            kind: 'source-map',
            description: `Attributed across: ${dependency.files.join(', ')}.`,
            file: file.relativePath,
            line: 1,
          },
        ],
        tags: ['dependency', 'bundle', 'heavy'],
        fingerprintSuffix: dependency.packageName,
      }),
    );
  }

  for (const duplicate of duplicateDependencies) {
    const file = files.find((candidate) => duplicate.locations.includes(candidate.relativePath));
    if (!file) continue;
    findings.push(
      createFinding({
        root,
        category: 'duplicate-dependency',
        status: 'unknown',
        confidence: 'medium',
        title: `Multiple bundled versions of "${duplicate.packageName}"`,
        description: `Source maps show versions ${duplicate.versions.join(', ')} in the build. Deduplicate versions to reduce bundle weight.`,
        file: file.file,
        line: 1,
        column: 1,
        symbol: duplicate.packageName,
        symbolKind: 'dependency',
        dependency: {
          packageName: duplicate.packageName,
          dependencyType: 'dependency',
          versions: duplicate.versions,
          reason: 'Multiple versions appear in bundle source-map attribution.',
        },
        size: {},
        evidence: [
          {
            kind: 'source-map',
            description: `Bundle files: ${duplicate.locations.join(', ')}.`,
            file: file.relativePath,
            line: 1,
          },
        ],
        tags: ['dependency', 'duplicate', 'bundle'],
        fingerprintSuffix: `bundle|${duplicate.versions.join('|')}`,
      }),
    );
  }

  if (files.length === 0) {
    warnings.push('Build directories were found but no JavaScript or CSS assets matched.');
  }
  if (initialFiles.length === 0 && files.length > 0) {
    warnings.push(
      'Initial/lazy asset classification was unavailable (no entry HTML or supported manifest). Set build.dir or provide an entry manifest.',
    );
  }

  const report: BundleReport = {
    available: files.length > 0,
    buildDirs,
    files,
    totals,
    initialFileIds: initialFiles.map((file) => file.id),
    lazyFileIds: lazyFiles.map((file) => file.id),
    duplicateDependencies,
    heavyDependencies,
    mappingCoverage: {
      jsFiles: jsFiles.length,
      mappedJsFiles: mappedJs,
      cssFiles: cssFiles.length,
      mappedCssFiles: mappedCss,
      mappedPercent: jsFiles.length + cssFiles.length > 0
        ? Math.round(((mappedJs + mappedCss) / (jsFiles.length + cssFiles.length)) * 1000) / 10
        : 0,
    },
    ...(manifestUsed ? { manifestUsed } : {}),
    notes: [
      'Gzip uses level 9 and Brotli uses quality 9; measured values can differ from CDN defaults.',
      'Module byte attribution is approximate: each mapping segment spans generated code and does not represent guaranteed removable bytes.',
      'Initial/lazy classification comes from entry HTML and supported Vite/Next manifests. Unknown assets remain classified as lazy.',
      'Total raw/gzip/Brotli sizes are disjoint file sizes. Module and finding estimates are overlapping and must not be summed.',
    ],
  };

  return {
    report,
    findings,
    sourceMapIndexes: [...assetsByFile.values()]
      .map((asset) => asset.index)
      .filter((index): index is SourceMapIndex => index !== undefined && index.kind !== 'none'),
    warnings: [...new Set(warnings)],
    cssFiles: cssFiles.map((file) => file.file),
    jsFiles: jsFiles.map((file) => file.file),
  };
}
