import path from 'node:path';
import type { UsageReport } from '../types.js';
import { ensureDir, writeJsonFile, writeTextFile } from '../util/fs.js';
import { renderConsoleReport } from './console.js';
import { renderHtmlReport } from './html.js';

export interface WriteReportOptions {
  console?: boolean;
  json?: boolean;
  html?: boolean;
  openPath?: boolean;
}

export interface WrittenReports {
  consoleText: string;
  jsonPath?: string;
  htmlPath?: string;
}

export function writeReports(report: UsageReport, options: WriteReportOptions = {}): WrittenReports {
  const output = report.config.output;
  ensureDir(output);
  const consoleText = renderConsoleReport(report);
  let jsonPath: string | undefined;
  let htmlPath: string | undefined;
  const writeJson = options.json ?? report.config.reporters.json;
  const writeHtml = options.html ?? report.config.reporters.html;
  if (writeJson) {
    jsonPath = path.join(output, 'code-usage-map.json');
    writeJsonFile(jsonPath, report);
  }
  if (writeHtml) {
    htmlPath = path.join(output, 'code-usage-map.html');
    writeTextFile(htmlPath, renderHtmlReport(report));
  }
  return {
    consoleText,
    ...(jsonPath ? { jsonPath } : {}),
    ...(htmlPath ? { htmlPath } : {}),
  };
}

export function writeBaseline(report: UsageReport, file: string): string {
  const target = path.isAbsolute(file) ? file : path.resolve(report.project.root, file);
  writeJsonFile(target, report);
  return target;
}
