import path from 'node:path';
import { existsSync, readdirSync, unlinkSync } from 'node:fs';
import type { RuntimeSession } from './types.js';
import { RUNTIME_SESSION_SCHEMA } from './types.js';
import { ensureDir, readJsonFile, writeTextFile } from '../util/fs.js';

export function runtimeDirectory(root: string): string {
  return path.join(root, '.code-usage-map', 'runtime');
}

export function saveRuntimeSession(root: string, session: RuntimeSession): string {
  const dir = ensureDir(runtimeDirectory(root));
  const safeStamp = session.startedAt.replace(/[^0-9A-Za-z]/g, '-');
  const file = path.join(dir, `${safeStamp}-${session.id}.json`);
  writeTextFile(file, `${JSON.stringify(session)}\n`);
  return file;
}

export interface RuntimeLoadResult {
  sessions: RuntimeSession[];
  warnings: string[];
}

export function loadRuntimeSessions(root: string, signal?: AbortSignal): RuntimeLoadResult {
  const dir = runtimeDirectory(root);
  const warnings: string[] = [];
  const sessions: RuntimeSession[] = [];
  if (!existsSync(dir)) return { sessions, warnings };
  let entries: string[] = [];
  try {
    entries = readdirSync(dir).filter((name) => name.endsWith('.json')).sort();
  } catch {
    return { sessions, warnings: [`Could not read runtime sessions from ${dir}.`] };
  }
  for (const name of entries) {
    if (signal?.aborted) break;
    const file = path.join(dir, name);
    try {
      const session = readJsonFile<RuntimeSession>(file);
      if (session.schemaVersion !== RUNTIME_SESSION_SCHEMA) {
        warnings.push(`Skipped runtime session with unsupported schema: ${name}.`);
        continue;
      }
      if (!Array.isArray(session.visits)) {
        warnings.push(`Skipped malformed runtime session: ${name}.`);
        continue;
      }
      sessions.push(session);
    } catch (error) {
      warnings.push(`Skipped unreadable runtime session ${name}: ${error instanceof Error ? error.message : String(error)}`);
    }
  }
  sessions.sort((a, b) => a.startedAt.localeCompare(b.startedAt));
  return { sessions, warnings };
}

export function clearRuntimeSessions(root: string): number {
  const dir = runtimeDirectory(root);
  if (!existsSync(dir)) return 0;
  let removed = 0;
  for (const name of readdirSync(dir)) {
    if (!name.endsWith('.json')) continue;
    try {
      unlinkSync(path.join(dir, name));
      removed += 1;
    } catch {
      // Ignore files that cannot be removed.
    }
  }
  return removed;
}
