import path from 'node:path';

export type SfcKind = 'vue' | 'svelte' | 'astro';
export type SfcScriptLanguage = 'js' | 'ts' | 'jsx' | 'tsx';

export interface SfcScriptBlock {
  content: string;
  /** Absolute offset of content in the original file. */
  startOffset: number;
  /** 1-based line of the first content character. */
  startLine: number;
  language: SfcScriptLanguage;
  setup: boolean;
  contextModule: boolean;
  tag: 'script' | 'frontmatter';
}

export interface SfcStyleBlock {
  content: string;
  startOffset: number;
  startLine: number;
  language: 'css' | 'scss' | 'sass' | 'less';
  module: boolean;
  scoped: boolean;
}

export interface SfcExtraction {
  kind: SfcKind;
  scripts: SfcScriptBlock[];
  styles: SfcStyleBlock[];
  /** Original markup with script/style/frontmatter content replaced by spaces. */
  templateText: string;
  /** Combined script content in original-position space, used for TS analysis. */
  virtualContent?: string;
  virtualPath?: string;
  scriptKind: 'ts' | 'tsx' | 'js' | 'jsx';
}

interface TagMatch {
  attrs: string;
  content: string;
  contentStart: number;
  contentEnd: number;
  tagStart: number;
  tagEnd: number;
}

function lineAt(content: string, offset: number): number {
  let line = 1;
  for (let index = 0; index < offset && index < content.length; index += 1) {
    if (content.charCodeAt(index) === 10) line += 1;
  }
  return line;
}

function findTags(content: string, tag: 'script' | 'style'): TagMatch[] {
  const matches: TagMatch[] = [];
  const expression = new RegExp(`<${tag}\\b([^>]*)>([\\s\\S]*?)<\\/${tag}\\s*>`, 'gi');
  let match: RegExpExecArray | null;
  while ((match = expression.exec(content)) !== null) {
    const attrs = match[1] ?? '';
    const body = match[2] ?? '';
    const contentStart = (match.index ?? 0) + match[0].indexOf('>') + 1;
    matches.push({
      attrs,
      content: body,
      contentStart,
      contentEnd: contentStart + body.length,
      tagStart: match.index ?? 0,
      tagEnd: (match.index ?? 0) + match[0].length,
    });
  }
  return matches;
}

function attrValue(attrs: string, name: string): string | undefined {
  const match = new RegExp(`\\b${name}\\s*=\\s*(?:"([^"]*)"|'([^']*)'|([^\\s>]+))`, 'i').exec(attrs);
  return match?.[1] ?? match?.[2] ?? match?.[3];
}

function hasAttr(attrs: string, name: string): boolean {
  return new RegExp(`(?:^|\\s)${name}(?:\\s|=|$)`, 'i').test(attrs);
}

function maskRanges(content: string, keepRanges: Array<{ start: number; end: number }>): string {
  const sorted = [...keepRanges].sort((a, b) => a.start - b.start);
  const result: string[] = [];
  let cursor = 0;
  const blank = (segment: string): string => segment.replace(/[^\r\n]/g, ' ');
  for (const range of sorted) {
    if (range.start > cursor) result.push(blank(content.slice(cursor, range.start)));
    result.push(content.slice(range.start, range.end));
    cursor = Math.max(cursor, range.end);
  }
  if (cursor < content.length) result.push(blank(content.slice(cursor)));
  return result.join('');
}

function languageFromAttrs(
  attrs: string,
  fallback: SfcScriptLanguage,
  kind: SfcKind,
): SfcScriptLanguage {
  const lang = attrValue(attrs, 'lang')?.toLowerCase();
  if (lang === 'ts' || lang === 'typescript') return hasAttr(attrs, 'setup') || kind === 'astro' ? 'ts' : 'ts';
  if (lang === 'tsx') return 'tsx';
  if (lang === 'jsx') return 'jsx';
  if (lang === 'js' || lang === 'javascript') return 'js';
  return fallback;
}

function scriptKindFrom(languages: SfcScriptLanguage[]): 'ts' | 'tsx' | 'js' | 'jsx' {
  if (languages.includes('tsx')) return 'tsx';
  if (languages.includes('ts')) return 'ts';
  if (languages.includes('jsx')) return 'jsx';
  return 'js';
}

function virtualExtension(kind: 'ts' | 'tsx' | 'js' | 'jsx'): string {
  if (kind === 'tsx') return '.tsx';
  if (kind === 'ts') return '.ts';
  if (kind === 'jsx') return '.jsx';
  return '.js';
}

/**
 * Extracts script/style blocks from Vue, Svelte and Astro single-file
 * components without introducing framework-specific dependencies. Line
 * positions in the virtual script are identical to the original file.
 */
export function extractSfc(file: string, content: string): SfcExtraction | undefined {
  const extension = path.extname(file).toLowerCase();
  let kind: SfcKind | undefined;
  if (extension === '.vue') kind = 'vue';
  else if (extension === '.svelte') kind = 'svelte';
  else if (extension === '.astro') kind = 'astro';
  if (!kind) return undefined;

  const scripts: SfcScriptBlock[] = [];
  const styles: SfcStyleBlock[] = [];
  const maskRangesToKeep: Array<{ start: number; end: number }> = [];

  // Astro frontmatter is TypeScript/JavaScript executed at build time.
  if (kind === 'astro') {
    const frontmatter = /^(?:\uFEFF)?\s*---\s*\r?\n([\s\S]*?)\r?\n---\s*(?:\r?\n|$)/.exec(content);
    if (frontmatter) {
      const body = frontmatter[1] ?? '';
      const bodyStart = (frontmatter.index ?? 0) + frontmatter[0].indexOf(body);
      scripts.push({
        content: body,
        startOffset: bodyStart,
        startLine: lineAt(content, bodyStart),
        language: 'ts',
        setup: false,
        contextModule: false,
        tag: 'frontmatter',
      });
      maskRangesToKeep.push({ start: bodyStart, end: bodyStart + body.length });
    }
  }

  for (const tag of findTags(content, 'script')) {
    const isContext = hasAttr(tag.attrs, 'context') && /context\s*=\s*["']module["']/i.test(tag.attrs);
    const language = languageFromAttrs(tag.attrs, kind === 'astro' ? 'ts' : 'js', kind);
    scripts.push({
      content: tag.content,
      startOffset: tag.contentStart,
      startLine: lineAt(content, tag.contentStart),
      language,
      setup: hasAttr(tag.attrs, 'setup'),
      contextModule: isContext,
      tag: 'script',
    });
    maskRangesToKeep.push({ start: tag.contentStart, end: tag.contentEnd });
  }

  for (const tag of findTags(content, 'style')) {
    const lang = attrValue(tag.attrs, 'lang')?.toLowerCase();
    let language: SfcStyleBlock['language'] = 'css';
    if (lang === 'scss') language = 'scss';
    else if (lang === 'sass') language = 'sass';
    else if (lang === 'less') language = 'less';
    styles.push({
      content: tag.content,
      startOffset: tag.contentStart,
      startLine: lineAt(content, tag.contentStart),
      language,
      module: hasAttr(tag.attrs, 'module'),
      scoped: hasAttr(tag.attrs, 'scoped'),
    });
  }

  const scriptRanges = [
    ...findTags(content, 'script').map((tag) => ({ start: tag.tagStart, end: tag.tagEnd })),
    ...findTags(content, 'style').map((tag) => ({ start: tag.tagStart, end: tag.tagEnd })),
  ];
  if (kind === 'astro') {
    const frontmatter = /^(?:\uFEFF)?\s*---\s*\r?\n[\s\S]*?\r?\n---\s*(?:\r?\n|$)/.exec(content);
    if (frontmatter) scriptRanges.push({ start: frontmatter.index ?? 0, end: (frontmatter.index ?? 0) + frontmatter[0].length });
  }
  const templateText = maskRanges(content, invertRanges(content.length, scriptRanges));

  const languages = scripts.map((block) => block.language);
  const scriptKind = scriptKindFrom(languages.length > 0 ? languages : ['js']);
  const virtualContent = maskRanges(content, maskRangesToKeep);
  const hasCode = scripts.some((block) => block.content.trim() !== '');
  const result: SfcExtraction = {
    kind,
    scripts,
    styles,
    templateText,
    scriptKind,
  };
  if (hasCode) {
    result.virtualContent = virtualContent;
    result.virtualPath = `${path.normalize(file)}.cum${virtualExtension(scriptKind)}`;
  }
  return result;
}

function invertRanges(length: number, removed: Array<{ start: number; end: number }>): Array<{ start: number; end: number }> {
  const sorted = [...removed].sort((a, b) => a.start - b.start);
  const kept: Array<{ start: number; end: number }> = [];
  let cursor = 0;
  for (const range of sorted) {
    if (range.start > cursor) kept.push({ start: cursor, end: range.start });
    cursor = Math.max(cursor, range.end);
  }
  if (cursor < length) kept.push({ start: cursor, end: length });
  return kept;
}

export function templateIdentifiers(template: string): Set<string> {
  const identifiers = new Set<string>();
  const expression =
    /\b(?:[A-Za-z_$][\w$]*)(?:\s*(?:\.|\[)[^\]\n}]*)?|\b(?:v-[\w-]+|on[A-Z][\w]*|@[\w-]+)\b/g;
  for (const match of template.matchAll(expression)) {
    const raw = match[0] ?? '';
    const name = raw.split(/[.[\s]/)[0] ?? '';
    if (name.length > 1) identifiers.add(name);
  }
  return identifiers;
}
