import path from 'node:path';
import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { AnyMap, decodedMappings, originalPositionFor } from '@jridgewell/trace-mapping';
import type { ModuleAttribution, SourceMapReport } from '../types.js';
import { hashString, toPosix } from '../util/fs.js';

export interface ResolvedSourceInfo {
  raw: string;
  display: string;
  file?: string;
  packageName?: string;
  version?: string;
  isNodeModules: boolean;
}

export interface ReverseMappingEntry {
  generatedLine: number;
  generatedColumn: number;
  originalLine: number;
  originalColumn: number;
  name?: string;
}

export interface SourceMapIndex {
  generatedFile: string;
  sourceMapFile?: string;
  kind: 'external' | 'inline' | 'indexed' | 'none';
  map?: InstanceType<typeof AnyMap>;
  sources: ResolvedSourceInfo[];
  reverseByKey: Map<string, ReverseMappingEntry[]>;
  attribution: ModuleAttribution[];
  mappedBytes: number;
  totalBytes: number;
  warnings: string[];
}

interface LoadedSourceMap {
  json: Record<string, unknown>;
  mapFile?: string;
  kind: 'external' | 'inline' | 'indexed';
}

function readSourceMapUrl(text: string, extension: 'js' | 'css'): string | undefined {
  if (extension === 'js') {
    const matches = [...text.matchAll(/\/\/[#@]\s*sourceMappingURL=([^\s'"]+)/g)];
    return matches[matches.length - 1]?.[1];
  }
  const matches = [...text.matchAll(/\/\*[#@]\s*sourceMappingURL=([^*\s]+)\s*\*\//g)];
  return matches[matches.length - 1]?.[1];
}

function decodeDataUri(uri: string): string {
  const comma = uri.indexOf(',');
  if (comma < 0) throw new Error('Malformed source map data URI.');
  const header = uri.slice(0, comma);
  const payload = uri.slice(comma + 1);
  if (/;base64/i.test(header)) return Buffer.from(payload, 'base64').toString('utf8');
  return decodeURIComponent(payload);
}

export function loadSourceMapFromFile(
  generatedFile: string,
  text: string,
  root: string,
  warnings: string[],
  maxMappingsPerFile = 250_000,
): SourceMapIndex {
  const extension = path.extname(generatedFile).toLowerCase() === '.css' ? 'css' : 'js';
  const url = readSourceMapUrl(text, extension);
  const baseIndex: SourceMapIndex = {
    generatedFile,
    kind: 'none',
    sources: [],
    reverseByKey: new Map(),
    attribution: [],
    mappedBytes: 0,
    totalBytes: Buffer.byteLength(text, 'utf8'),
    warnings: [],
  };
  if (!url) return baseIndex;

  let loaded: LoadedSourceMap | undefined;
  try {
    if (url.startsWith('data:')) {
      const json = JSON.parse(decodeDataUri(url)) as Record<string, unknown>;
      loaded = { json, kind: 'inline' };
    } else if (/^https?:/i.test(url)) {
      warnings.push(`Remote source map ignored for offline analysis: ${url}`);
      return baseIndex;
    } else {
      const clean = url.replace(/[?#].*$/, '');
      const mapFile = path.resolve(path.dirname(generatedFile), decodeURIComponent(clean));
      if (!existsSync(mapFile)) {
        warnings.push(`Source map not found: ${mapFile}`);
        return baseIndex;
      }
      const raw = readFileSync(mapFile, 'utf8');
      const json = JSON.parse(raw) as Record<string, unknown>;
      loaded = { json, mapFile, kind: 'external' };
    }
  } catch (error) {
    warnings.push(
      `Failed to load source map for ${path.basename(generatedFile)}: ${error instanceof Error ? error.message : String(error)}`,
    );
    return baseIndex;
  }

  const indexed = Array.isArray(loaded.json.sections);
  const mapUrl = pathToFileURL(loaded.mapFile ?? generatedFile).href;
  let map: InstanceType<typeof AnyMap>;
  try {
    map = new AnyMap(
      loaded.json as unknown as ConstructorParameters<typeof AnyMap>[0],
      mapUrl,
    );
  } catch (error) {
    warnings.push(
      `Failed to parse source map for ${path.basename(generatedFile)}: ${error instanceof Error ? error.message : String(error)}`,
    );
    return baseIndex;
  }

  const sources = resolveSources(map, root);
  const sourceByIndex = new Map<number, ResolvedSourceInfo>();
  sources.forEach((source, index) => sourceByIndex.set(index, source));
  const reverseByKey = new Map<string, ReverseMappingEntry[]>();
  const attribution = new Map<string, { source: ResolvedSourceInfo; bytes: number; segments: number }>();
  let mappedBytes = 0;

  const lineStarts: number[] = [0];
  for (let index = 0; index < text.length; index += 1) {
    if (text.charCodeAt(index) === 10) lineStarts.push(index + 1);
  }

  let mappingsTruncated = false;
  try {
    const decoded = decodedMappings(map);
    const maxSegments = Math.max(100, maxMappingsPerFile);
    let visited = 0;
    for (let lineIndex = 0; lineIndex < decoded.length; lineIndex += 1) {
      const segments = decoded[lineIndex];
      if (!segments) continue;
      for (let segmentIndex = 0; segmentIndex < segments.length; segmentIndex += 1) {
        const segment = segments[segmentIndex];
        if (!segment) continue;
        visited += 1;
        if (visited > maxSegments) {
          mappingsTruncated = true;
          break;
        }
        const generatedColumn = segment[0] ?? 0;
        const sourceIndex = segment[1];
        const originalLine = segment[2];
        const originalColumn = segment[3];
        if (sourceIndex === undefined || originalLine === undefined || originalColumn === undefined) {
          continue;
        }
        const source = sourceByIndex.get(sourceIndex);
        if (!source) continue;
        const nameIndex = segment[4];
        const name = nameIndex !== undefined ? map.names[nameIndex] : undefined;
        const generatedLine = lineIndex + 1;
        const original1BasedLine = originalLine + 1;
        const entry: ReverseMappingEntry = {
          generatedLine,
          generatedColumn: generatedColumn + 1,
          originalLine: original1BasedLine,
          originalColumn: originalColumn + 1,
          ...(name ? { name } : {}),
        };
        for (const key of [source.display, source.file].filter((value): value is string => Boolean(value))) {
          const existing = reverseByKey.get(key) ?? [];
          // Keep reverse maps bounded and focused on useful near-line positions.
          if (existing.length < 20_000) existing.push(entry);
          reverseByKey.set(key, existing);
        }

        const lineStart = lineStarts[lineIndex] ?? 0;
        const nextSegment = segments[segmentIndex + 1];
        const nextColumn = nextSegment?.[0] ?? (text.slice(lineStart).split('\n')[0]?.length ?? 0);
        const startOffset = lineStart + generatedColumn;
        const endOffset = lineStart + Math.max(generatedColumn + 1, nextColumn);
        const bytes = Math.max(0, Math.min(endOffset, text.length) - Math.min(startOffset, text.length));
        const current = attribution.get(source.display) ?? { source, bytes: 0, segments: 0 };
        current.bytes += bytes;
        current.segments += 1;
        attribution.set(source.display, current);
        mappedBytes += bytes;
      }
      if (visited > maxSegments) break;
    }
  } catch (error) {
    warnings.push(
      `Failed to decode mappings for ${path.basename(generatedFile)}: ${error instanceof Error ? error.message : String(error)}`,
    );
  }
  if (mappingsTruncated) {
    warnings.push(
      `Mappings truncated after ${maxMappingsPerFile} segments for ${path.basename(generatedFile)}. Increase sourceMaps.maxMappingsPerFile for complete attribution.`,
    );
  }

  for (const entry of reverseByKey.values()) {
    entry.sort((a, b) => a.originalLine - b.originalLine || a.originalColumn - b.originalColumn);
  }

  const modules: ModuleAttribution[] = [...attribution.values()]
    .map((item) => ({
      sourceFile: item.source.display,
      ...(item.source.packageName ? { packageName: item.source.packageName } : {}),
      ...(item.source.version ? { version: item.source.version } : {}),
      bytes: item.bytes,
      mappingSegments: item.segments,
    }))
    .sort((a, b) => b.bytes - a.bytes);

  return {
    generatedFile,
    ...(loaded.mapFile ? { sourceMapFile: loaded.mapFile } : {}),
    kind: indexed ? 'indexed' : loaded.kind,
    map,
    sources,
    reverseByKey,
    attribution: modules,
    mappedBytes,
    totalBytes: Buffer.byteLength(text, 'utf8'),
    warnings: [],
  };
}

function resolveSources(map: InstanceType<typeof AnyMap>, root: string): ResolvedSourceInfo[] {
  const resolved = map.resolvedSources ?? [];
  return resolved.map((resolvedSource, index) => {
    const raw = map.sources[index] ?? resolvedSource;
    return resolveSourceInfo(raw, resolvedSource, root);
  });
}

export function packageFromSource(source: string): { packageName?: string; version?: string; isNodeModules: boolean } {
  const normalized = source.replaceAll('\\', '/');
  const lastNodeModules = normalized.lastIndexOf('node_modules/');
  if (lastNodeModules < 0) return { isNodeModules: false };
  const tail = normalized.slice(lastNodeModules + 'node_modules/'.length);
  const workspaceIndex = tail.indexOf('/node_modules/');
  const packagePath = workspaceIndex >= 0 ? tail.slice(0, workspaceIndex) : tail;
  const segments = packagePath.split('/');
  if (segments[0]?.startsWith('@') && segments[1]) {
    return {
      packageName: `${segments[0]}/${segments[1]}`,
      isNodeModules: true,
    };
  }
  // pnpm paths include the version after the package name.
  const pnpm = /(?:^|\/)(?:@([^/]+)\/)?([^/@]+)@([^/]+)/.exec(packagePath);
  if (segments[0]) {
    return {
      packageName: segments[0],
      ...(pnpm?.[3] ? { version: pnpm[3] } : {}),
      isNodeModules: true,
    };
  }
  return { isNodeModules: true };
}

function cleanVirtualSource(source: string): string {
  let value = source;
  value = value.replace(/^(?:webpack|webpack-internal|vite|rollup|turbopack|meteor|ng|file):\/\//i, '');
  value = value.replace(/^\/+/, '');
  value = value.replace(/^(?:\.\/)+/, '');
  value = value.replace(/[?#].*$/, '');
  return value;
}

export function resolveSourceInfo(raw: string, resolved: string, root: string): ResolvedSourceInfo {
  const packageInfo = packageFromSource(raw.includes('node_modules') ? raw : resolved);
  let absolute: string | undefined;
  let display = raw;

  const candidates: string[] = [];
  if (resolved.startsWith('file://')) {
    try {
      candidates.push(fileURLToPath(resolved));
    } catch {
      // Ignore invalid file URLs.
    }
  }
  for (const candidate of [resolved, raw]) {
    if (!candidate) continue;
    const cleaned = cleanVirtualSource(candidate);
    if (/^[A-Za-z]:[\\/]/.test(cleaned) || cleaned.startsWith('/')) {
      candidates.push(path.normalize(cleaned));
    } else {
      candidates.push(path.resolve(root, cleaned));
    }
  }

  for (const candidate of candidates) {
    if (existsSync(candidate)) {
      absolute = path.normalize(candidate);
      break;
    }
  }
  if (!absolute) {
    for (const candidate of candidates) {
      const normalizedCandidate = toPosix(candidate);
      if (existsSync(normalizedCandidate)) {
        absolute = path.normalize(normalizedCandidate);
        break;
      }
    }
  }

  if (absolute && absolute.startsWith(root)) {
    display = toPosix(path.relative(root, absolute));
  } else {
    const cleaned = cleanVirtualSource(raw);
    display = cleaned.includes('node_modules/') ? cleaned.slice(cleaned.lastIndexOf('node_modules/')) : cleaned;
    if (!display) display = resolved;
  }

  const fromDisplay = packageFromSource(display);
  return {
    raw,
    display,
    ...(absolute ? { file: absolute } : {}),
    ...(fromDisplay.packageName ?? packageInfo.packageName
      ? { packageName: fromDisplay.packageName ?? packageInfo.packageName }
      : {}),
    ...(fromDisplay.version ?? packageInfo.version
      ? { version: fromDisplay.version ?? packageInfo.version }
      : {}),
    isNodeModules: fromDisplay.isNodeModules || packageInfo.isNodeModules,
  };
}

export interface FindingMappingLookup {
  generatedFile: string;
  generatedLine: number;
  generatedColumn: number;
  precision: 'symbol' | 'line-column' | 'line' | 'file';
  entry?: ReverseMappingEntry;
}

export function findGeneratedPosition(
  index: SourceMapIndex,
  sourceKeys: string[],
  originalLine: number,
  symbol: string | undefined,
): FindingMappingLookup | undefined {
  const entries: ReverseMappingEntry[] = [];
  for (const key of sourceKeys) {
    const found = index.reverseByKey.get(key);
    if (found) entries.push(...found);
  }
  if (entries.length > 0) {
    if (symbol) {
      const named = entries
        .filter((entry) => entry.name === symbol)
        .sort(
          (a, b) =>
            Math.abs(a.originalLine - originalLine) - Math.abs(b.originalLine - originalLine) ||
            a.generatedLine - b.generatedLine,
        )[0];
      if (named) {
        return {
          generatedFile: index.generatedFile,
          generatedLine: named.generatedLine,
          generatedColumn: named.generatedColumn,
          precision: 'symbol',
          entry: named,
        };
      }
    }
    let best: ReverseMappingEntry | undefined;
    let bestDistance = Number.POSITIVE_INFINITY;
    for (const entry of entries) {
      const distance = Math.abs(entry.originalLine - originalLine);
      if (distance < bestDistance) {
        best = entry;
        bestDistance = distance;
      } else if (distance === bestDistance && entry.generatedLine < (best?.generatedLine ?? Number.POSITIVE_INFINITY)) {
        best = entry;
      }
    }
    if (best) {
      if (bestDistance === 0) {
        return {
          generatedFile: index.generatedFile,
          generatedLine: best.generatedLine,
          generatedColumn: best.generatedColumn,
          precision: symbol && best.name === symbol ? 'symbol' : 'line-column',
          entry: best,
        };
      }
      if (bestDistance <= 3) {
        return {
          generatedFile: index.generatedFile,
          generatedLine: best.generatedLine,
          generatedColumn: best.generatedColumn,
          precision: 'line',
          entry: best,
        };
      }
      return {
        generatedFile: index.generatedFile,
        generatedLine: best.generatedLine,
        generatedColumn: best.generatedColumn,
        precision: 'file',
        entry: best,
      };
    }
  }
  const attributed = index.attribution.find((item) =>
    sourceKeys.some(
      (key) => item.sourceFile === key || item.sourceFile.endsWith(key) || key.endsWith(item.sourceFile),
    ),
  );
  if (!attributed) return undefined;
  return {
    generatedFile: index.generatedFile,
    generatedLine: 1,
    generatedColumn: 1,
    precision: 'file',
  };
}

export function mapGeneratedToOriginal(
  index: SourceMapIndex,
  line: number,
  column: number,
  root: string,
): { source: ResolvedSourceInfo; line: number; column: number } | undefined {
  if (!index.map) return undefined;
  try {
    const mapped = originalPositionFor(index.map, { line, column });
    if (mapped.line === null || mapped.source === null) return undefined;
    const source = resolveSourceInfo(mapped.source, mapped.source, root);
    return {
      source,
      line: mapped.line,
      column: (mapped.column ?? 0) + 1,
    };
  } catch {
    return undefined;
  }
}

export function buildSourceMapReport(indexes: SourceMapIndex[], mappedFindings: number, totalMappedFindings: number): SourceMapReport {
  const jsFiles = indexes.filter((index) => path.extname(index.generatedFile).toLowerCase() !== '.css').length;
  const filesWithSourceMaps = indexes.filter((index) => index.kind !== 'none').length;
  const inlineMaps = indexes.filter((index) => index.kind === 'inline').length;
  const externalMaps = indexes.filter((index) => index.kind === 'external').length;
  const indexedMaps = indexes.filter((index) => index.kind === 'indexed').length;
  return {
    enabled: true,
    jsFiles,
    filesWithSourceMaps,
    inlineMaps,
    externalMaps,
    indexedMaps,
    resolvedFindings: mappedFindings,
    unresolvedFindings: Math.max(0, totalMappedFindings - mappedFindings),
    precision: { symbol: 0, lineColumn: 0, line: 0, file: 0 },
    notes: [
      'Precision is reported per finding. Symbol-level mapping requires a source map names table and a matching symbol.',
      'Remote HTTP source maps are intentionally ignored; analysis stays local and offline.',
      `Index fingerprint: ${hashString(indexes.map((index) => path.basename(index.generatedFile)).join('|'), 12)}`,
    ],
  };
}
