import { existsSync, statSync } from 'node:fs';
import path from 'node:path';
import fg from 'fast-glob';
import type { ResolvedCodeUsageMapConfig } from '../types.js';
import type { ProjectDetection } from '../integrations/detect.js';
import { toPosix } from '../util/fs.js';

const ALL_SOURCE_EXTENSIONS = '{js,jsx,mjs,cjs,ts,tsx,mts,cts,css,scss,sass,less,html,htm,vue,svelte,astro}';

export interface SourceCollection {
  root: string;
  files: string[];
  scripts: string[];
  styles: string[];
  templates: string[];
  html: string[];
  fileSet: Set<string>;
  sourceRoots: string[];
  buildDirs: string[];
}

const IGNORED_SEGMENTS = new Set([
  'node_modules',
  '.git',
  '.hg',
  '.svn',
  'coverage',
  '.nyc_output',
  '.cache',
  '.turbo',
  '.parcel-cache',
  '.vite',
]);

export function isTestOrStoryFile(file: string): boolean {
  const normalized = toPosix(file).toLowerCase();
  return (
    /\.(test|spec|stories|story)\.[^.]+$/.test(normalized) ||
    normalized.includes('/__tests__/') ||
    normalized.includes('/__mocks__/') ||
    normalized.includes('/tests/') ||
    normalized.includes('/test/') ||
    normalized.includes('/e2e/')
  );
}

export function isDeclarationFile(file: string): boolean {
  return /\.d\.(ts|mts|cts)$/i.test(file);
}

export function isMinifiedFile(file: string): boolean {
  return /\.min\.(js|mjs|cjs|css)$/i.test(file) || /[.-][a-z0-9]{8,}\.(js|css)$/i.test(path.basename(file));
}

export function scriptLikeFile(file: string): boolean {
  return /\.(js|jsx|mjs|cjs|ts|tsx|mts|cts|vue|svelte|astro)$/i.test(file);
}

export function styleLikeFile(file: string): boolean {
  return /\.(css|scss|sass|less)$/i.test(file);
}

export function templateLikeFile(file: string): boolean {
  return /\.(html?|vue|svelte|astro)$/i.test(file);
}

function globForDirectory(root: string, dir: string): string {
  const relative = toPosix(path.relative(root, dir)) || '.';
  return relative === '.' ? `**/*.${ALL_SOURCE_EXTENSIONS}` : `${relative}/**/*.${ALL_SOURCE_EXTENSIONS}`;
}

function excludeGlobs(config: ResolvedCodeUsageMapConfig, detectedBuildDirs: string[]): string[] {
  const ignores = new Set<string>([
    ...config.exclude,
    '**/.git/**',
    '**/coverage/**',
    '**/.nyc_output/**',
    '**/.code-usage-map/**',
  ]);
  const excludeAbsolute = (dir: string): void => {
    if (!existsSync(dir)) return;
    const relative = toPosix(path.relative(config.root, dir));
    if (relative === '' || relative.startsWith('..')) return;
    ignores.add(`${relative}/**`);
  };
  excludeAbsolute(config.output);
  if (config.cache.dir) excludeAbsolute(config.cache.dir);
  for (const buildDir of config.build.dir ?? []) excludeAbsolute(buildDir);
  for (const buildDir of detectedBuildDirs) excludeAbsolute(buildDir);
  return [...ignores];
}

/**
 * Collects project source files. Build output is excluded from source analysis
 * when it overlaps a source root, but remains available to the bundle engine.
 */
export function collectSourceFiles(
  config: ResolvedCodeUsageMapConfig,
  detection: ProjectDetection,
): SourceCollection {
  const patterns: string[] = [];
  const directFiles: string[] = [];

  for (const source of config.source) {
    if (!existsSync(source)) continue;
    let isFile = false;
    try {
      isFile = statSync(source).isFile();
    } catch {
      isFile = false;
    }
    if (isFile) {
      directFiles.push(path.normalize(source));
    } else {
      patterns.push(globForDirectory(config.root, source));
    }
  }
  patterns.push(...config.include);
  if (patterns.length === 0) patterns.push(`**/*.${ALL_SOURCE_EXTENSIONS}`);

  const ignore = excludeGlobs(config, detection.buildDirs);
  let files: string[] = [];
  try {
    files = fg.sync(patterns, {
      cwd: config.root,
      absolute: true,
      onlyFiles: true,
      unique: true,
      dot: false,
      followSymbolicLinks: false,
      ignore,
    }).map((file) => path.normalize(file));
  } catch {
    files = [];
  }
  for (const file of directFiles) {
    if (!files.includes(file)) files.push(file);
  }

  // Root HTML entry points and public HTML are part of the application even
  // when source analysis is scoped to src/.
  try {
    const extraHtml = fg.sync(['*.html', '*.htm', 'public/**/*.html', 'public/**/*.htm'], {
      cwd: config.root,
      absolute: true,
      onlyFiles: true,
      unique: true,
      dot: false,
      ignore,
    }).map((file) => path.normalize(file));
    for (const file of extraHtml) {
      if (!files.includes(file)) files.push(file);
    }
  } catch {
    // Keep the source-only file list if the extra entry scan fails.
  }

  const filtered = files.filter((file) => {
    const segments = toPosix(path.relative(config.root, file)).split('/');
    if (segments.some((segment) => IGNORED_SEGMENTS.has(segment))) return false;
    if (config.output && (file === config.output || file.startsWith(`${config.output}${path.sep}`))) return false;
    if (config.cache.dir && file.startsWith(`${config.cache.dir}${path.sep}`)) return false;
    return true;
  });

  const scripts = filtered.filter(scriptLikeFile);
  const styles = filtered.filter(styleLikeFile);
  const templates = filtered.filter(templateLikeFile);
  const html = filtered.filter((file) => /\.html?$/i.test(file));

  return {
    root: config.root,
    files: filtered,
    scripts,
    styles,
    templates,
    html,
    fileSet: new Set(filtered),
    sourceRoots: detection.sourceRoots,
    buildDirs: detection.buildDirs,
  };
}

export function normalizeSourcePath(root: string, file: string): string {
  return toPosix(path.relative(root, file));
}
