import path from 'node:path';
import type { BundleReport, Finding, MappingHop, SourceMapReport } from '../types.js';
import {
  buildSourceMapReport,
  findGeneratedPosition,
  type SourceMapIndex,
} from './parse.js';
import { toPosix } from '../util/fs.js';

const JS_CATEGORIES = new Set([
  'unused-import',
  'unused-export',
  'unused-variable',
  'unused-function',
  'unused-class',
  'unused-class-method',
  'unused-type',
  'unused-enum-member',
  'unused-type-parameter',
  'unused-decorator',
  'unused-event-handler',
  'unreachable-code',
  'unused-type-only-import',
  'circular-dependency',
  'duplicate-code',
  'unused-module',
  'tree-shaking-opportunity',
]);

const CSS_CATEGORIES = new Set([
  'unused-css-selector',
  'unused-css-declaration',
  'duplicate-css-selector',
  'duplicate-css-rule',
  'unused-css-custom-property',
  'unused-stylesheet',
  'css-specificity',
]);

function sourceMatches(moduleSource: string, finding: Finding): boolean {
  const keys = [finding.location.relativeFile, finding.location.file, toPosix(finding.location.file)];
  return keys.some(
    (key) =>
      moduleSource === key ||
      moduleSource.endsWith(`/${key}`) ||
      key.endsWith(moduleSource) ||
      toPosix(moduleSource).endsWith(`/${finding.location.relativeFile}`),
  );
}

function indexScore(index: SourceMapIndex, finding: Finding): number {
  let score = 0;
  for (const module of index.attribution) {
    if (sourceMatches(module.sourceFile, finding)) score += module.bytes;
  }
  if (index.reverseByKey.has(finding.location.relativeFile)) score += 1_000_000;
  if (index.reverseByKey.has(finding.location.file)) score += 1_000_000;
  return score;
}

function mappingChain(finding: Finding, generatedFile: string, root: string): MappingHop[] {
  const relativeGenerated = toPosix(path.relative(root, generatedFile));
  return [
    { kind: 'bundle', label: relativeGenerated, file: generatedFile },
    { kind: 'chunk', label: path.basename(generatedFile), file: generatedFile },
    {
      kind: 'module',
      label:
        finding.css?.stylesheet ??
        finding.location.relativeFile,
    },
    {
      kind: 'source',
      label: finding.location.relativeFile,
      file: finding.location.file,
      line: finding.location.line,
      column: finding.location.column,
    },
    ...(finding.symbol
      ? [
          {
            kind: 'symbol' as const,
            label: finding.parent ? `${finding.parent}.${finding.symbol}` : finding.symbol,
            file: finding.location.file,
            line: finding.location.line,
            column: finding.location.column,
          },
        ]
      : []),
  ];
}

export interface MappingAttachmentSummary {
  mappedFindings: number;
  eligibleFindings: number;
  precision: SourceMapReport['precision'];
}

/**
 * Maps findings back through bundle source maps. A finding keeps its original
 * source location; the mapping adds the generated chunk position and chain.
 */
export function attachSourceMappings(
  findings: Finding[],
  indexes: SourceMapIndex[],
  bundle: BundleReport,
  root: string,
): MappingAttachmentSummary {
  const precision: SourceMapReport['precision'] = { symbol: 0, lineColumn: 0, line: 0, file: 0 };
  let mappedFindings = 0;
  let eligibleFindings = 0;

  const routeMap = new Map<string, Set<string>>();
  for (const file of bundle.files) {
    for (const module of file.modules) {
      const key = toPosix(module.sourceFile);
      const routes = routeMap.get(key) ?? new Set<string>();
      for (const route of file.routes) routes.add(route);
      routeMap.set(key, routes);
    }
  }

  for (const finding of findings) {
    const isJs = JS_CATEGORIES.has(finding.category);
    const isCss = CSS_CATEGORIES.has(finding.category);
    if (!isJs && !isCss) continue;
    eligibleFindings += 1;

    const candidates = indexes
      .filter((index) => {
        const extension = path.extname(index.generatedFile).toLowerCase();
        if (isCss) return extension === '.css';
        return extension !== '.css';
      })
      .map((index) => ({ index, score: indexScore(index, finding) }))
      .filter((item) => item.score > 0)
      .sort((a, b) => b.score - a.score);

    for (const [key, routes] of routeMap) {
      if (sourceMatches(key, finding)) {
        for (const route of routes) {
          if (!finding.routeHints.includes(route)) finding.routeHints.push(route);
        }
      }
    }

    const best = candidates[0];
    if (!best) continue;
    const lookup = findGeneratedPosition(
      best.index,
      [finding.location.relativeFile, finding.location.file],
      finding.location.line,
      finding.symbol,
    );
    if (!lookup) continue;

    const sourceFile = best.index.generatedFile;
    finding.mapping = {
      precision: lookup.precision,
      generatedFile: sourceFile,
      generatedLine: lookup.generatedLine,
      generatedColumn: lookup.generatedColumn,
      originalFile: finding.location.file,
      originalLine: finding.location.line,
      originalColumn: finding.location.column,
      ...(best.index.sourceMapFile ? { sourceMapFile: best.index.sourceMapFile } : {}),
      chunk: path.basename(sourceFile),
      chain: mappingChain(finding, sourceFile, root),
      ...(lookup.precision === 'file'
        ? { limitation: 'Only file-level attribution was available for this finding.' }
        : lookup.precision === 'line'
          ? { limitation: 'Nearest mapping lines were used; generated column is approximate.' }
          : {}),
    };

    const routesForGenerated = bundle.files.find((file) => file.file === sourceFile)?.routes ?? [];
    for (const route of routesForGenerated) {
      if (!finding.routeHints.includes(route)) finding.routeHints.push(route);
    }

    mappedFindings += 1;
    if (finding.mapping.precision === 'symbol') precision.symbol += 1;
    else if (finding.mapping.precision === 'line-column') precision.lineColumn += 1;
    else if (finding.mapping.precision === 'line') precision.line += 1;
    else precision.file += 1;
  }

  for (const finding of findings) {
    if (finding.routeHints.length > 0) finding.routeHints.sort();
  }

  return { mappedFindings, eligibleFindings, precision };
}

export function createSourceMapReport(
  indexes: SourceMapIndex[],
  summary: MappingAttachmentSummary,
  enabled: boolean,
): SourceMapReport {
  const base = buildSourceMapReport(indexes, summary.mappedFindings, summary.eligibleFindings);
  return {
    ...base,
    enabled,
    precision: summary.precision,
    resolvedFindings: summary.mappedFindings,
    unresolvedFindings: Math.max(0, summary.eligibleFindings - summary.mappedFindings),
  };
}
