import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { createRequire } from 'node:module';
import ts from 'typescript';
import type {
  AnalysisToggles,
  BuildConfig,
  CacheConfig,
  CodeUsageMapConfig,
  CssConfig,
  LoggingConfig,
  ReporterConfig,
  ResolvedCodeUsageMapConfig,
  RouteInput,
  RuntimeAction,
  RuntimeConfig,
  RuntimeScenario,
  SourceMapConfig,
  ThresholdConfig,
} from './types.js';
import { SAFE_EXCLUDE_PATTERNS } from './integrations/detect.js';
import { resolveFrom } from './util/fs.js';

export const CONFIG_FILE_NAMES = [
  'code-usage-map.config.ts',
  'code-usage-map.config.mts',
  'code-usage-map.config.cts',
  'code-usage-map.config.js',
  'code-usage-map.config.mjs',
  'code-usage-map.config.cjs',
  'code-usage-map.config.json',
] as const;

export interface LoadedConfig {
  config: CodeUsageMapConfig;
  configPath?: string;
  warnings: string[];
}

export interface ConfigValidationIssue {
  path: string;
  message: string;
}

export interface ResolvedConfigResult {
  config: ResolvedCodeUsageMapConfig;
  configPath?: string;
  warnings: string[];
  issues: ConfigValidationIssue[];
}

/**
 * Identity helper for typed configuration files.
 */
export function defineConfig(config: CodeUsageMapConfig): CodeUsageMapConfig {
  return config;
}

export function findConfigFile(root: string, explicit?: string): string | undefined {
  if (explicit) {
    const resolved = path.isAbsolute(explicit) ? explicit : path.resolve(root, explicit);
    return existsSync(resolved) ? resolved : undefined;
  }
  for (const name of CONFIG_FILE_NAMES) {
    const file = path.join(root, name);
    if (existsSync(file)) return file;
  }
  return undefined;
}

function readPackageConfig(root: string): { config?: unknown; packageJsonPath?: string } {
  const packageJsonPath = path.join(root, 'package.json');
  if (!existsSync(packageJsonPath)) return {};
  try {
    const raw = JSON.parse(readFileSync(packageJsonPath, 'utf8')) as Record<string, unknown>;
    if (raw.codeUsageMap && typeof raw.codeUsageMap === 'object') {
      return { config: raw.codeUsageMap, packageJsonPath };
    }
  } catch {
    // A malformed package.json is reported by project analysis; ignore here.
  }
  return { packageJsonPath };
}

async function loadJavaScriptConfig(file: string): Promise<unknown> {
  const url = `${pathToFileURL(file).href}?cum=${Date.now()}`;
  const loaded: unknown = await import(url);
  if (loaded && typeof loaded === 'object' && 'default' in loaded) {
    return (loaded as { default: unknown }).default;
  }
  return loaded;
}

function loadTypeScriptConfig(file: string, warnings: string[]): unknown {
  const source = readFileSync(file, 'utf8');
  const transpiled = ts.transpileModule(source, {
    fileName: file,
    compilerOptions: {
      module: ts.ModuleKind.CommonJS,
      target: ts.ScriptTarget.ES2022,
      esModuleInterop: true,
      jsx: ts.JsxEmit.ReactJSX,
      sourceMap: false,
      inlineSourceMap: false,
    },
    reportDiagnostics: true,
  });
  if (transpiled.diagnostics?.length) {
    for (const diagnostic of transpiled.diagnostics) {
      warnings.push(`Config transpile diagnostic: ${ts.flattenDiagnosticMessageText(diagnostic.messageText, ' ')}`);
    }
  }
  const moduleObject: { exports: unknown } = { exports: {} };
  const localRequire = createRequire(file);
  const dirname = path.dirname(file);
  // Config files are user-authored local code. They are expected to execute,
  // just like a Vite/Webpack/Next config. Project source files are never run.
  const runner = new Function('exports', 'require', 'module', '__filename', '__dirname', transpiled.outputText);
  runner(moduleObject.exports, localRequire, moduleObject, file, dirname);
  const exported = moduleObject.exports;
  if (exported && typeof exported === 'object' && 'default' in exported) {
    return (exported as { default: unknown }).default;
  }
  return exported;
}

/**
 * Loads a config file or the `codeUsageMap` package.json field.
 * TypeScript configs are transpiled and executed locally; they are never sent
 * anywhere. Only `.ts`, `.js`, `.json` and package.json configs are supported.
 */
export async function loadConfig(root: string, explicit?: string): Promise<LoadedConfig> {
  const warnings: string[] = [];
  const configPath = findConfigFile(root, explicit);
  if (!configPath) {
    if (explicit) {
      warnings.push(`Config file not found: ${explicit}`);
    }
    const fromPackage = readPackageConfig(root);
    if (fromPackage.config) {
      return {
        config: validateConfigObject(fromPackage.config, fromPackage.packageJsonPath ?? 'package.json'),
        configPath: fromPackage.packageJsonPath,
        warnings,
      };
    }
    return { config: {}, warnings };
  }

  try {
    let value: unknown;
    if (configPath.endsWith('.json')) {
      value = JSON.parse(readFileSync(configPath, 'utf8')) as unknown;
    } else if (/\.(ts|mts|cts)$/i.test(configPath)) {
      value = loadTypeScriptConfig(configPath, warnings);
    } else {
      value = await loadJavaScriptConfig(configPath);
    }
    return {
      config: validateConfigObject(value, configPath),
      configPath,
      warnings,
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(`Failed to load config ${configPath}: ${message}`);
  }
}

const TOP_LEVEL_KEYS = new Set([
  'source',
  'include',
  'exclude',
  'output',
  'mode',
  'entryPoints',
  'routes',
  'tsconfig',
  'analysis',
  'build',
  'css',
  'runtime',
  'sourceMaps',
  'thresholds',
  'reporters',
  'cache',
  'baseline',
  'logging',
]);

const ANALYSIS_KEYS = new Set([
  'javascript',
  'typescript',
  'css',
  'dependencies',
  'bundles',
  'sourceMaps',
  'runtime',
  'duplicates',
  'unreachableCode',
  'recommendations',
]);

const BUILD_KEYS = new Set(['dir', 'manifest', 'command']);
const CSS_KEYS = new Set([
  'safelist',
  'safelistPatterns',
  'specificityThreshold',
  'checkCustomProperties',
  'scanTemplates',
  'analyzeOverriddenDeclarations',
]);
const RUNTIME_KEYS = new Set([
  'enabled',
  'baseUrl',
  'routes',
  'browser',
  'headless',
  'timeoutMs',
  'settleMs',
  'waitUntil',
  'navigation',
  'collectCoverage',
  'collectCss',
  'collectNetwork',
  'interactive',
  'snapshotIntervalMs',
  'viewport',
  'scenarios',
  'storageState',
  'ignoreHTTPSErrors',
]);
const SOURCE_MAP_KEYS = new Set(['enabled', 'maxMappingsPerFile']);
const THRESHOLD_KEYS = new Set([
  'maxTotalBundleBytes',
  'maxBundleGrowthBytes',
  'maxBundleGrowthPercent',
  'maxCssGrowthBytes',
  'maxCssGrowthPercent',
  'maxNewFindings',
  'maxRouteGrowthPercent',
  'failOn',
]);
const REPORTER_KEYS = new Set(['console', 'json', 'html']);
const CACHE_KEYS = new Set(['enabled', 'dir']);
const LOGGING_KEYS = new Set(['level']);

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function assertKeys(value: Record<string, unknown>, allowed: Set<string>, prefix: string): void {
  for (const key of Object.keys(value)) {
    if (!allowed.has(key)) {
      throw new Error(`Unknown configuration option "${prefix}${key}".`);
    }
  }
}

function asString(value: unknown, field: string): string {
  if (typeof value !== 'string' || value.trim() === '') {
    throw new Error(`Configuration option "${field}" must be a non-empty string.`);
  }
  return value;
}

function asOptionalString(value: unknown, field: string): string | undefined {
  if (value === undefined) return undefined;
  return asString(value, field);
}

function asBoolean(value: unknown, field: string): boolean {
  if (typeof value !== 'boolean') {
    throw new Error(`Configuration option "${field}" must be a boolean.`);
  }
  return value;
}

function asNumber(value: unknown, field: string, min = 0): number {
  if (typeof value !== 'number' || !Number.isFinite(value) || value < min) {
    throw new Error(`Configuration option "${field}" must be a number >= ${min}.`);
  }
  return value;
}

function asStringArray(value: unknown, field: string): string[] {
  if (!Array.isArray(value) || value.some((item) => typeof item !== 'string')) {
    throw new Error(`Configuration option "${field}" must be an array of strings.`);
  }
  return value as string[];
}

function asRoutes(value: unknown, field: string): RouteInput[] {
  if (!Array.isArray(value)) {
    throw new Error(`Configuration option "${field}" must be an array.`);
  }
  return value.map((entry, index) => {
    if (typeof entry === 'string' && entry.trim() !== '') return entry;
    if (isObject(entry)) {
      assertKeys(entry, new Set(['name', 'path', 'url']), `${field}[${index}].`);
      const name = asOptionalString(entry.name, `${field}[${index}].name`);
      const routePath = asOptionalString(entry.path, `${field}[${index}].path`);
      const url = asOptionalString(entry.url, `${field}[${index}].url`);
      if (!routePath && !url) {
        throw new Error(`Route at ${field}[${index}] must define "path" or "url".`);
      }
      if (url) asHttpUrl(url, `${field}[${index}].url`, true);
      return { ...(name ? { name } : {}), ...(routePath ? { path: routePath } : {}), ...(url ? { url } : {}) };
    }
    throw new Error(`Invalid route at ${field}[${index}].`);
  });
}

function asHttpUrl(value: string, field: string, allowRelative = false): string {
  if (allowRelative && value.startsWith('/')) return value;
  let parsed: URL;
  try {
    parsed = new URL(value);
  } catch {
    throw new Error(`Configuration option "${field}" must be an absolute http(s) URL.`);
  }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    throw new Error(`Configuration option "${field}" must use http or https.`);
  }
  return value;
}

function asRuntimeActions(value: unknown, field: string): RuntimeAction[] {
  if (!Array.isArray(value)) throw new Error(`Configuration option "${field}" must be an array.`);
  const allowedTypes = new Set(['click', 'hover', 'fill', 'press', 'waitForSelector', 'wait', 'select']);
  return value.map((entry, index) => {
    if (!isObject(entry)) throw new Error(`Invalid runtime action at ${field}[${index}].`);
    assertKeys(entry, new Set(['type', 'selector', 'value', 'key', 'ms', 'timeoutMs']), `${field}[${index}].`);
    const type = asString(entry.type, `${field}[${index}].type`);
    if (!allowedTypes.has(type)) {
      throw new Error(`Runtime action type "${type}" at ${field}[${index}] is not supported.`);
    }
    if (type !== 'wait' && !entry.selector) {
      throw new Error(`Runtime action "${type}" at ${field}[${index}] requires a selector.`);
    }
    return {
      type: type as RuntimeAction['type'],
      ...(entry.selector ? { selector: asString(entry.selector, `${field}[${index}].selector`) } : {}),
      ...(entry.value !== undefined ? { value: String(entry.value) } : {}),
      ...(entry.key !== undefined ? { key: String(entry.key) } : {}),
      ...(entry.ms !== undefined ? { ms: asNumber(entry.ms, `${field}[${index}].ms`) } : {}),
      ...(entry.timeoutMs !== undefined
        ? { timeoutMs: asNumber(entry.timeoutMs, `${field}[${index}].timeoutMs`) }
        : {}),
    };
  });
}

function asScenarios(value: unknown, field: string): RuntimeScenario[] {
  if (!Array.isArray(value)) throw new Error(`Configuration option "${field}" must be an array.`);
  return value.map((entry, index) => {
    if (!isObject(entry)) throw new Error(`Invalid scenario at ${field}[${index}].`);
    assertKeys(entry, new Set(['route', 'actions', 'strict']), `${field}[${index}].`);
    return {
      route: asString(entry.route, `${field}[${index}].route`),
      actions: asRuntimeActions(entry.actions, `${field}[${index}].actions`),
      ...(entry.strict !== undefined ? { strict: asBoolean(entry.strict, `${field}[${index}].strict`) } : {}),
    };
  });
}

function validateConfigObject(value: unknown, source: string): CodeUsageMapConfig {
  if (!isObject(value)) {
    throw new Error(`Config ${source} must export an object.`);
  }
  assertKeys(value, TOP_LEVEL_KEYS, '');

  const config: CodeUsageMapConfig = {};
  if (value.source !== undefined) {
    config.source =
      typeof value.source === 'string'
        ? asString(value.source, 'source')
        : asStringArray(value.source, 'source');
    if (config.source.length === 0) throw new Error('Configuration option "source" cannot be empty.');
  }
  if (value.include !== undefined) config.include = asStringArray(value.include, 'include');
  if (value.exclude !== undefined) config.exclude = asStringArray(value.exclude, 'exclude');
  if (value.output !== undefined) config.output = asString(value.output, 'output');
  if (value.mode !== undefined) {
    const mode = asString(value.mode, 'mode');
    if (mode !== 'application' && mode !== 'library') {
      throw new Error('Configuration option "mode" must be "application" or "library".');
    }
    config.mode = mode;
  }
  if (value.entryPoints !== undefined) config.entryPoints = asStringArray(value.entryPoints, 'entryPoints');
  if (value.routes !== undefined) config.routes = asRoutes(value.routes, 'routes');
  if (value.tsconfig !== undefined) config.tsconfig = asString(value.tsconfig, 'tsconfig');
  if (value.baseline !== undefined) config.baseline = asString(value.baseline, 'baseline');

  if (value.analysis !== undefined) {
    if (!isObject(value.analysis)) throw new Error('Configuration option "analysis" must be an object.');
    assertKeys(value.analysis, ANALYSIS_KEYS, 'analysis.');
    const analysis: Partial<AnalysisToggles> = {};
    for (const key of ANALYSIS_KEYS) {
      const current = value.analysis[key];
      if (current !== undefined) {
        analysis[key as keyof AnalysisToggles] = asBoolean(current, `analysis.${key}`);
      }
    }
    config.analysis = analysis;
  }

  if (value.build !== undefined) {
    if (!isObject(value.build)) throw new Error('Configuration option "build" must be an object.');
    assertKeys(value.build, BUILD_KEYS, 'build.');
    const build: BuildConfig = {};
    if (value.build.dir !== undefined) {
      build.dir =
        typeof value.build.dir === 'string'
          ? asString(value.build.dir, 'build.dir')
          : asStringArray(value.build.dir, 'build.dir');
    }
    if (value.build.manifest !== undefined) build.manifest = asString(value.build.manifest, 'build.manifest');
    if (value.build.command !== undefined) build.command = asString(value.build.command, 'build.command');
    config.build = build;
  }

  if (value.css !== undefined) {
    if (!isObject(value.css)) throw new Error('Configuration option "css" must be an object.');
    assertKeys(value.css, CSS_KEYS, 'css.');
    const css: Partial<CssConfig> = {};
    if (value.css.safelist !== undefined) css.safelist = asStringArray(value.css.safelist, 'css.safelist');
    if (value.css.safelistPatterns !== undefined) {
      css.safelistPatterns = asStringArray(value.css.safelistPatterns, 'css.safelistPatterns');
    }
    if (value.css.specificityThreshold !== undefined) {
      css.specificityThreshold = asNumber(value.css.specificityThreshold, 'css.specificityThreshold', 0);
    }
    if (value.css.checkCustomProperties !== undefined) {
      css.checkCustomProperties = asBoolean(value.css.checkCustomProperties, 'css.checkCustomProperties');
    }
    if (value.css.scanTemplates !== undefined) {
      css.scanTemplates = asBoolean(value.css.scanTemplates, 'css.scanTemplates');
    }
    if (value.css.analyzeOverriddenDeclarations !== undefined) {
      css.analyzeOverriddenDeclarations = asBoolean(
        value.css.analyzeOverriddenDeclarations,
        'css.analyzeOverriddenDeclarations',
      );
    }
    config.css = css;
  }

  if (value.runtime !== undefined) {
    if (!isObject(value.runtime)) throw new Error('Configuration option "runtime" must be an object.');
    assertKeys(value.runtime, RUNTIME_KEYS, 'runtime.');
    const runtime: Partial<RuntimeConfig> = {};
    if (value.runtime.enabled !== undefined) runtime.enabled = asBoolean(value.runtime.enabled, 'runtime.enabled');
    if (value.runtime.baseUrl !== undefined) {
      runtime.baseUrl = asHttpUrl(asString(value.runtime.baseUrl, 'runtime.baseUrl'), 'runtime.baseUrl');
    }
    if (value.runtime.routes !== undefined) runtime.routes = asRoutes(value.runtime.routes, 'runtime.routes');
    if (value.runtime.browser !== undefined) {
      const browser = asString(value.runtime.browser, 'runtime.browser');
      if (browser !== 'chromium' && browser !== 'firefox' && browser !== 'webkit') {
        throw new Error('Configuration option "runtime.browser" must be chromium, firefox or webkit.');
      }
      runtime.browser = browser;
    }
    if (value.runtime.headless !== undefined) runtime.headless = asBoolean(value.runtime.headless, 'runtime.headless');
    if (value.runtime.timeoutMs !== undefined) {
      runtime.timeoutMs = asNumber(value.runtime.timeoutMs, 'runtime.timeoutMs', 1000);
    }
    if (value.runtime.settleMs !== undefined) {
      runtime.settleMs = asNumber(value.runtime.settleMs, 'runtime.settleMs', 0);
    }
    if (value.runtime.snapshotIntervalMs !== undefined) {
      runtime.snapshotIntervalMs = asNumber(value.runtime.snapshotIntervalMs, 'runtime.snapshotIntervalMs', 100);
    }
    if (value.runtime.waitUntil !== undefined) {
      const waitUntil = asString(value.runtime.waitUntil, 'runtime.waitUntil');
      if (!['load', 'domcontentloaded', 'networkidle', 'commit'].includes(waitUntil)) {
        throw new Error('Configuration option "runtime.waitUntil" must be load, domcontentloaded, networkidle or commit.');
      }
      runtime.waitUntil = waitUntil as RuntimeConfig['waitUntil'];
    }
    if (value.runtime.navigation !== undefined) {
      const navigation = asString(value.runtime.navigation, 'runtime.navigation');
      if (navigation !== 'auto' && navigation !== 'goto') {
        throw new Error('Configuration option "runtime.navigation" must be "auto" or "goto".');
      }
      runtime.navigation = navigation;
    }
    for (const key of ['collectCoverage', 'collectCss', 'collectNetwork', 'interactive', 'ignoreHTTPSErrors'] as const) {
      if (value.runtime[key] !== undefined) {
        runtime[key] = asBoolean(value.runtime[key], `runtime.${key}`);
      }
    }
    if (value.runtime.viewport !== undefined) {
      if (!isObject(value.runtime.viewport)) throw new Error('Configuration option "runtime.viewport" must be an object.');
      assertKeys(value.runtime.viewport, new Set(['width', 'height']), 'runtime.viewport.');
      runtime.viewport = {
        width: asNumber(value.runtime.viewport.width, 'runtime.viewport.width', 1),
        height: asNumber(value.runtime.viewport.height, 'runtime.viewport.height', 1),
      };
    }
    if (value.runtime.scenarios !== undefined) {
      runtime.scenarios = asScenarios(value.runtime.scenarios, 'runtime.scenarios');
    }
    if (value.runtime.storageState !== undefined) {
      runtime.storageState = asString(value.runtime.storageState, 'runtime.storageState');
    }
    config.runtime = runtime;
  }

  if (value.sourceMaps !== undefined) {
    if (!isObject(value.sourceMaps)) throw new Error('Configuration option "sourceMaps" must be an object.');
    assertKeys(value.sourceMaps, SOURCE_MAP_KEYS, 'sourceMaps.');
    const sourceMaps: Partial<SourceMapConfig> = {};
    if (value.sourceMaps.enabled !== undefined) {
      sourceMaps.enabled = asBoolean(value.sourceMaps.enabled, 'sourceMaps.enabled');
    }
    if (value.sourceMaps.maxMappingsPerFile !== undefined) {
      sourceMaps.maxMappingsPerFile = asNumber(
        value.sourceMaps.maxMappingsPerFile,
        'sourceMaps.maxMappingsPerFile',
        100,
      );
    }
    config.sourceMaps = sourceMaps;
  }

  if (value.thresholds !== undefined) {
    if (!isObject(value.thresholds)) throw new Error('Configuration option "thresholds" must be an object.');
    assertKeys(value.thresholds, THRESHOLD_KEYS, 'thresholds.');
    const thresholds: ThresholdConfig = {};
    for (const key of [
      'maxTotalBundleBytes',
      'maxBundleGrowthBytes',
      'maxBundleGrowthPercent',
      'maxCssGrowthBytes',
      'maxCssGrowthPercent',
      'maxNewFindings',
      'maxRouteGrowthPercent',
    ] as const) {
      if (value.thresholds[key] !== undefined) {
        thresholds[key] = asNumber(value.thresholds[key], `thresholds.${key}`, 0);
      }
    }
    if (value.thresholds.failOn !== undefined) {
      const categories = [
        'unused-import',
        'unused-export',
        'unused-variable',
        'unused-function',
        'unused-class',
        'unused-class-method',
        'unused-type',
        'unused-enum-member',
        'unused-type-parameter',
        'unused-decorator',
        'unused-event-handler',
        'unreachable-code',
        'unused-type-only-import',
        'circular-dependency',
        'duplicate-code',
        'unused-css-selector',
        'unused-css-declaration',
        'duplicate-css-selector',
        'duplicate-css-rule',
        'unused-css-custom-property',
        'unused-stylesheet',
        'css-specificity',
        'unused-dependency',
        'duplicate-dependency',
        'heavy-dependency',
        'unused-module',
        'unused-bundle-code',
        'route-exclusive-module',
        'code-splitting-opportunity',
        'polyfill-included',
        'tree-shaking-opportunity',
      ] as const;
      const failOn = asStringArray(value.thresholds.failOn, 'thresholds.failOn');
      for (const category of failOn) {
        if (!categories.includes(category as (typeof categories)[number])) {
          throw new Error(`Unknown finding category "${category}" in thresholds.failOn.`);
        }
      }
      thresholds.failOn = failOn as NonNullable<ThresholdConfig['failOn']>;
    }
    config.thresholds = thresholds;
  }

  if (value.reporters !== undefined) {
    if (!isObject(value.reporters)) throw new Error('Configuration option "reporters" must be an object.');
    assertKeys(value.reporters, REPORTER_KEYS, 'reporters.');
    const reporters: Partial<ReporterConfig> = {};
    for (const key of ['console', 'json', 'html'] as const) {
      if (value.reporters[key] !== undefined) reporters[key] = asBoolean(value.reporters[key], `reporters.${key}`);
    }
    config.reporters = reporters;
  }

  if (value.cache !== undefined) {
    if (!isObject(value.cache)) throw new Error('Configuration option "cache" must be an object.');
    assertKeys(value.cache, CACHE_KEYS, 'cache.');
    const cache: Partial<CacheConfig> = {};
    if (value.cache.enabled !== undefined) cache.enabled = asBoolean(value.cache.enabled, 'cache.enabled');
    if (value.cache.dir !== undefined) cache.dir = asString(value.cache.dir, 'cache.dir');
    config.cache = cache;
  }

  if (value.logging !== undefined) {
    if (!isObject(value.logging)) throw new Error('Configuration option "logging" must be an object.');
    assertKeys(value.logging, LOGGING_KEYS, 'logging.');
    const logging: Partial<LoggingConfig> = {};
    if (value.logging.level !== undefined) {
      const level = asString(value.logging.level, 'logging.level');
      if (!['silent', 'error', 'warn', 'info', 'debug'].includes(level)) {
        throw new Error('Configuration option "logging.level" must be silent, error, warn, info or debug.');
      }
      logging.level = level as LoggingConfig['level'];
    }
    config.logging = logging;
  }

  return config;
}

function defaultSource(root: string): string[] {
  if (existsSync(path.join(root, 'src'))) return ['src'];
  if (existsSync(path.join(root, 'app'))) return ['app'];
  return ['.'];
}

/**
 * Normalizes user configuration, resolving paths and applying safe defaults.
 * Invalid regexes in `css.safelistPatterns` produce warnings instead of aborting.
 */
export function resolveConfig(
  root: string,
  user: CodeUsageMapConfig,
  configPath?: string,
  loadWarnings: string[] = [],
): ResolvedConfigResult {
  const warnings = [...loadWarnings];
  const issues: ConfigValidationIssue[] = [];

  const sourceValues = user.source
    ? Array.isArray(user.source)
      ? user.source
      : [user.source]
    : defaultSource(root);
  const source = [...new Set(sourceValues.map((value) => resolveFrom(root, value)))];
  if (source.length === 0) {
    issues.push({ path: 'source', message: 'At least one source directory is required.' });
  }
  for (const dir of source) {
    if (!existsSync(dir)) {
      warnings.push(`Source path does not exist: ${dir}`);
    }
  }

  let output: string;
  if (user.output) {
    output = resolveFrom(root, user.output);
  } else {
    output = path.join(root, 'code-usage-map-report');
  }

  const buildDirValues = user.build?.dir
    ? Array.isArray(user.build.dir)
      ? user.build.dir
      : [user.build.dir]
    : [];
  const build: BuildConfig = {
    ...(buildDirValues.length > 0 ? { dir: buildDirValues.map((value) => resolveFrom(root, value)) } : {}),
    ...(user.build?.manifest ? { manifest: resolveFrom(root, user.build.manifest) } : {}),
    ...(user.build?.command ? { command: user.build.command } : {}),
  };

  const entryPoints = [...new Set((user.entryPoints ?? []).map((value) => resolveFrom(root, value)))];

  const analysis: AnalysisToggles = {
    javascript: true,
    typescript: true,
    css: true,
    dependencies: true,
    bundles: true,
    sourceMaps: true,
    runtime: true,
    duplicates: true,
    unreachableCode: true,
    recommendations: true,
    ...user.analysis,
  };

  const css: CssConfig = {
    safelist: [],
    safelistPatterns: [],
    specificityThreshold: 40,
    checkCustomProperties: true,
    scanTemplates: true,
    analyzeOverriddenDeclarations: true,
    ...user.css,
  };
  for (const pattern of css.safelistPatterns) {
    try {
      new RegExp(pattern);
    } catch {
      warnings.push(`Invalid regular expression in css.safelistPatterns: ${pattern}`);
    }
  }

  const runtimeRoutes = user.runtime?.routes ?? user.routes ?? [];
  const runtime: RuntimeConfig = {
    enabled: true,
    browser: 'chromium',
    headless: true,
    timeoutMs: 30_000,
    settleMs: 500,
    waitUntil: 'load',
    navigation: 'auto',
    collectCoverage: true,
    collectCss: true,
    collectNetwork: true,
    interactive: false,
    snapshotIntervalMs: 500,
    viewport: { width: 1365, height: 900 },
    scenarios: [],
    ignoreHTTPSErrors: false,
    ...user.runtime,
    routes: runtimeRoutes,
  };
  if (user.runtime?.baseUrl) runtime.baseUrl = user.runtime.baseUrl;

  const sourceMaps: SourceMapConfig = {
    enabled: true,
    maxMappingsPerFile: 250_000,
    ...user.sourceMaps,
  };

  const thresholds: ThresholdConfig = { ...user.thresholds };
  const reporters: ReporterConfig = {
    console: true,
    json: true,
    html: true,
    ...user.reporters,
  };
  const cache: CacheConfig = {
    enabled: true,
    dir: path.join(root, '.code-usage-map', 'cache'),
    ...user.cache,
    ...(user.cache?.dir ? { dir: resolveFrom(root, user.cache.dir) } : {}),
  };
  const logging: LoggingConfig = {
    level: 'info',
    ...user.logging,
  };

  const config: ResolvedCodeUsageMapConfig = {
    root,
    source,
    include: user.include ?? [],
    exclude: [...SAFE_EXCLUDE_PATTERNS, ...(user.exclude ?? [])],
    output,
    mode: user.mode ?? 'application',
    entryPoints,
    routes: user.routes ?? [],
    ...(user.tsconfig
      ? { tsconfig: resolveFrom(root, user.tsconfig) }
      : existsSync(path.join(root, 'tsconfig.json'))
        ? { tsconfig: path.join(root, 'tsconfig.json') }
        : existsSync(path.join(root, 'jsconfig.json'))
          ? { tsconfig: path.join(root, 'jsconfig.json') }
          : {}),
    analysis,
    build,
    css,
    runtime,
    sourceMaps,
    thresholds,
    reporters,
    cache,
    ...(user.baseline ? { baseline: resolveFrom(root, user.baseline) } : {}),
    logging,
  };

  return { config, configPath, warnings, issues };
}

export async function loadResolvedConfig(
  root: string,
  explicitConfig?: string,
): Promise<ResolvedConfigResult & { configFile?: string }> {
  const loaded = await loadConfig(root, explicitConfig);
  const resolved = resolveConfig(root, loaded.config, loaded.configPath, loaded.warnings);
  return { ...resolved, configFile: loaded.configPath };
}
