import { existsSync, readFileSync, statSync } from 'node:fs';
import path from 'node:path';
import { builtinModules } from 'node:module';
import ts from 'typescript';
import type {
  ExternalImportRecord,
  ImportBinding,
  ImportRecord,
  ModuleRecordInfo,
  SourceFileInfo,
  CircularDependencyInfo,
  DynamicPatternRecord,
  TypeOnlyImportRecord,
} from './types.js';
import { isDeclarationFile, isTestOrStoryFile } from './source-files.js';
import type { StaticProgram } from './program.js';
import { toPosix } from '../util/fs.js';
import { fileType } from '../integrations/detect.js';

export interface ImportGraphResult {
  imports: ImportRecord[];
  externalImports: ExternalImportRecord[];
  assetImports: ImportRecord[];
  modules: ModuleRecordInfo[];
  sourceFiles: SourceFileInfo[];
  dynamicPatterns: DynamicPatternRecord[];
  typeOnlyImports: TypeOnlyImportRecord[];
  entryPoints: string[];
  reachableFiles: string[];
  circularDependencies: CircularDependencyInfo[];
  htmlReferences: Array<{ file: string; reference: string; resolvedFile?: string }>;
  hasDynamicModuleLoading: boolean;
  hasGlobImports: boolean;
  warnings: string[];
}

const ASSET_EXTENSIONS = new Set([
  '.css',
  '.scss',
  '.sass',
  '.less',
  '.svg',
  '.png',
  '.jpg',
  '.jpeg',
  '.gif',
  '.webp',
  '.avif',
  '.ico',
  '.woff',
  '.woff2',
  '.ttf',
  '.eot',
  '.json',
  '.txt',
  '.md',
  '.wasm',
]);

const BUILTINS = new Set(builtinModules.map((name) => name.replace(/^node:/, '')));

const RESOLVE_EXTENSIONS = [
  '.ts',
  '.tsx',
  '.mts',
  '.cts',
  '.js',
  '.jsx',
  '.mjs',
  '.cjs',
  '.vue',
  '.svelte',
  '.astro',
  '.css',
  '.scss',
  '.sass',
  '.less',
];

export function packageNameFromSpecifier(specifier: string): string | undefined {
  if (
    !specifier ||
    specifier.startsWith('.') ||
    specifier.startsWith('/') ||
    specifier.startsWith('\\') ||
    specifier.startsWith('node:') ||
    specifier.startsWith('http:') ||
    specifier.startsWith('https:') ||
    specifier.startsWith('data:') ||
    specifier.startsWith('virtual:') ||
    specifier.startsWith('\0') ||
    specifier.startsWith('#')
  ) {
    return undefined;
  }
  if (specifier.startsWith('@')) {
    const parts = specifier.split('/');
    return parts.length >= 2 ? `${parts[0]}/${parts[1]}` : specifier;
  }
  return specifier.split('/')[0];
}

export function isBuiltinSpecifier(specifier: string): boolean {
  return specifier.startsWith('node:') || BUILTINS.has(specifier.split('/')[0] ?? '');
}

export function stripQuery(specifier: string): string {
  return specifier.replace(/[?#].*$/, '');
}

function pageLikeFile(file: string): boolean {
  const normalized = toPosix(file).toLowerCase();
  return (
    /\/pages\//.test(normalized) ||
    /\/app\//.test(normalized) ||
    /\/routes\//.test(normalized) ||
    /\/views\//.test(normalized) ||
    /\/screens\//.test(normalized) ||
    /\/\+page\.[a-z]+$/.test(normalized) ||
    /\/(page|layout|template|route|error|not-found)\.[a-z]+$/.test(normalized) ||
    /\.(vue|svelte|astro)$/.test(normalized)
  );
}

function scriptRootsFromHtml(htmlFiles: string[], root: string): ImportGraphResult['htmlReferences'] {
  const references: ImportGraphResult['htmlReferences'] = [];
  for (const file of htmlFiles) {
    if (!existsSync(file)) continue;
    let content = '';
    try {
      content = readFileSync(file, 'utf8');
    } catch {
      continue;
    }
    const regex = /<(?:script\b[^>]*\bsrc|link\b[^>]*\bhref)\s*=\s*(?:"([^"]+)"|'([^']+)'|([^\s>]+))/gi;
    let match: RegExpExecArray | null;
    while ((match = regex.exec(content)) !== null) {
      const reference = match[1] ?? match[2] ?? match[3];
      if (!reference) continue;
      if (reference.startsWith('http:') || reference.startsWith('https:') || reference.startsWith('//')) continue;
      let resolved: string | undefined;
      if (reference.startsWith('/')) {
        const candidate = path.resolve(root, `.${stripQuery(reference)}`);
        if (existsSync(candidate)) resolved = candidate;
      } else {
        const candidate = path.resolve(path.dirname(file), stripQuery(reference));
        if (existsSync(candidate)) resolved = candidate;
      }
      references.push({ file, reference, ...(resolved ? { resolvedFile: resolved } : {}) });
    }
  }
  return references;
}

function resolveFileCandidates(
  base: string,
  analyzedFiles: Set<string>,
  root: string,
): string | undefined {
  const normalizedBase = path.normalize(base);
  const candidates = new Set<string>();
  candidates.add(normalizedBase);

  const ext = path.extname(normalizedBase).toLowerCase();
  if (['.js', '.jsx', '.mjs', '.cjs'].includes(ext)) {
    const without = normalizedBase.slice(0, -ext.length);
    const tsExtensions = ext === '.mjs' ? ['.mts', '.ts'] : ext === '.cjs' ? ['.cts', '.ts'] : ['.ts', '.tsx'];
    for (const candidateExt of tsExtensions) candidates.add(`${without}${candidateExt}`);
  }
  for (const candidateExt of RESOLVE_EXTENSIONS) candidates.add(`${normalizedBase}${candidateExt}`);
  for (const candidateExt of RESOLVE_EXTENSIONS) candidates.add(path.join(normalizedBase, `index${candidateExt}`));

  for (const candidate of candidates) {
    if (!existsSync(candidate)) continue;
    try {
      if (statSync(candidate).isFile()) {
        if (candidate.startsWith(root) || analyzedFiles.has(candidate)) return candidate;
      }
    } catch {
      // Ignore unreadable candidates.
    }
  }
  return undefined;
}

function resolveImport(
  specifier: string,
  containingFile: string,
  analyzedFiles: Set<string>,
  root: string,
  options: ts.CompilerOptions,
): string | undefined {
  const cleaned = stripQuery(specifier);
  if (cleaned.startsWith('http:') || cleaned.startsWith('https:') || cleaned.startsWith('data:')) return undefined;

  const relativeOrAbsolute = cleaned.startsWith('.') || cleaned.startsWith('/');
  if (relativeOrAbsolute) {
    const base = cleaned.startsWith('/')
      ? path.resolve(root, `.${cleaned}`)
      : path.resolve(path.dirname(containingFile), cleaned);
    const resolved = resolveFileCandidates(base, analyzedFiles, root);
    if (resolved) return resolved;
  }

  try {
    const resolution = ts.resolveModuleName(cleaned, containingFile, options, ts.sys);
    const resolved = resolution.resolvedModule?.resolvedFileName;
    if (resolved && !resolved.includes('node_modules')) {
      return path.normalize(resolved);
    }
  } catch {
    // Fall through to manual resolution.
  }

  if (relativeOrAbsolute) {
    return resolveFileCandidates(
      path.resolve(path.dirname(containingFile), cleaned),
      analyzedFiles,
      root,
    );
  }
  return undefined;
}

function lineColumn(sourceFile: ts.SourceFile, node: ts.Node): { line: number; column: number } {
  const position = sourceFile.getLineAndCharacterOfPosition(node.getStart(sourceFile));
  return { line: position.line + 1, column: position.character + 1 };
}

function collectBindings(importClause: ts.ImportClause | undefined, sourceFile: ts.SourceFile): ImportBinding[] {
  if (!importClause) return [];
  const bindings: ImportBinding[] = [];
  if (importClause.name) {
    const position = lineColumn(sourceFile, importClause.name);
    bindings.push({
      imported: 'default',
      local: importClause.name.text,
      typeOnly: importClause.isTypeOnly,
      line: position.line,
      column: position.column,
    });
  }
  if (importClause.namedBindings) {
    if (ts.isNamespaceImport(importClause.namedBindings)) {
      const position = lineColumn(sourceFile, importClause.namedBindings.name);
      bindings.push({
        imported: '*',
        local: importClause.namedBindings.name.text,
        typeOnly: importClause.isTypeOnly,
        line: position.line,
        column: position.column,
      });
    } else {
      for (const element of importClause.namedBindings.elements) {
        const position = lineColumn(sourceFile, element.name);
        bindings.push({
          imported: element.propertyName?.text ?? element.name.text,
          local: element.name.text,
          typeOnly: importClause.isTypeOnly || element.isTypeOnly,
          line: position.line,
          column: position.column,
        });
      }
    }
  }
  return bindings;
}

function exportNames(node: ts.ExportDeclaration): string[] {
  if (!node.exportClause) return [];
  if (ts.isNamespaceExport(node.exportClause)) return ['*'];
  return node.exportClause.elements.map((element) => element.propertyName?.text ?? element.name.text);
}

function isAsset(specifier: string): boolean {
  return ASSET_EXTENSIONS.has(path.extname(stripQuery(specifier)).toLowerCase());
}

function isLikelyGlobImport(node: ts.CallExpression): 'glob' | 'require-context' | undefined {
  if (ts.isPropertyAccessExpression(node.expression)) {
    const name = node.expression.name.text;
    if ((name === 'glob' || name === 'globEager') && ts.isMetaProperty(node.expression.expression)) {
      return 'glob';
    }
    if (name === 'context' && node.expression.expression.getText().includes('require')) {
      return 'require-context';
    }
  }
  return undefined;
}

/** Collects imports, module reachability, dependency references and cycles. */
export function buildImportGraph(
  staticProgram: StaticProgram,
  analyzedFiles: string[],
  root: string,
  configuredEntryPoints: string[],
  htmlFiles: string[],
  signal?: AbortSignal,
): ImportGraphResult {
  const imports: ImportRecord[] = [];
  const externalImports: ExternalImportRecord[] = [];
  const assetImports: ImportRecord[] = [];
  const dynamicPatterns: DynamicPatternRecord[] = [];
  const warnings: string[] = [];
  const analyzedSet = new Set(analyzedFiles.map((file) => path.normalize(file)));
  const htmlReferences = scriptRootsFromHtml(htmlFiles, root);

  const isVirtual = (fileName: string): boolean => staticProgram.virtualByFile.has(path.normalize(fileName));
  const originalOf = (fileName: string): string =>
    staticProgram.virtualByFile.get(path.normalize(fileName))?.originalFile ?? path.normalize(fileName);

  const virtualOriginalSet = new Set(
    [...staticProgram.virtualByFile.values()].map((value) => path.normalize(value.originalFile)),
  );

  const programSourceFiles = staticProgram.program
    .getSourceFiles()
    .filter((sourceFile) => {
      const normalized = path.normalize(sourceFile.fileName);
      if (sourceFile.isDeclarationFile && !analyzedSet.has(normalized) && !virtualOriginalSet.has(normalized)) {
        return false;
      }
      if (normalized.includes(`${path.sep}node_modules${path.sep}`)) return false;
      if (analyzedSet.has(normalized) || virtualOriginalSet.has(normalized)) return true;
      return !sourceFile.isDeclarationFile && !normalized.includes(`${path.sep}typescript${path.sep}lib${path.sep}`);
    });

  const processImportDeclaration = (sourceFile: ts.SourceFile, node: ts.ImportDeclaration): void => {
    if (!ts.isStringLiteralLike(node.moduleSpecifier)) return;
    const specifier = node.moduleSpecifier.text;
    const original = originalOf(sourceFile.fileName);
    if (!analyzedSet.has(original)) return;
    const bindings = collectBindings(node.importClause, sourceFile);
    const typeOnly = Boolean(node.importClause?.isTypeOnly) || (bindings.length > 0 && bindings.every((binding) => binding.typeOnly));
    const resolved = resolveImport(specifier, original, analyzedSet, root, staticProgram.options);
    const position = lineColumn(sourceFile, node.moduleSpecifier);
    const packageName = packageNameFromSpecifier(specifier);
    const asset = isAsset(specifier);
    const record: ImportRecord = {
      file: original,
      relativeFile: toPosix(path.relative(root, original)),
      specifier,
      kind: typeOnly ? 'type' : bindings.length === 0 ? 'side-effect' : 'static',
      line: position.line,
      column: position.column,
      bindings,
      typeOnly,
      ...(packageName && !isBuiltinSpecifier(specifier) ? { packageName } : {}),
      ...(resolved ? { resolvedFile: resolved, resolvedRelativeFile: toPosix(path.relative(root, resolved)) } : {}),
      isAsset: asset,
      sourceNodeKind: 'import',
    };
    imports.push(record);
    if (asset) assetImports.push(record);
    if (packageName && !isBuiltinSpecifier(specifier)) {
      externalImports.push({
        packageName,
        specifier,
        file: original,
        relativeFile: record.relativeFile,
        typeOnly,
        dynamic: false,
        kind: typeOnly ? 'type' : 'static',
        names: bindings.map((binding) => binding.imported),
      });
    }
  };

  const processExportDeclaration = (sourceFile: ts.SourceFile, node: ts.ExportDeclaration): void => {
    if (!node.moduleSpecifier || !ts.isStringLiteralLike(node.moduleSpecifier)) return;
    const original = originalOf(sourceFile.fileName);
    if (!analyzedSet.has(original)) return;
    const specifier = node.moduleSpecifier.text;
    const position = lineColumn(sourceFile, node.moduleSpecifier);
    const names = exportNames(node);
    const resolved = resolveImport(specifier, original, analyzedSet, root, staticProgram.options);
    const packageName = packageNameFromSpecifier(specifier);
    const record: ImportRecord = {
      file: original,
      relativeFile: toPosix(path.relative(root, original)),
      specifier,
      kind: node.isTypeOnly ? 'type' : 're-export',
      line: position.line,
      column: position.column,
      bindings: names.map((name) => ({ imported: name, local: name, typeOnly: node.isTypeOnly, line: position.line, column: position.column })),
      typeOnly: node.isTypeOnly,
      ...(packageName && !isBuiltinSpecifier(specifier) ? { packageName } : {}),
      ...(resolved ? { resolvedFile: resolved, resolvedRelativeFile: toPosix(path.relative(root, resolved)) } : {}),
      isAsset: isAsset(specifier),
      sourceNodeKind: 'export',
    };
    imports.push(record);
    if (record.isAsset) assetImports.push(record);
    if (packageName && !isBuiltinSpecifier(specifier)) {
      externalImports.push({
        packageName,
        specifier,
        file: original,
        relativeFile: record.relativeFile,
        typeOnly: node.isTypeOnly,
        dynamic: false,
        kind: node.isTypeOnly ? 'type' : 're-export',
        names,
      });
    }
  };

  const processCall = (sourceFile: ts.SourceFile, node: ts.CallExpression): void => {
    const original = originalOf(sourceFile.fileName);
    const position = lineColumn(sourceFile, node.expression);
    const dynamicKind = isLikelyGlobImport(node);
    if (dynamicKind) {
      if (analyzedSet.has(original)) {
        dynamicPatterns.push({
          file: original,
          relativeFile: toPosix(path.relative(root, original)),
          kind: 'glob-import',
          description:
            dynamicKind === 'glob'
              ? 'import.meta.glob() loads modules with a generated expression.'
              : 'require.context() loads modules with a generated expression.',
          line: position.line,
        });
      }
      return;
    }

    if (ts.isIdentifier(node.expression) && node.expression.text === 'eval') {
      if (analyzedSet.has(original)) {
        dynamicPatterns.push({
          file: original,
          relativeFile: toPosix(path.relative(root, original)),
          kind: 'eval',
          description: 'Direct eval() can reference local bindings dynamically.',
          line: position.line,
        });
      }
      return;
    }

    if (
      ts.isPropertyAccessExpression(node.expression) &&
      ['defineProperty', 'getOwnPropertyDescriptor', 'getOwnPropertyNames'].includes(node.expression.name.text) &&
      node.expression.expression.getText(sourceFile).endsWith('Object')
    ) {
      if (analyzedSet.has(original)) {
        dynamicPatterns.push({
          file: original,
          relativeFile: toPosix(path.relative(root, original)),
          kind: 'reflection',
          description: `${node.expression.getText(sourceFile)} uses runtime reflection.`,
          line: position.line,
        });
      }
    }

    const isDynamicImport = node.expression.kind === ts.SyntaxKind.ImportKeyword;
    const isRequire = ts.isIdentifier(node.expression) && node.expression.text === 'require';
    if (!isDynamicImport && !isRequire) return;

    const argument = node.arguments[0];
    if (argument && ts.isStringLiteralLike(argument)) {
      if (!analyzedSet.has(original)) return;
      const specifier = argument.text;
      const resolved = resolveImport(specifier, original, analyzedSet, root, staticProgram.options);
      const packageName = packageNameFromSpecifier(specifier);
      const record: ImportRecord = {
        file: original,
        relativeFile: toPosix(path.relative(root, original)),
        specifier,
        kind: isDynamicImport ? 'dynamic' : 'require',
        line: position.line,
        column: position.column,
        bindings: [],
        typeOnly: false,
        ...(packageName && !isBuiltinSpecifier(specifier) ? { packageName } : {}),
        ...(resolved ? { resolvedFile: resolved, resolvedRelativeFile: toPosix(path.relative(root, resolved)) } : {}),
        isAsset: isAsset(specifier),
        sourceNodeKind: isDynamicImport ? 'dynamic-import' : 'require',
      };
      imports.push(record);
      if (record.isAsset) assetImports.push(record);
      if (packageName && !isBuiltinSpecifier(specifier)) {
        externalImports.push({
          packageName,
          specifier,
          file: original,
          relativeFile: record.relativeFile,
          typeOnly: false,
          dynamic: isDynamicImport,
          kind: isDynamicImport ? 'dynamic' : 'require',
          names: [],
        });
      }
    } else if (analyzedSet.has(original)) {
      dynamicPatterns.push({
        file: original,
        relativeFile: toPosix(path.relative(root, original)),
        kind: 'dynamic-module',
        description: `${isDynamicImport ? 'import()' : 'require()'} uses a computed module specifier.`,
        line: position.line,
      });
    }
  };

  for (const sourceFile of programSourceFiles) {
    if (signal?.aborted) break;
    const normalizedFile = path.normalize(sourceFile.fileName);
    if (sourceFile.isDeclarationFile) continue;
    if (normalizedFile.includes(`${path.sep}node_modules${path.sep}`)) continue;

    const visit = (node: ts.Node): void => {
      if (ts.isImportDeclaration(node)) {
        processImportDeclaration(sourceFile, node);
        return;
      }
      if (ts.isExportDeclaration(node)) {
        processExportDeclaration(sourceFile, node);
        return;
      }
      if (ts.isImportEqualsDeclaration(node) && ts.isExternalModuleReference(node.moduleReference)) {
        const expression = node.moduleReference.expression;
        if (ts.isStringLiteralLike(expression)) {
          const original = originalOf(sourceFile.fileName);
          if (analyzedSet.has(original)) {
            const specifier = expression.text;
            const packageName = packageNameFromSpecifier(specifier);
            const position = lineColumn(sourceFile, expression);
            const resolved = resolveImport(specifier, original, analyzedSet, root, staticProgram.options);
            imports.push({
              file: original,
              relativeFile: toPosix(path.relative(root, original)),
              specifier,
              kind: 'require',
              line: position.line,
              column: position.column,
              bindings: [{ imported: 'default', local: node.name.text, typeOnly: false, line: position.line, column: position.column }],
              typeOnly: false,
              ...(packageName && !isBuiltinSpecifier(specifier) ? { packageName } : {}),
              ...(resolved ? { resolvedFile: resolved, resolvedRelativeFile: toPosix(path.relative(root, resolved)) } : {}),
              isAsset: isAsset(specifier),
              sourceNodeKind: 'import-equals',
            });
            if (packageName && !isBuiltinSpecifier(specifier)) {
              externalImports.push({
                packageName,
                specifier,
                file: original,
                relativeFile: toPosix(path.relative(root, original)),
                typeOnly: false,
                dynamic: false,
                kind: 'require',
                names: ['default'],
              });
            }
          }
        }
      }
      if (ts.isNewExpression(node) && ts.isIdentifier(node.expression) && node.expression.text === 'Function') {
        const original = originalOf(sourceFile.fileName);
        if (analyzedSet.has(original)) {
          const position = lineColumn(sourceFile, node.expression);
          dynamicPatterns.push({
            file: original,
            relativeFile: toPosix(path.relative(root, original)),
            kind: 'new-function',
            description: 'new Function() can execute dynamically generated code.',
            line: position.line,
          });
        }
      }
      if (ts.isElementAccessExpression(node) && !ts.isStringLiteralLike(node.argumentExpression) && !ts.isNumericLiteral(node.argumentExpression)) {
        const objectText = node.expression.getText(sourceFile);
        if (['window', 'globalThis', 'self', 'global', 'this'].includes(objectText)) {
          const original = originalOf(sourceFile.fileName);
          if (analyzedSet.has(original)) {
            const position = lineColumn(sourceFile, node.expression);
            dynamicPatterns.push({
              file: original,
              relativeFile: toPosix(path.relative(root, original)),
              kind: 'dynamic-member',
              description: `Computed property access on ${objectText} can reach any property.`,
              line: position.line,
            });
          }
        }
      }
      if (ts.isCallExpression(node)) processCall(sourceFile, node);
      ts.forEachChild(node, visit);
    };
    visit(sourceFile);
  }

  const hasGlobImports = dynamicPatterns.some((pattern) => pattern.kind === 'glob-import');
  const hasDynamicModuleLoading = dynamicPatterns.some(
    (pattern) => pattern.kind === 'dynamic-module' || pattern.kind === 'glob-import',
  );

  // Module nodes are keyed by original source path.
  const moduleList = new Map<string, ModuleRecordInfo>();
  for (const file of analyzedFiles) {
    const original = staticProgram.virtualByFile.get(path.normalize(file))?.originalFile ?? path.normalize(file);
    if (moduleList.has(path.normalize(original))) continue;
    let bytes = 0;
    let lines = 0;
    try {
      const stat = statSync(original);
      bytes = stat.size;
      const content = readFileSync(original, 'utf8');
      lines = content === '' ? 0 : content.split(/\r\n|\r|\n/).length;
    } catch {
      // Missing files retain zero sizes.
    }
    moduleList.set(path.normalize(original), {
      file: original,
      relativeFile: toPosix(path.relative(root, original)),
      type: fileType(original),
      isVirtual: isVirtual(file),
      ...(isVirtual(file) ? { originalFile: original } : {}),
      entry: false,
      pageLike: pageLikeFile(original),
      reachable: false,
      isTest: isTestOrStoryFile(original),
      importCount: 0,
      importerCount: 0,
      importers: [],
      dynamicImportTarget: false,
      bytes,
      lines,
    });
  }

  for (const record of imports) {
    const module = moduleList.get(path.normalize(record.file));
    if (module) module.importCount += 1;
    if (record.resolvedFile) {
      const target = moduleList.get(path.normalize(record.resolvedFile));
      if (target) {
        target.importerCount += 1;
        if (!target.importers.includes(record.relativeFile)) target.importers.push(record.relativeFile);
        if (record.kind === 'dynamic') target.dynamicImportTarget = true;
      }
    }
  }

  const configuredRoots = new Set<string>();
  for (const entry of configuredEntryPoints) {
    const normalized = path.normalize(entry);
    if (moduleList.has(normalized)) configuredRoots.add(normalized);
  }
  for (const reference of htmlReferences) {
    if (reference.resolvedFile && moduleList.has(path.normalize(reference.resolvedFile))) {
      configuredRoots.add(path.normalize(reference.resolvedFile));
    }
  }
  for (const module of moduleList.values()) {
    if (module.pageLike) configuredRoots.add(module.file);
  }

  const entryPoints = [...configuredRoots];
  const queue = [...entryPoints];
  const reachable = new Set<string>();
  while (queue.length > 0) {
    const current = queue.shift();
    if (!current || reachable.has(current)) continue;
    reachable.add(current);
    for (const record of imports) {
      if (path.normalize(record.file) !== current) continue;
      const target = record.resolvedFile ? path.normalize(record.resolvedFile) : undefined;
      if (!target || reachable.has(target)) continue;
      if (!moduleList.has(target)) continue;
      queue.push(target);
    }
  }
  for (const module of moduleList.values()) {
    module.entry = entryPoints.includes(module.file);
    module.reachable = reachable.has(module.file);
  }
  if (entryPoints.length === 0) {
    warnings.push('No application entry points were detected; unused-module findings are skipped.');
  }

  const circularDependencies = findCircularDependencies(moduleList, imports, root);
  const typeOnlyImports = buildTypeOnlyImportRecords(imports);

  const sourceFiles: SourceFileInfo[] = [...moduleList.values()].map((module) => ({
    file: module.file,
    relativeFile: module.relativeFile,
    type: module.type,
    lines: module.lines,
    bytes: module.bytes,
    isSfc: ['.vue', '.svelte', '.astro'].includes(path.extname(module.file).toLowerCase()),
    isTest: module.isTest,
    isDeclaration: isDeclarationFile(module.file),
  }));

  return {
    imports,
    externalImports: dedupeExternalImports(externalImports),
    assetImports,
    modules: [...moduleList.values()],
    sourceFiles,
    dynamicPatterns,
    typeOnlyImports,
    entryPoints,
    reachableFiles: [...reachable],
    circularDependencies,
    htmlReferences,
    hasDynamicModuleLoading,
    hasGlobImports,
    warnings,
  };
}

function buildTypeOnlyImportRecords(imports: ImportRecord[]): TypeOnlyImportRecord[] {
  const grouped = new Map<string, TypeOnlyImportRecord>();
  for (const record of imports) {
    if (!record.typeOnly) continue;
    const names = record.bindings.map((binding) => binding.imported);
    const key = `${record.relativeFile}|${record.specifier}`;
    const existing = grouped.get(key);
    if (existing) {
      for (const name of names) if (!existing.names.includes(name)) existing.names.push(name);
    } else {
      grouped.set(key, {
        source: record.specifier,
        file: record.file,
        relativeFile: record.relativeFile,
        names,
        ...(record.packageName ? { packageName: record.packageName } : {}),
      });
    }
  }
  return [...grouped.values()];
}

function dedupeExternalImports(records: ExternalImportRecord[]): ExternalImportRecord[] {
  const map = new Map<string, ExternalImportRecord>();
  for (const record of records) {
    const key = `${record.file}|${record.specifier}|${record.typeOnly ? 't' : 'v'}|${record.dynamic ? 'd' : 's'}`;
    const existing = map.get(key);
    if (existing) {
      for (const name of record.names) if (!existing.names.includes(name)) existing.names.push(name);
    } else {
      map.set(key, { ...record, names: [...record.names] });
    }
  }
  return [...map.values()];
}

function findCircularDependencies(
  modules: Map<string, ModuleRecordInfo>,
  imports: ImportRecord[],
  root: string,
): CircularDependencyInfo[] {
  const nodes = [...modules.keys()];
  const adjacency = new Map<string, ImportRecord[]>();
  for (const node of nodes) adjacency.set(node, []);
  for (const record of imports) {
    const from = path.normalize(record.file);
    const to = record.resolvedFile ? path.normalize(record.resolvedFile) : undefined;
    if (!to || !modules.has(from) || !modules.has(to)) continue;
    const list = adjacency.get(from);
    if (list) list.push(record);
  }

  let index = 0;
  const stack: string[] = [];
  const onStack = new Set<string>();
  const indices = new Map<string, number>();
  const lowlink = new Map<string, number>();
  const components: string[][] = [];

  const strongConnect = (node: string): void => {
    indices.set(node, index);
    lowlink.set(node, index);
    index += 1;
    stack.push(node);
    onStack.add(node);
    for (const edge of adjacency.get(node) ?? []) {
      const target = edge.resolvedFile ? path.normalize(edge.resolvedFile) : undefined;
      if (!target || !adjacency.has(target)) continue;
      if (!indices.has(target)) {
        strongConnect(target);
        lowlink.set(node, Math.min(lowlink.get(node) ?? 0, lowlink.get(target) ?? 0));
      } else if (onStack.has(target)) {
        lowlink.set(node, Math.min(lowlink.get(node) ?? 0, indices.get(target) ?? 0));
      }
    }
    if ((lowlink.get(node) ?? 0) === (indices.get(node) ?? 0)) {
      const component: string[] = [];
      while (stack.length > 0) {
        const current = stack.pop();
        if (!current) break;
        onStack.delete(current);
        component.push(current);
        if (current === node) break;
      }
      if (component.length > 1) components.push(component);
    }
  };

  for (const node of nodes) {
    if (!indices.has(node)) strongConnect(node);
  }

  const selfLoops: string[][] = [];
  for (const [node, edges] of adjacency) {
    if (edges.some((edge) => edge.resolvedFile && path.normalize(edge.resolvedFile) === node)) {
      selfLoops.push([node]);
    }
  }

  const all = [...components, ...selfLoops];
  return all.slice(0, 100).map((component) => {
    const set = new Set(component);
    const edges = imports.filter(
      (edge) =>
        set.has(path.normalize(edge.file)) &&
        edge.resolvedFile &&
        set.has(path.normalize(edge.resolvedFile)),
    );
    const typeOnly = edges.every((edge) => edge.typeOnly);
    const first = edges[0];
    return {
      files: component.map((file) => path.normalize(file)),
      relativeFiles: component.map((file) => toPosix(path.relative(root, file))),
      ...(first ? { line: first.line } : {}),
      typeOnly,
    };
  });
}
