import path from 'node:path';
import { readFileSync } from 'node:fs';
import postcss from 'postcss';
import type { Declaration, Rule } from 'postcss';
import ts from 'typescript';
import { extractSfc } from '../static/sfc.js';
import { toPosix } from '../util/fs.js';

export interface CssInJsDeclaration {
  prop: string;
  value: string;
  line: number;
  column: number;
}

export interface CssInJsSelector {
  selector: string;
  line: number;
  column: number;
  declarations: string[];
  declarationKey: string;
}

export interface CssInJsBlock {
  file: string;
  relativeFile: string;
  tag: string;
  kind: 'global' | 'component';
  startLine: number;
  endLine: number;
  cssText: string;
  dynamic: boolean;
  declarations: CssInJsDeclaration[];
  selectors: CssInJsSelector[];
  declarationKey: string;
}

interface TemplateInfo {
  text: string;
  startOffset: number;
  endOffset: number;
  dynamic: boolean;
}

const CSS_IN_JS_TAG = /(?:^|[.(])(?:styled|css|createGlobalStyle|injectGlobal|keyframes|Global|sx)\b/;

function templateInfo(template: ts.TemplateLiteral, sourceFile: ts.SourceFile): TemplateInfo {
  const startOffset = template.getStart(sourceFile) + 1;
  const endOffset = Math.max(startOffset, template.getEnd() - 1);
  const source = sourceFile.text.slice(startOffset, endOffset);
  if (!ts.isTemplateExpression(template)) {
    return { text: source, startOffset, endOffset, dynamic: false };
  }
  const replaced = source.replace(/\$\{[\s\S]*?\}/g, (match) =>
    `0${' '.repeat(Math.max(0, match.length - 1))}`,
  );
  return { text: replaced, startOffset, endOffset, dynamic: true };
}

function positionAt(sourceFile: ts.SourceFile, offset: number): { line: number; column: number } {
  const position = sourceFile.getLineAndCharacterOfPosition(Math.max(0, offset));
  return { line: position.line + 1, column: position.character + 1 };
}

function declarationsKey(declarations: string[]): string {
  return declarations
    .map((declaration) => declaration.replace(/\s+/g, ' ').trim())
    .filter(Boolean)
    .sort()
    .join('|');
}

function collectStyles(
  node: postcss.ChildNode,
  sourceFile: ts.SourceFile,
  contentStart: number,
  selectors: CssInJsSelector[],
  declarations: CssInJsDeclaration[],
  insideGlobalRule: boolean,
): void {
  if (node.type === 'decl') {
    const decl = node as Declaration;
    const offset = contentStart + (decl.source?.start?.offset ?? 0);
    const position = positionAt(sourceFile, offset);
    declarations.push({
      prop: decl.prop,
      value: decl.value,
      line: position.line,
      column: position.column,
    });
    return;
  }
  if (node.type === 'rule') {
    const rule = node as Rule;
    const ruleDeclarations: string[] = [];
    for (const child of rule.nodes ?? []) {
      if (child.type === 'decl') {
        const decl = child as Declaration;
        ruleDeclarations.push(`${decl.prop}: ${decl.value}${decl.important ? ' !important' : ''}`);
      }
    }
    const offset = contentStart + (rule.source?.start?.offset ?? 0);
    const position = positionAt(sourceFile, offset);
    selectors.push({
      selector: rule.selector.trim(),
      line: position.line,
      column: position.column,
      declarations: ruleDeclarations,
      declarationKey: declarationsKey(ruleDeclarations),
    });
    for (const child of rule.nodes ?? []) {
      collectStyles(child, sourceFile, contentStart, selectors, declarations, insideGlobalRule);
    }
    return;
  }
  if (node.type === 'atrule') {
    for (const child of node.nodes ?? []) {
      collectStyles(child, sourceFile, contentStart, selectors, declarations, insideGlobalRule);
    }
  }
  void insideGlobalRule;
}

function extractFromSource(
  file: string,
  root: string,
  code: string,
  sourceKind: ts.ScriptKind,
  warnings: string[],
): CssInJsBlock[] {
  const sourceFile = ts.createSourceFile(`${file}.cum-css-in-js.ts`, code, ts.ScriptTarget.Latest, true, sourceKind);
  const blocks: CssInJsBlock[] = [];
  const visit = (node: ts.Node): void => {
    if (ts.isTaggedTemplateExpression(node)) {
      const tag = node.tag.getText(sourceFile);
      if (CSS_IN_JS_TAG.test(`(${tag}`)) {
        const info = templateInfo(node.template, sourceFile);
        const kind: CssInJsBlock['kind'] = /styled|sx/.test(tag) ? 'component' : 'global';
        const textForParse = info.text.trim();
        if (textForParse) {
          try {
            const parsed = postcss.parse(info.text, { from: file });
            const selectors: CssInJsSelector[] = [];
            const declarations: CssInJsDeclaration[] = [];
            for (const child of parsed.nodes) {
              collectStyles(child, sourceFile, info.startOffset, selectors, declarations, false);
            }
            const start = positionAt(sourceFile, info.startOffset);
            const end = positionAt(sourceFile, info.endOffset);
            const directKeys = declarations.map((declaration) => `${declaration.prop}: ${declaration.value}`);
            blocks.push({
              file,
              relativeFile: toPosix(path.relative(root, file)),
              tag,
              kind,
              startLine: start.line,
              endLine: end.line,
              cssText: info.text.slice(0, 4_000),
              dynamic: info.dynamic,
              declarations,
              selectors,
              declarationKey: declarationsKey(directKeys),
            });
          } catch (error) {
            warnings.push(
              `Could not parse CSS-in-JS template in ${toPosix(path.relative(root, file))}: ${error instanceof Error ? error.message : String(error)}`,
            );
          }
        }
      }
    }
    ts.forEachChild(node, visit);
  };
  visit(sourceFile);
  return blocks;
}

/** Extracts source-mapped CSS from common CSS-in-JS tagged templates. */
export function extractCssInJs(root: string, scriptFiles: string[], warnings: string[], signal?: AbortSignal): CssInJsBlock[] {
  const blocks: CssInJsBlock[] = [];
  for (const file of scriptFiles) {
    if (signal?.aborted) break;
    let raw: string;
    try {
      raw = readFileSync(file, 'utf8');
    } catch {
      continue;
    }
    const extension = path.extname(file).toLowerCase();
    const sourceKind = extension === '.tsx' || extension === '.jsx'
      ? ts.ScriptKind.TSX
      : extension === '.js' || extension === '.jsx'
        ? ts.ScriptKind.JS
        : ts.ScriptKind.TS;
    if (['.vue', '.svelte', '.astro'].includes(extension)) {
      const extraction = extractSfc(file, raw);
      if (extraction?.virtualContent) {
        blocks.push(
          ...extractFromSource(
            file,
            root,
            extraction.virtualContent,
            extraction.scriptKind === 'tsx'
              ? ts.ScriptKind.TSX
              : extraction.scriptKind === 'jsx'
                ? ts.ScriptKind.JSX
                : extraction.scriptKind === 'js'
                  ? ts.ScriptKind.JS
                  : ts.ScriptKind.TS,
            warnings,
          ),
        );
      }
    } else {
      blocks.push(...extractFromSource(file, root, raw, sourceKind, warnings));
    }
  }
  return blocks;
}

/** Normalizes CSS declarations from a runtime rule body for source correlation. */
export function declarationKeyFromRuleText(ruleText: string): string {
  const start = ruleText.indexOf('{');
  const end = ruleText.lastIndexOf('}');
  if (start < 0 || end <= start) return '';
  const body = ruleText.slice(start + 1, end);
  try {
    const parsed = postcss.parse(`.__cum {${body}}`);
    const declarations: string[] = [];
    const visit = (nodes: postcss.ChildNode[] | undefined): void => {
      for (const node of nodes ?? []) {
        if (node.type === 'decl') {
          declarations.push(`${node.prop}: ${node.value}${node.important ? ' !important' : ''}`);
        } else if ('nodes' in node) {
          visit(node.nodes as postcss.ChildNode[] | undefined);
        }
      }
    };
    visit(parsed.nodes);
    return declarationsKey(declarations);
  } catch {
    return '';
  }
}
