#!/usr/bin/env node
import path from 'node:path';
import { existsSync, readFileSync, statSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { stdin } from 'node:process';
import { spawn } from 'node:child_process';
import fg from 'fast-glob';
import { Command } from 'commander';
import pc from 'picocolors';
import type {
  CodeUsageMapConfig,
  ResolvedCodeUsageMapConfig,
  RouteInput,
  ThresholdConfig,
  UsageReport,
} from '../types.js';
import { TOOL_VERSION } from '../version.js';
import { loadResolvedConfig } from '../config.js';
import { runFullAnalysis } from '../core/analyze.js';
import { writeBaseline, writeReports } from '../report/write.js';
import { renderConsoleReport } from '../report/console.js';
import { compareReports, formatComparison } from '../compare/compare.js';
import { clearRuntimeSessions } from '../runtime/store.js';
import { collectRuntime } from '../runtime/collect.js';
import { startStaticServer, type StaticServerHandle } from '../runtime/server.js';
import {
  applyFixPreview,
  buildFixPreview,
  formatFixPreview,
  revertLatestFix,
} from '../autofix/fix.js';
import { createLogger } from '../util/logger.js';
import { formatBytes, splitComma, toPosix, writeTextFile } from '../util/fs.js';

const program = new Command();
const abortController = new AbortController();
let abortAnnounced = false;

program
  .name('code-usage-map')
  .description('Discover unused JavaScript and CSS, trace every finding to its original source, optimize every route.')
  .version(TOOL_VERSION, '-v, --version')
  .option('--config <file>', 'configuration file')
  .option('--cwd <directory>', 'working directory')
  .showHelpAfterError();

function globalOptions(): { config?: string; cwd?: string } {
  return program.opts<{ config?: string; cwd?: string }>();
}

function resolveRoot(directory?: string): string {
  const cwd = globalOptions().cwd ? path.resolve(globalOptions().cwd ?? '.') : process.cwd();
  return path.resolve(cwd, directory ?? '.');
}

function resolveConfigPath(root: string): string | undefined {
  const configured = globalOptions().config;
  if (!configured) return undefined;
  const resolved = path.isAbsolute(configured) ? configured : path.resolve(root, configured);
  if (!existsSync(resolved)) {
    throw new Error(`Config file not found: ${resolved}`);
  }
  return resolved;
}

async function loadCommandConfig(
  root: string,
  options: { silent?: boolean } = {},
): Promise<{ config: ResolvedCodeUsageMapConfig; configFile?: string; logger: ReturnType<typeof createLogger> }> {
  const loaded = await loadResolvedConfig(root, resolveConfigPath(root));
  if (loaded.issues.length > 0) {
    throw new Error(loaded.issues.map((issue) => `${issue.path}: ${issue.message}`).join('\n'));
  }
  const logger = createLogger(loaded.config.logging.level);
  for (const warning of loaded.warnings) {
    if (warning.startsWith('Using config:')) continue;
    logger.warn(warning);
  }
  if (!options.silent && loaded.configFile) {
    logger.info(pc.gray(`Config: ${toPosix(path.relative(root, loaded.configFile))}`));
  }
  return { config: loaded.config, ...(loaded.configFile ? { configFile: loaded.configFile } : {}), logger };
}

function splitPaths(value: string | undefined): string[] {
  return value ? splitComma(value) : [];
}

function parseRoutes(value: string | undefined): RouteInput[] {
  return splitPaths(value).map((item) => (item.startsWith('http') ? { url: item } : { path: item }));
}

function applyCliOverrides(
  config: ResolvedCodeUsageMapConfig,
  root: string,
  options: Record<string, unknown>,
): void {
  const source = splitPaths(typeof options.source === 'string' ? options.source : undefined);
  if (source.length > 0) config.source = source.map((item) => path.resolve(root, item));
  if (typeof options.output === 'string' && options.output.trim()) {
    config.output = path.resolve(root, options.output);
  }
  if (typeof options.mode === 'string' && (options.mode === 'application' || options.mode === 'library')) {
    config.mode = options.mode;
  }
  const routes = parseRoutes(typeof options.routes === 'string' ? options.routes : undefined);
  if (routes.length > 0) config.routes = routes;
  if (options.js === false) config.analysis.javascript = false;
  if (options.ts === false) config.analysis.typescript = false;
  if (options.css === false) config.analysis.css = false;
  if (options.deps === false) config.analysis.dependencies = false;
  if (options.bundles === false) config.analysis.bundles = false;
  if (options.runtime === false) config.analysis.runtime = false;
  if (options.sourceMaps === false) {
    config.analysis.sourceMaps = false;
    config.sourceMaps.enabled = false;
  }
  if (options.recommendations === false) config.analysis.recommendations = false;
  if (options.cache === false) config.cache.enabled = false;
  if (options.quiet === true) config.logging.level = 'silent';
  else if (options.verbose === true) config.logging.level = 'debug';
}

function progressLogger(_logger: ReturnType<typeof createLogger>, enabled: boolean) {
  if (!enabled) return undefined;
  return (event: { message: string }): void => {
    process.stdout.write(`${pc.gray(`• ${event.message}`)}\n`);
  };
}

function openReport(file: string | undefined): void {
  if (!file || !existsSync(file)) return;
  try {
    if (process.platform === 'win32') {
      spawn('cmd', ['/c', 'start', '', file], { detached: true, stdio: 'ignore' }).unref();
    } else if (process.platform === 'darwin') {
      spawn('open', [file], { detached: true, stdio: 'ignore' }).unref();
    } else {
      spawn('xdg-open', [file], { detached: true, stdio: 'ignore' }).unref();
    }
  } catch {
    // Opening the browser is optional.
  }
}

function writeRuntimeSummary(message: string): void {
  process.stderr.write(`${pc.gray('•')} ${message}\n`);
}

function syncLoggingLevel(logger: ReturnType<typeof createLogger>, config: ResolvedCodeUsageMapConfig): void {
  logger.level = config.logging.level;
}

function packageManagerCommand(root: string): string {
  try {
    const pkg = JSON.parse(readFileSync(path.join(root, 'package.json'), 'utf8')) as { packageManager?: string };
    const declared = pkg.packageManager?.split('@')[0];
    if (declared) return declared;
  } catch {
    // Fall back to lockfile detection.
  }
  if (existsSync(path.join(root, 'pnpm-lock.yaml'))) return 'pnpm';
  if (existsSync(path.join(root, 'yarn.lock'))) return 'yarn';
  if (existsSync(path.join(root, 'bun.lockb')) || existsSync(path.join(root, 'bun.lock'))) return 'bun';
  return 'npm';
}

function runProjectBuild(
  root: string,
  config: ResolvedCodeUsageMapConfig,
  logger: ReturnType<typeof createLogger>,
  jsonMode: boolean,
): void {
  let command = config.build.command;
  if (!command) {
    let hasBuildScript = false;
    try {
      const pkg = JSON.parse(readFileSync(path.join(root, 'package.json'), 'utf8')) as {
        scripts?: Record<string, string>;
      };
      hasBuildScript = Boolean(pkg.scripts?.build);
    } catch {
      hasBuildScript = false;
    }
    if (!hasBuildScript) {
      throw new Error('--build was requested but no build.command or package.json build script exists.');
    }
    command = `${packageManagerCommand(root)} run build`;
  }
  logger.info(pc.gray(`Running production build: ${command}`));
  const result = spawnSync(command, {
    cwd: root,
    shell: true,
    encoding: 'utf8',
    timeout: 20 * 60_000,
    env: process.env,
  });
  const output = `${result.stdout ?? ''}${result.stderr ?? ''}`.trim();
  if (output) {
    if (jsonMode) process.stderr.write(`${output}\n`);
    else process.stdout.write(`${output}\n`);
  }
  if (result.status !== 0) {
    throw new Error(
      `Build command failed with exit code ${result.status ?? 'unknown'}${output ? `:\n${output.slice(-4_000)}` : ''}`,
    );
  }
}

function printArtifacts(paths: { jsonPath?: string; htmlPath?: string; patchPath?: string }): void {
  if (paths.jsonPath) process.stdout.write(`${pc.green('JSON')}  ${paths.jsonPath}\n`);
  if (paths.htmlPath) process.stdout.write(`${pc.green('HTML')}  ${paths.htmlPath}\n`);
  if (paths.patchPath) process.stdout.write(`${pc.green('PATCH')} ${paths.patchPath}\n`);
}

function extractReportFromFile(file: string): UsageReport {
  const raw = readFileSync(file, 'utf8');
  const parsed = JSON.parse(raw) as UsageReport;
  if (!parsed || typeof parsed !== 'object' || !parsed.summary || !Array.isArray(parsed.findings)) {
    throw new Error(`Not a Code Usage Map report: ${file}`);
  }
  return parsed;
}

function thresholdOverrides(config: ThresholdConfig, options: Record<string, unknown>): ThresholdConfig {
  const next: ThresholdConfig = { ...config };
  const numeric = (value: unknown): number | undefined => {
    if (value === undefined || value === null || value === '') return undefined;
    const number = Number(value);
    return Number.isFinite(number) && number >= 0 ? number : undefined;
  };
  const mappings: Array<[keyof ThresholdConfig, unknown]> = [
    ['maxTotalBundleBytes', options.maxTotalBundleBytes],
    ['maxBundleGrowthBytes', options.maxBundleGrowthBytes],
    ['maxBundleGrowthPercent', options.maxBundleGrowthPercent],
    ['maxCssGrowthBytes', options.maxCssGrowthBytes],
    ['maxCssGrowthPercent', options.maxCssGrowthPercent],
    ['maxNewFindings', options.maxNewFindings],
    ['maxRouteGrowthPercent', options.maxRouteGrowthPercent],
  ];
  for (const [key, value] of mappings) {
    const parsed = numeric(value);
    if (parsed !== undefined) {
      (next as Record<string, unknown>)[key] = parsed;
    }
  }
  if (typeof options.failOn === 'string' && options.failOn.trim()) {
    next.failOn = splitComma(options.failOn) as NonNullable<ThresholdConfig['failOn']>;
  }
  return next;
}

function routeFromHtml(relative: string): string {
  const without = relative.replace(/\.html?$/i, '');
  if (without === 'index' || without.endsWith('/index')) {
    return `/${without.replace(/\/?index$/, '')}`.replace(/\/+/g, '/');
  }
  return `/${without}`.replace(/\/+/g, '/');
}

async function discoverServerRoutes(directory: string): Promise<RouteInput[]> {
  const files = await fg('**/*.html', {
    cwd: directory,
    onlyFiles: true,
    ignore: ['**/404.html', '**/500.html'],
  });
  const routes = new Set<string>();
  for (const file of files) {
    const route = routeFromHtml(toPosix(file));
    if (route !== '/') routes.add(route);
  }
  routes.add('/');
  return [...routes].sort().map((route) => ({ path: route }));
}

function chooseServeDirectory(config: ResolvedCodeUsageMapConfig, root: string): string | undefined {
  const candidates = [
    ...(config.build.dir
      ? Array.isArray(config.build.dir)
        ? config.build.dir
        : [config.build.dir]
      : []),
    path.join(root, 'dist'),
    path.join(root, 'build'),
    path.join(root, 'out'),
    path.join(root, 'public'),
  ];
  for (const candidate of candidates) {
    const dir = path.resolve(root, candidate);
    if (!existsSync(dir)) continue;
    try {
      if (statSync(dir).isDirectory() && existsSync(path.join(dir, 'index.html'))) return dir;
    } catch {
      // Ignore candidates that disappear.
    }
  }
  return undefined;
}

async function scanCommand(directory: string | undefined, options: Record<string, unknown>): Promise<void> {
  const root = resolveRoot(directory);
  const { config, configFile, logger } = await loadCommandConfig(root);
  applyCliOverrides(config, root, options);
  syncLoggingLevel(logger, config);
  const jsonMode = options.json === true;
  if (options.build === true) runProjectBuild(root, config, logger, jsonMode);
  const progress = progressLogger(logger, !jsonMode && config.logging.level !== 'silent');
  const context = await runFullAnalysis({
    root,
    config,
    ...(configFile ? { configPath: configFile } : {}),
    ...(options.refresh === true ? { refresh: true } : {}),
    signal: abortController.signal,
    ...(progress ? { onProgress: progress } : {}),
    command: 'scan',
  });

  const written = writeReports(context.report, {
    console: false,
    ...(options.jsonFile === false ? { json: false } : {}),
    ...(options.html === false ? { html: false } : {}),
  });

  let baselinePath = typeof options.baseline === 'string' ? path.resolve(root, options.baseline) : config.baseline;
  if (typeof options.saveBaseline === 'string') {
    baselinePath = writeBaseline(context.report, options.saveBaseline);
    logger.info(`Saved baseline: ${baselinePath}`);
  }

  if (!jsonMode && options.console !== false && config.reporters.console) {
    process.stdout.write(renderConsoleReport(context.report));
    printArtifacts(written);
    if (written.htmlPath) process.stdout.write(pc.gray(`Open the report: ${written.htmlPath}\n`));
  }

  if (jsonMode) {
    process.stdout.write(`${JSON.stringify(context.report, null, 2)}\n`);
  }

  if (options.open === true) openReport(written.htmlPath);

  if (options.ci === true || (options.baseline !== undefined && baselinePath)) {
    if (baselinePath && existsSync(baselinePath)) {
      const baseline = extractReportFromFile(baselinePath);
      const comparison = compareReports(baseline, context.report, config.thresholds, baselinePath);
      if (!jsonMode) {
        process.stdout.write(`\n${formatComparison(comparison)}\n`);
      } else if (comparison.regressions.length > 0) {
        process.stderr.write(`${formatComparison(comparison)}\n`);
      }
      if (!comparison.passed) process.exitCode = 1;
    } else if (config.thresholds.maxTotalBundleBytes !== undefined) {
      if (context.report.bundles.totals.rawBytes > config.thresholds.maxTotalBundleBytes) {
        logger.error(
          `Bundle size ${formatBytes(context.report.bundles.totals.rawBytes)} exceeds the limit ${formatBytes(config.thresholds.maxTotalBundleBytes)}.`,
        );
        process.exitCode = 1;
      }
    } else if (options.ci === true && !jsonMode) {
      logger.warn('CI mode has no baseline; only absolute bundle-size limits can fail. Use --save-baseline and compare for regressions.');
    }
  }
}

async function analyzeCommand(directory: string | undefined, options: Record<string, unknown>): Promise<void> {
  const root = resolveRoot(directory);
  const { config, logger } = await loadCommandConfig(root);
  applyCliOverrides(config, root, options);
  syncLoggingLevel(logger, config);
  if (!config.runtime.enabled) throw new Error('Runtime collection is disabled in configuration.');
  const jsonMode = options.json === true;
  const progress = progressLogger(logger, !jsonMode && config.logging.level !== 'silent');
  if (options.clean === true) {
    const removed = clearRuntimeSessions(root);
    logger.info(`Removed ${removed} previous runtime session(s).`);
  }
  if (options.build === true) {
    runProjectBuild(root, config, logger, jsonMode);
    if (typeof options.url === 'string') {
      logger.warn('--build completed, but --url points at an already-running server. The browser will not automatically serve the new build.');
    }
  }

  let baseUrl = typeof options.url === 'string' ? options.url : config.runtime.baseUrl;
  let server: StaticServerHandle | undefined;
  let discoveredRoutes: RouteInput[] = [];
  if (!baseUrl) {
    const serveOption = options.serve;
    const serveDirectory =
      typeof serveOption === 'string'
        ? path.resolve(root, serveOption)
        : serveOption === true
          ? chooseServeDirectory(config, root)
          : chooseServeDirectory(config, root);
    if (!serveDirectory || !existsSync(path.join(serveDirectory, 'index.html'))) {
      throw new Error(
        'No runtime URL was provided and no servable build directory with index.html was found. Pass --url http://localhost:5173 or --serve <dir>.',
      );
    }
    server = await startStaticServer(serveDirectory);
    baseUrl = server.baseUrl;
    logger.info(`Serving ${serveDirectory} at ${baseUrl}`);
    discoveredRoutes = await discoverServerRoutes(serveDirectory);
    if (discoveredRoutes.length > 1) logger.info(`Discovered ${discoveredRoutes.length} HTML page route(s).`);
  }

  const cliRoutes = parseRoutes(typeof options.routes === 'string' ? options.routes : undefined);
  const routes = cliRoutes.length > 0 ? cliRoutes : config.routes.length > 0 ? config.routes : discoveredRoutes;
  const interactiveDefault =
    !routes.length &&
    !options.headless &&
    !jsonMode &&
    Boolean(stdin.isTTY) &&
    options.interactive !== false;
  const interactive = options.interactive === true || interactiveDefault;
  const browser =
    typeof options.browser === 'string' && ['chromium', 'firefox', 'webkit'].includes(options.browser)
      ? (options.browser as 'chromium' | 'firefox' | 'webkit')
      : config.runtime.browser;

  let collectResult: Awaited<ReturnType<typeof collectRuntime>>;
  try {
    collectResult = await collectRuntime({
      root,
      config,
      options: {
        ...(baseUrl ? { baseUrl } : {}),
        ...(routes.length > 0 ? { routes: routes.length > 0 ? routes : [{ path: '/' }] } : {}),
        browser,
        headless: options.headed === true ? false : interactive ? false : options.headless === true ? true : config.runtime.headless,
        interactive,
        signal: abortController.signal,
        ...(progress ? { onProgress: progress } : {}),
      },
      persist: true,
    });
  } finally {
    await server?.close();
  }

  if (!jsonMode && config.logging.level !== 'silent') {
    writeRuntimeSummary(
      `Collected ${collectResult.sessions.length} session(s), ${collectResult.result.routes.length} route(s), base ${collectResult.result.baseUrl}.`,
    );
  }

  if (options.report === false) {
    if (jsonMode) process.stdout.write(`${JSON.stringify(collectResult.result, null, 2)}\n`);
    return;
  }

  const analysis = await runFullAnalysis({
    root,
    config,
    ...(progress ? { onProgress: progress } : {}),
    signal: abortController.signal,
    command: 'analyze',
    runtimeSessions: collectResult.sessions,
  });
  const written = writeReports(analysis.report, {
    console: false,
    ...(options.jsonFile === false ? { json: false } : {}),
    ...(options.html === false ? { html: false } : {}),
  });
  if (jsonMode) {
    process.stdout.write(`${JSON.stringify(analysis.report, null, 2)}\n`);
  } else if (config.reporters.console) {
    process.stdout.write(renderConsoleReport(analysis.report));
    printArtifacts(written);
  }
  if (options.open === true) openReport(written.htmlPath);
}

async function reportCommand(directory: string | undefined, options: Record<string, unknown>): Promise<void> {
  const root = resolveRoot(directory);
  const { config, configFile, logger } = await loadCommandConfig(root);
  applyCliOverrides(config, root, options);
  syncLoggingLevel(logger, config);
  const jsonMode = options.json === true;
  const progress = progressLogger(logger, !jsonMode && config.logging.level !== 'silent');
  if (options.build === true) runProjectBuild(root, config, logger, jsonMode);
  let report: UsageReport;
  const from = typeof options.from === 'string' ? path.resolve(root, options.from) : undefined;
  if (from) {
    report = extractReportFromFile(from);
  } else {
    const context = await runFullAnalysis({
      root,
      config,
      ...(configFile ? { configPath: configFile } : {}),
      ...(options.refresh === true ? { refresh: true } : {}),
      ...(progress ? { onProgress: progress } : {}),
      command: 'report',
    });
    report = context.report;
  }
  const written = writeReports(report, {
    console: false,
    ...(options.jsonFile === false ? { json: false } : {}),
    ...(options.html === false ? { html: false } : {}),
  });
  if (jsonMode) process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
  else if (config.reporters.console) {
    process.stdout.write(renderConsoleReport(report));
    printArtifacts(written);
  }
  if (options.open === true) openReport(written.htmlPath);
}

async function compareCommand(directory: string | undefined, options: Record<string, unknown>): Promise<void> {
  const root = resolveRoot(directory);
  const { config, logger } = await loadCommandConfig(root);
  applyCliOverrides(config, root, options);
  syncLoggingLevel(logger, config);
  const baselinePath = typeof options.baseline === 'string'
    ? path.resolve(root, options.baseline)
    : config.baseline;
  if (!baselinePath) {
    throw new Error('compare needs --baseline <report.json> or a baseline path in configuration.');
  }
  if (!existsSync(baselinePath)) throw new Error(`Baseline report not found: ${baselinePath}`);
  const baseline = extractReportFromFile(baselinePath);
  let current: UsageReport;
  const currentPath = typeof options.current === 'string' ? path.resolve(root, options.current) : undefined;
  if (currentPath) current = extractReportFromFile(currentPath);
  else {
    if (options.build === true) runProjectBuild(root, config, logger, options.json === true);
    const context = await runFullAnalysis({
      root,
      config,
      ...(options.refresh === true ? { refresh: true } : {}),
      signal: abortController.signal,
      ...(options.json === true || config.logging.level === 'silent'
        ? {}
        : { onProgress: progressLogger(logger, true) }),
      command: 'compare',
    });
    current = context.report;
  }
  const thresholds = thresholdOverrides(config.thresholds, options);
  const comparison = compareReports(baseline, current, thresholds, baselinePath, currentPath);
  if (options.json === true) process.stdout.write(`${JSON.stringify(comparison, null, 2)}\n`);
  else process.stdout.write(`${formatComparison(comparison)}\n`);
  if (!comparison.passed) process.exitCode = 1;
}

async function fixCommand(directory: string | undefined, options: Record<string, unknown>): Promise<void> {
  const root = resolveRoot(directory);
  const { config, logger } = await loadCommandConfig(root);
  applyCliOverrides(config, root, options);
  syncLoggingLevel(logger, config);
  if (options.revert === true) {
    const reverted = revertLatestFix(config.output);
    if (options.json === true) process.stdout.write(`${JSON.stringify(reverted, null, 2)}\n`);
    else if (reverted.reverted) {
      process.stdout.write(`Restored ${reverted.files.length} file(s) from ${reverted.backupDir ?? 'backup'}.\n`);
    } else {
      logger.warn(reverted.reason ?? 'Nothing to revert.');
    }
    return;
  }

  const reportPath = typeof options.report === 'string'
    ? path.resolve(root, options.report)
    : path.join(config.output, 'code-usage-map.json');
  if (!existsSync(reportPath)) {
    throw new Error(`No report found at ${reportPath}. Run "code-usage-map scan" first or pass --report.`);
  }
  const report = extractReportFromFile(reportPath);
  const findingIds = splitPaths(typeof options.finding === 'string' ? options.finding : undefined);
  const selected = findingIds.length > 0 ? findingIds : undefined;
  const preview = buildFixPreview({
    root,
    config,
    findings: report.findings,
    ...(selected ? { findingIds: selected } : {}),
    writePatch: true,
  });
  const apply = options.apply === true;
  const result = apply
    ? applyFixPreview({ root, config, preview })
    : { ...preview, applied: false, changedFiles: [] };
  if (options.json === true) {
    process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
  } else {
    process.stdout.write(`${formatFixPreview(preview)}\n`);
    if (apply && result.applied) {
      process.stdout.write(
        `\nApplied ${result.fixes.length} fix(es) to ${result.changedFiles.length} file(s). Backups: ${result.backupDir}\n`,
      );
      process.stdout.write('Revert with: npx @codewithrajat/code-usage-map fix --revert\n');
    } else if (apply) {
      process.stdout.write('\nNo safe fixes were applied.\n');
    } else {
      process.stdout.write('\nDry run only. Re-run with --apply to write these edits.\n');
    }
    if (result.patchPath) process.stdout.write(pc.green(`Patch: ${result.patchPath}\n`));
  }
}

async function initCommand(directory: string | undefined, options: Record<string, unknown>): Promise<void> {
  const root = resolveRoot(directory);
  if (!existsSync(root) || !statSync(root).isDirectory()) {
    throw new Error(`Directory does not exist: ${root}`);
  }
  const explicitConfig = globalOptions().config;
  const configPath = explicitConfig
    ? path.resolve(root, explicitConfig)
    : path.join(root, 'code-usage-map.config.ts');
  if (existsSync(configPath) && options.force !== true) {
    throw new Error(`Configuration already exists: ${configPath}. Use --force to overwrite.`);
  }
  const source = existsSync(path.join(root, 'src')) ? './src' : existsSync(path.join(root, 'app')) ? './app' : '.';
  const configObject: CodeUsageMapConfig = {
    source,
    output: './code-usage-map-report',
    analysis: {
      javascript: true,
      typescript: true,
      css: true,
      runtime: true,
      sourceMaps: true,
    },
    routes: [],
  };
  const content = `import type { CodeUsageMapConfig } from '@codewithrajat/code-usage-map';

const config: CodeUsageMapConfig = ${JSON.stringify(configObject, null, 2)};
// Add routes that should be exercised by runtime analysis, for example:
// routes: ['/', '/dashboard', '/settings'],

export default config;
`;
  writeTextFile(configPath, content);
  if (options.json === true) {
    process.stdout.write(`${JSON.stringify({ configPath, config: configObject }, null, 2)}\n`);
    return;
  }
  process.stdout.write(`${pc.green('Created')} ${configPath}\n\n`);
  process.stdout.write('Next steps:\n');
  process.stdout.write(`  1. ${pc.cyan('npx @codewithrajat/code-usage-map scan')}\n`);
  process.stdout.write(`  2. Start the app and run ${pc.cyan('npx @codewithrajat/code-usage-map analyze --url http://localhost:5173')}\n`);
  process.stdout.write(`  3. Open the generated HTML report; no server or upload is required.\n\n`);
  process.stdout.write(pc.gray('Add `.code-usage-map/` and `code-usage-map-report/` to .gitignore if desired.\n'));
}

