import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import fg from 'fast-glob';
import type {
  BuildToolDetection,
  FrameworkDetection,
  SourceFileType,
} from '../types.js';
import { normalizeSlashes, toPosix } from '../util/fs.js';

export interface PackageJson {
  name?: string;
  version?: string;
  type?: string;
  packageManager?: string;
  main?: string;
  module?: string;
  browser?: string;
  source?: string;
  scripts?: Record<string, string>;
  dependencies?: Record<string, string>;
  devDependencies?: Record<string, string>;
  peerDependencies?: Record<string, string>;
  optionalDependencies?: Record<string, string>;
}

export interface ProjectDetection {
  root: string;
  name: string;
  version?: string;
  packageJsonPath?: string;
  packageJson?: PackageJson;
  packageManager: string;
  frameworks: FrameworkDetection[];
  buildTools: BuildToolDetection[];
  sourceRoots: string[];
  buildDirs: string[];
  detectedEntryPoints: string[];
  tsconfig?: string;
  filesByLanguage: Record<string, number>;
  textFiles: string[];
  supportedFiles: string[];
  templateFiles: string[];
}

const FRAMEWORKS: Array<{ name: string; pkg: string }> = [
  { name: 'React', pkg: 'react' },
  { name: 'Preact', pkg: 'preact' },
  { name: 'Vue', pkg: 'vue' },
  { name: 'Angular', pkg: '@angular/core' },
  { name: 'Svelte', pkg: 'svelte' },
  { name: 'Solid', pkg: 'solid-js' },
  { name: 'Next.js', pkg: 'next' },
  { name: 'Nuxt', pkg: 'nuxt' },
  { name: 'Astro', pkg: 'astro' },
  { name: 'Lit / Web Components', pkg: 'lit' },
  { name: 'Ember', pkg: 'ember-source' },
  { name: 'Qwik', pkg: '@builder.io/qwik' },
];

const BUILD_TOOLS: Array<{ name: string; pkg: string; configs: string[] }> = [
  { name: 'Vite', pkg: 'vite', configs: ['vite.config.ts', 'vite.config.js', 'vite.config.mjs', 'vite.config.mts'] },
  { name: 'Webpack', pkg: 'webpack', configs: ['webpack.config.js', 'webpack.config.ts', 'webpack.config.cjs', 'webpack.config.mjs'] },
  { name: 'Rollup', pkg: 'rollup', configs: ['rollup.config.js', 'rollup.config.ts', 'rollup.config.mjs'] },
  { name: 'esbuild', pkg: 'esbuild', configs: ['esbuild.config.js', 'esbuild.config.mjs', 'esbuild.config.ts'] },
  { name: 'Parcel', pkg: 'parcel', configs: ['.parcelrc'] },
  { name: 'Angular CLI', pkg: '@angular/cli', configs: ['angular.json'] },
  { name: 'Next.js', pkg: 'next', configs: ['next.config.js', 'next.config.mjs', 'next.config.ts'] },
  { name: 'Nuxt', pkg: 'nuxt', configs: ['nuxt.config.ts', 'nuxt.config.js'] },
  { name: 'Astro', pkg: 'astro', configs: ['astro.config.mjs', 'astro.config.ts', 'astro.config.js'] },
];

const SOURCE_FILE_GLOBS = [
  '**/*.{js,jsx,mjs,cjs,ts,tsx,mts,cts}',
  '**/*.{css,scss,sass,less}',
  '**/*.{html,htm}',
  '**/*.{vue,svelte,astro}',
];

const DEFAULT_EXCLUDES = [
  '**/node_modules/**',
  '**/.git/**',
  '**/.hg/**',
  '**/.svn/**',
  '**/coverage/**',
  '**/.nyc_output/**',
  '**/.cache/**',
  '**/.turbo/**',
  '**/.parcel-cache/**',
  '**/.vite/**',
  '**/__snapshots__/**',
];

export const SAFE_EXCLUDE_PATTERNS = DEFAULT_EXCLUDES;

const BUILD_DIR_CANDIDATES = [
  'dist',
  'build',
  'out',
  'output',
  'www',
  'public/build',
  'public/dist',
  'storybook-static',
  '.next',
  '.next/static',
  '.nuxt',
  '.nuxt/dist/client',
  '.output/public',
  '.svelte-kit/output/client',
  '.astro',
];

const LANGUAGE_BY_EXT: Record<string, SourceFileType> = {
  '.js': 'js',
  '.jsx': 'jsx',
  '.mjs': 'mjs',
  '.cjs': 'cjs',
  '.ts': 'ts',
  '.tsx': 'tsx',
  '.mts': 'mts',
  '.cts': 'cts',
  '.css': 'css',
  '.scss': 'scss',
  '.sass': 'sass',
  '.less': 'less',
  '.html': 'html',
  '.htm': 'html',
  '.vue': 'vue',
  '.svelte': 'svelte',
  '.astro': 'astro',
  '.json': 'json',
};

export function fileType(file: string): SourceFileType {
  return LANGUAGE_BY_EXT[path.extname(file).toLowerCase()] ?? 'other';
}

export function isScriptFile(file: string): boolean {
  const type = fileType(file);
  return ['js', 'jsx', 'mjs', 'cjs', 'ts', 'tsx', 'mts', 'cts', 'vue', 'svelte', 'astro'].includes(type);
}

export function isStyleFile(file: string): boolean {
  return ['css', 'scss', 'sass', 'less'].includes(fileType(file));
}

export function isTemplateFile(file: string): boolean {
  return ['html', 'vue', 'svelte', 'astro'].includes(fileType(file));
}

export function readPackageJson(root: string): { path?: string; value?: PackageJson } {
  const file = path.join(root, 'package.json');
  if (!existsSync(file)) return {};
  try {
    // package.json is local project metadata, never executed.
    const raw = JSON.parse(readFileSync(file, 'utf8')) as unknown;
    if (raw && typeof raw === 'object') {
      return { path: file, value: raw as PackageJson };
    }
  } catch {
    return { path: file };
  }
  return { path: file };
}

function detectPackageManager(root: string, pkg?: PackageJson): string {
  const declared = pkg?.packageManager?.split('@')[0]?.trim();
  if (declared) return declared;
  if (existsSync(path.join(root, 'pnpm-lock.yaml'))) return 'pnpm';
  if (existsSync(path.join(root, 'yarn.lock'))) return 'yarn';
  if (existsSync(path.join(root, 'bun.lockb')) || existsSync(path.join(root, 'bun.lock'))) return 'bun';
  if (existsSync(path.join(root, 'package-lock.json'))) return 'npm';
  return 'npm';
}

export function detectProject(
  root: string,
  options: {
    source?: string[];
    buildDirs?: string[];
    tsconfig?: string;
    includeTemplates?: boolean;
  } = {},
): ProjectDetection {
  const { path: packageJsonPath, value: pkg } = readPackageJson(root);
  const dependencies = {
    ...(pkg?.dependencies ?? {}),
    ...(pkg?.devDependencies ?? {}),
  };

  const frameworks = FRAMEWORKS.filter((item) => item.pkg in dependencies).map((item) => ({
    name: item.name,
    packageName: item.pkg,
    source: 'dependency' as const,
  }));

  const buildTools: BuildToolDetection[] = [];
  for (const tool of BUILD_TOOLS) {
    const hasPackage = tool.pkg in dependencies;
    const config = tool.configs.find((name) => existsSync(path.join(root, name)));
    if (hasPackage || config) {
      buildTools.push({
        name: tool.name,
        source: hasPackage ? 'dependency' : 'config-file',
      });
    }
  }

  const configuredBuildDirs = options.buildDirs?.length
    ? options.buildDirs.map((dir) => path.resolve(root, dir))
    : [];
  const autoBuildDirs = BUILD_DIR_CANDIDATES.map((dir) => path.resolve(root, dir)).filter((dir) => existsSync(dir));
  const buildDirs = dedupePaths(configuredBuildDirs.length ? configuredBuildDirs : autoBuildDirs)
    .filter((dir) => existsSync(dir));

  for (const dir of buildDirs) {
    if (!buildTools.some((tool) => tool.name === 'Vite') && existsSync(path.join(dir, '.vite'))) {
      buildTools.push({ name: 'Vite', source: 'build-output' });
    }
    if (!buildTools.some((tool) => tool.name === 'Next.js') && path.basename(path.dirname(dir)) === '.next') {
      buildTools.push({ name: 'Next.js', source: 'build-output' });
    }
  }

  const sourceRoots = (options.source?.length ? options.source : detectSourceRoots(root)).map((dir) =>
    path.resolve(root, dir),
  );

  const tsconfigCandidate = options.tsconfig
    ? path.resolve(root, options.tsconfig)
    : ['tsconfig.json', 'tsconfig.build.json', 'jsconfig.json']
        .map((name) => path.join(root, name))
        .find((file) => existsSync(file));

  const ignore = [
    ...DEFAULT_EXCLUDES,
    ...buildDirs.map((dir) => `${toPosix(path.relative(root, dir))}/**`),
    '**/dist/**',
    '**/build/**',
    '**/.next/**',
    '**/.nuxt/**',
    '**/.svelte-kit/**',
  ];

  const files = fg.sync(SOURCE_FILE_GLOBS, {
    cwd: root,
    absolute: true,
    onlyFiles: true,
    unique: true,
    dot: false,
    ignore,
  }).map((file) => path.normalize(file));

  const filesByLanguage: Record<string, number> = {};
  const textFiles: string[] = [];
  const supportedFiles: string[] = [];
  const templateFiles: string[] = [];
  for (const file of files) {
    const type = fileType(file);
    filesByLanguage[type] = (filesByLanguage[type] ?? 0) + 1;
    if (type !== 'other') textFiles.push(file);
    if (isScriptFile(file) || isStyleFile(file) || type === 'html') supportedFiles.push(file);
    if (options.includeTemplates !== false && isTemplateFile(file)) templateFiles.push(file);
  }

  return {
    root,
    name: pkg?.name ?? path.basename(root),
    version: pkg?.version,
    packageJsonPath,
    packageJson: pkg,
    packageManager: detectPackageManager(root, pkg),
    frameworks,
    buildTools: dedupeBuildTools(buildTools),
    sourceRoots,
    buildDirs,
    detectedEntryPoints: detectEntryPoints(root, pkg, sourceRoots),
    tsconfig: tsconfigCandidate,
    filesByLanguage,
    textFiles,
    supportedFiles,
    templateFiles,
  };
}

function dedupePaths(values: string[]): string[] {
  const seen = new Set<string>();
  return values.filter((value) => {
    const normalized = path.resolve(value);
    if (seen.has(normalized)) return false;
    seen.add(normalized);
    return true;
  });
}

function dedupeBuildTools(values: BuildToolDetection[]): BuildToolDetection[] {
  const seen = new Set<string>();
  return values.filter((value) => {
    if (seen.has(value.name)) return false;
    seen.add(value.name);
    return true;
  });
}

function detectSourceRoots(root: string): string[] {
  const candidates = ['src', 'app', 'source', 'ui', 'client', 'frontend'];
  const found = candidates.filter((dir) => existsSync(path.join(root, dir)));
  if (found.length > 0) return found;
  return ['.'];
}

function detectEntryPoints(root: string, pkg: PackageJson | undefined, sourceRoots: string[]): string[] {
  const results = new Set<string>();
  const packageFields = [pkg?.source, pkg?.module, pkg?.main, pkg?.browser];
  for (const field of packageFields) {
    if (!field) continue;
    const resolved = path.resolve(root, field);
    if (existsSync(resolved) && sourceRoots.some((dir) => resolved.startsWith(dir))) {
      results.add(resolved);
    }
  }

  const globs = [
    'main.{js,jsx,ts,tsx,mjs,mts}',
    'index.{js,jsx,ts,tsx,mjs,mts}',
    'app.{js,jsx,ts,tsx,mjs,mts}',
    '**/main.{js,jsx,ts,tsx,mjs,mts}',
    '**/index.{js,jsx,ts,tsx,mjs,mts}',
    '**/App.{js,jsx,ts,tsx}',
    '**/root.{js,jsx,ts,tsx}',
    '**/+page.{js,jsx,ts,tsx,svelte,vue}',
    '**/page.{js,jsx,ts,tsx}',
    '**/pages/**/*.{js,jsx,ts,tsx,vue,svelte,astro}',
    '**/app/**/page.{js,jsx,ts,tsx}',
    '**/routes/**/*.{js,jsx,ts,tsx,vue,svelte}',
    '**/pages/**/*.{md,mdx}',
  ];
  const ignore = [
    ...DEFAULT_EXCLUDES,
    '**/*.test.*',
    '**/*.spec.*',
    '**/*.stories.*',
    '**/dist/**',
    '**/build/**',
  ];
  const files = fg.sync(globs, {
    cwd: root,
    absolute: true,
    onlyFiles: true,
    unique: true,
    ignore,
  });
  for (const file of files) {
    if (sourceRoots.some((dir) => file.startsWith(dir) || dir === root)) results.add(path.normalize(file));
  }
  if (results.size === 0) {
    const fallback = fg.sync(['**/src/index.{js,ts,jsx,tsx}', '**/src/main.{js,ts,jsx,tsx}'], {
      cwd: root,
      absolute: true,
      onlyFiles: true,
      ignore,
    });
    fallback.forEach((file) => results.add(path.normalize(file)));
  }
  return [...results].slice(0, 200);
}

export function detectRouteFromHtml(file: string, root: string): string {
  const relative = normalizeSlashes(path.relative(root, file));
  const withoutExt = relative.replace(/\.html?$/i, '');
  if (withoutExt === 'index' || withoutExt.endsWith('/index')) {
    const dir = withoutExt.replace(/\/?index$/, '');
    return `/${dir}`.replace(/\/+/g, '/');
  }
  return `/${withoutExt}`.replace(/\/+/g, '/');
}
