import ts from 'typescript';
import type { Finding, FindingCategory } from '../types.js';
import { createFinding } from './finding-utils.js';
import { toPosix } from '../util/fs.js';

function isAbrupt(statement: ts.Statement): boolean {
  return (
    ts.isReturnStatement(statement) ||
    ts.isThrowStatement(statement) ||
    ts.isBreakStatement(statement) ||
    ts.isContinueStatement(statement)
  );
}

function isDeclarationStatement(statement: ts.Statement): boolean {
  return (
    ts.isFunctionDeclaration(statement) ||
    ts.isClassDeclaration(statement) ||
    ts.isInterfaceDeclaration(statement) ||
    ts.isTypeAliasDeclaration(statement) ||
    ts.isEnumDeclaration(statement) ||
    ts.isVariableStatement(statement) ||
    ts.isModuleDeclaration(statement)
  );
}

function parentName(node: ts.Node): string | undefined {
  let current: ts.Node | undefined = node.parent;
  while (current) {
    if (
      ts.isFunctionDeclaration(current) ||
      ts.isMethodDeclaration(current) ||
      ts.isConstructorDeclaration(current) ||
      ts.isGetAccessorDeclaration(current) ||
      ts.isSetAccessorDeclaration(current) ||
      ts.isClassDeclaration(current)
    ) {
      if (current.name && ts.isIdentifier(current.name)) return current.name.text;
    }
    current = current.parent;
  }
  return undefined;
}

function lineColumn(sourceFile: ts.SourceFile, node: ts.Node): { line: number; column: number; endLine: number; endColumn: number } {
  const start = sourceFile.getLineAndCharacterOfPosition(node.getStart(sourceFile));
  const end = sourceFile.getLineAndCharacterOfPosition(Math.max(node.getStart(sourceFile), node.getEnd() - 1));
  return {
    line: start.line + 1,
    column: start.character + 1,
    endLine: end.line + 1,
    endColumn: end.character + 2,
  };
}

function makeUnreachableFinding(
  root: string,
  file: string,
  sourceFile: ts.SourceFile,
  node: ts.Node,
  title: string,
  description: string,
  category: FindingCategory = 'unreachable-code',
): Finding {
  const position = lineColumn(sourceFile, node);
  const sourceBytes = Math.max(0, node.getEnd() - node.getStart(sourceFile));
  return createFinding({
    root,
    category,
    status: 'confirmed-unused',
    confidence: 'high',
    title,
    description,
    file,
    line: position.line,
    column: position.column,
    endLine: position.endLine,
    endColumn: position.endColumn,
    symbolKind: 'unknown',
    ...(parentName(node) ? { parent: parentName(node) } : {}),
    size: {
      sourceBytes,
      estimatedRemovableBytes: sourceBytes,
      basis: `Unreachable source span (${sourceBytes} bytes).`,
    },
    evidence: [
      {
        kind: 'parser',
        description: 'TypeScript control-flow structure proves this statement cannot execute.',
        file: toPosix(file),
        line: position.line,
      },
    ],
    tags: ['static-proof'],
    fingerprintSuffix: `${position.line}:${position.column}`,
  });
}

/** Detects statically provable unreachable statements. */
export function findUnreachableCode(
  root: string,
  file: string,
  sourceFile: ts.SourceFile,
  maxFindings = 200,
): Finding[] {
  const findings: Finding[] = [];
  const seen = new Set<string>();

  const push = (node: ts.Node, title: string, description: string): boolean => {
    const key = `${node.getStart(sourceFile)}`;
    if (seen.has(key) || findings.length >= maxFindings) return findings.length >= maxFindings;
    seen.add(key);
    findings.push(makeUnreachableFinding(root, file, sourceFile, node, title, description));
    return findings.length >= maxFindings;
  };

  const visitStatements = (statements: readonly ts.Statement[]): void => {
    let abrupt: ts.Statement | undefined;
    for (const statement of statements) {
      if (abrupt) {
        if (!isDeclarationStatement(statement)) {
          if (push(statement, 'Unreachable code', `This statement follows a ${abrupt.getText(sourceFile).split(/\s+/)[0] ?? 'terminating'} statement and cannot execute.`)) {
            return;
          }
        }
      }
      if (isAbrupt(statement)) abrupt = statement;
    }
  };

  const visit = (node: ts.Node): void => {
    if (findings.length >= maxFindings) return;
    if (ts.isBlock(node) || ts.isModuleBlock(node)) {
      visitStatements(node.statements);
    }
    if (ts.isIfStatement(node)) {
      const condition = node.expression;
      const falseLiteral =
        condition.kind === ts.SyntaxKind.FalseKeyword ||
        (ts.isNumericLiteral(condition) && Number(condition.text) === 0) ||
        (ts.isStringLiteral(condition) && condition.text === '') ||
        condition.kind === ts.SyntaxKind.NullKeyword;
      const trueLiteral = condition.kind === ts.SyntaxKind.TrueKeyword;
      if (falseLiteral && !ts.isIfStatement(node.thenStatement) && !ts.isBlock(node.thenStatement)) {
        push(
          node.thenStatement,
          'Unreachable branch',
          'The condition is a false literal, so this branch can never execute.',
        );
      } else if (falseLiteral) {
        push(node.thenStatement, 'Unreachable branch', 'The condition is a false literal, so this branch can never execute.');
      } else if (trueLiteral && node.elseStatement) {
        push(node.elseStatement, 'Unreachable else branch', 'The condition is a true literal, so the else branch can never execute.');
      }
    }
    if (
      (ts.isWhileStatement(node) || ts.isForStatement(node)) &&
      node.statement &&
      ((ts.isWhileStatement(node) &&
        (node.expression.kind === ts.SyntaxKind.FalseKeyword ||
          (ts.isNumericLiteral(node.expression) && Number(node.expression.text) === 0))) ||
        (ts.isForStatement(node) &&
          node.condition &&
          (node.condition.kind === ts.SyntaxKind.FalseKeyword ||
            (ts.isNumericLiteral(node.condition) && Number(node.condition.text) === 0))))
    ) {
      push(node.statement, 'Unreachable loop body', 'The loop condition is a false literal, so the body can never execute.');
    }
    ts.forEachChild(node, visit);
  };

  visit(sourceFile);
  return findings;
}
