import { readFileSync } from 'node:fs';
import type { CodeSnippet } from '../types.js';

const lineCache = new Map<string, string[]>();

export function readSourceLines(file: string): string[] | undefined {
  const cached = lineCache.get(file);
  if (cached) return cached;
  try {
    const content = readFileSync(file, 'utf8');
    const lines = content.split(/\r\n|\r|\n/);
    lineCache.set(file, lines);
    if (lineCache.size > 500) {
      const first = lineCache.keys().next().value;
      if (first) lineCache.delete(first);
    }
    return lines;
  } catch {
    return undefined;
  }
}

export function clearSourceLineCache(): void {
  lineCache.clear();
}

export function buildSnippet(
  file: string,
  line: number,
  options: { context?: number; maxLineLength?: number; ruleText?: string } = {},
): CodeSnippet | undefined {
  const lines = readSourceLines(file);
  if (!lines || line < 1) return undefined;
  const context = Math.max(0, options.context ?? 2);
  const maxLineLength = options.maxLineLength ?? 500;
  const start = Math.max(1, line - context);
  const end = Math.min(lines.length, line + context);
  const snippetLines: Array<{ line: number; text: string }> = [];
  for (let current = start; current <= end; current += 1) {
    const raw = lines[current - 1] ?? '';
    snippetLines.push({
      line: current,
      text: raw.length > maxLineLength ? `${raw.slice(0, maxLineLength)}…` : raw,
    });
  }
  const before = Math.max(0, line - 1);
  const after = Math.max(0, lines.length - line);
  return {
    startLine: start,
    highlightLine: line,
    lines: snippetLines,
    ...(before + after > context * 2 ? { truncated: true } : {}),
    ...(options.ruleText ? { ruleText: options.ruleText } : {}),
  };
}

export function getSourceText(file: string): string | undefined {
  try {
    return readFileSync(file, 'utf8');
  } catch {
    return undefined;
  }
}
