import type { BrowserCollectorSnapshot } from './browser-collector.js';

export const RUNTIME_SESSION_SCHEMA = 1 as const;

export interface RuntimeCoverageFunction {
  url: string;
  functionName: string;
  startOffset: number;
  endOffset: number;
  startLine: number;
  startColumn: number;
  endLine: number;
  endColumn: number;
  bytes: number;
  count: number;
}

export interface RuntimeScriptCoverage {
  url: string;
  totalFunctions: number;
  executedFunctions: number;
  totalFunctionBytes: number;
  executedFunctionBytes: number;
}

export interface RuntimeCoverage {
  available: boolean;
  browser: string;
  functions: RuntimeCoverageFunction[];
  scripts: RuntimeScriptCoverage[];
  truncated: boolean;
  note?: string;
}

export interface RuntimeRouteVisit {
  route: string;
  name: string;
  path: string;
  url: string;
  navigation: 'initial' | 'goto' | 'link' | 'interactive';
  startedAt: string;
  finishedAt: string;
  durationMs: number;
  snapshot: BrowserCollectorSnapshot;
  coverage?: RuntimeCoverage;
  actions: string[];
  warnings: string[];
}

export interface RuntimeSession {
  schemaVersion: typeof RUNTIME_SESSION_SCHEMA;
  id: string;
  startedAt: string;
  finishedAt: string;
  baseUrl: string;
  browser: string;
  headless: boolean;
  interactive: boolean;
  navigationMode: 'auto' | 'goto';
  viewport: { width: number; height: number };
  userAgent?: string;
  visits: RuntimeRouteVisit[];
  coverageSession?: RuntimeCoverage;
  warnings: string[];
}

export interface MergedRouteRuntime {
  route: string;
  names: Set<string>;
  paths: Set<string>;
  sessions: number;
  scripts: Set<string>;
  resources: Array<{ url: string; type: 'js' | 'css' | 'other'; bytes: number }>;
  selectors: Map<string, {
    selector: string;
    sheets: Set<string>;
    matchedElements: number;
    stateOnly: boolean;
    media: Set<string>;
    mediaActive: boolean;
    ruleText?: string;
  }>;
  domClasses: Set<string>;
  domIds: Set<string>;
  domTags: Set<string>;
  stylesheets: Set<string>;
  interactions: number;
  dynamicCss: string[];
  coverage: {
    available: boolean;
    functions: RuntimeCoverageFunction[];
    scripts: RuntimeScriptCoverage[];
  };
  warnings: Set<string>;
}

export interface MergedRuntime {
  sessions: RuntimeSession[];
  routes: Map<string, MergedRouteRuntime>;
  sessionCoverage: {
    available: boolean;
    functions: RuntimeCoverageFunction[];
    scripts: RuntimeScriptCoverage[];
  };
  warnings: string[];
}
