import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';

export function toPosix(value: string): string {
  return value.replaceAll('\\', '/');
}

export function relativePosix(root: string, file: string): string {
  const relative = path.relative(root, file);
  return toPosix(relative === '' ? '.' : relative);
}

export function resolveFrom(root: string, value: string): string {
  return path.isAbsolute(value) ? path.normalize(value) : path.resolve(root, value);
}

export function isPathInside(parent: string, child: string): boolean {
  const relative = path.relative(parent, child);
  return relative !== '' && !relative.startsWith('..') && !path.isAbsolute(relative);
}

export function hashString(value: string, length = 16): string {
  return createHash('sha256').update(value).digest('hex').slice(0, length);
}

export function fileHash(file: string): string {
  return createHash('sha256').update(readFileSync(file)).digest('hex');
}

export function ensureDir(dir: string): string {
  mkdirSync(dir, { recursive: true });
  return dir;
}

export function readText(file: string): string {
  return readFileSync(file, 'utf8');
}

export function readJsonFile<T>(file: string): T {
  return JSON.parse(readText(file)) as T;
}

export function writeJsonFile(file: string, value: unknown): void {
  ensureDir(path.dirname(file));
  writeFileSync(file, `${JSON.stringify(value, null, 2)}\n`, 'utf8');
}

export function writeTextFile(file: string, value: string): void {
  ensureDir(path.dirname(file));
  writeFileSync(file, value, 'utf8');
}

export function safeReadJson<T>(file: string): T | undefined {
  if (!existsSync(file)) return undefined;
  try {
    return readJsonFile<T>(file);
  } catch {
    return undefined;
  }
}

export function parseJsonSafe<T>(value: string): T | undefined {
  try {
    return JSON.parse(value) as T;
  } catch {
    return undefined;
  }
}

export function formatBytes(bytes: number): string {
  if (!Number.isFinite(bytes) || bytes < 0) return '0 B';
  if (bytes < 1024) return `${bytes} B`;
  const units = ['KB', 'MB', 'GB', 'TB'];
  let value = bytes / 1024;
  let unit = 0;
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024;
    unit += 1;
  }
  return `${value.toFixed(value >= 10 ? 1 : 2)} ${units[unit]}`;
}

export function formatPercent(value: number): string {
  if (!Number.isFinite(value)) return '0%';
  const rounded = Math.abs(value) >= 10 ? value.toFixed(1) : value.toFixed(2);
  return `${rounded}%`;
}

export function bounded(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value));
}

export function uniq<T>(values: Iterable<T>): T[] {
  return [...new Set(values)];
}

export function uniqBy<T, K>(values: Iterable<T>, key: (value: T) => K): T[] {
  const seen = new Set<K>();
  const result: T[] = [];
  for (const value of values) {
    const id = key(value);
    if (!seen.has(id)) {
      seen.add(id);
      result.push(value);
    }
  }
  return result;
}

export function truncate(value: string, max: number): string {
  if (value.length <= max) return value;
  return `${value.slice(0, Math.max(0, max - 1))}…`;
}

export function abortError(signal?: AbortSignal): Error | undefined {
  if (!signal?.aborted) return undefined;
  const reason: unknown = signal.reason;
  if (reason instanceof Error) return reason;
  return new Error(typeof reason === 'string' ? reason : 'Operation aborted');
}

export function throwIfAborted(signal?: AbortSignal): void {
  const error = abortError(signal);
  if (error) throw error;
}

export function splitComma(value: string): string[] {
  return value
    .split(',')
    .map((part) => part.trim())
    .filter(Boolean);
}

export function normalizeSlashes(value: string): string {
  return value.replaceAll('\\', '/').replace(/\/+/g, '/');
}
