import path from 'node:path';
import ts from 'typescript';
import { readFileSync, existsSync } from 'node:fs';

export interface CompilerConfig {
  options: ts.CompilerOptions;
  warnings: string[];
}

export function loadCompilerOptions(tsconfig: string | undefined): CompilerConfig {
  const warnings: string[] = [];
  let options: ts.CompilerOptions = {};

  if (tsconfig && existsSync(tsconfig)) {
    const read = ts.readConfigFile(tsconfig, (file) => ts.sys.readFile(file));
    if (read.error) {
      warnings.push(`tsconfig: ${ts.flattenDiagnosticMessageText(read.error.messageText, ' ')}`);
    } else {
      const parsed = ts.parseJsonConfigFileContent(
        read.config,
        ts.sys,
        path.dirname(tsconfig),
        {},
        tsconfig,
      );
      options = parsed.options;
      for (const diagnostic of parsed.errors.slice(0, 5)) {
        warnings.push(`tsconfig: ${ts.flattenDiagnosticMessageText(diagnostic.messageText, ' ')}`);
      }
    }
  } else if (tsconfig) {
    warnings.push(`tsconfig not found: ${tsconfig}`);
  }

  options = {
    ...options,
    allowJs: true,
    checkJs: false,
    noEmit: true,
    skipLibCheck: true,
    sourceMap: false,
    inlineSourceMap: false,
    declaration: false,
    declarationMap: false,
    composite: false,
    incremental: false,
    resolveJsonModule: true,
    allowSyntheticDefaultImports: true,
    esModuleInterop: true,
    allowArbitraryExtensions: true,
    allowImportingTsExtensions: true,
    moduleDetection: ts.ModuleDetectionKind.Force,
    jsx: options.jsx ?? ts.JsxEmit.Preserve,
    target: options.target ?? ts.ScriptTarget.ES2022,
    module: options.module ?? ts.ModuleKind.ESNext,
    moduleResolution: options.moduleResolution ?? ts.ModuleResolutionKind.Bundler,
    newLine: ts.NewLineKind.LineFeed,
  };

  return { options, warnings };
}

export function readSourceText(file: string): string | undefined {
  try {
    return readFileSync(file, 'utf8');
  } catch {
    return undefined;
  }
}
