/**
 * Self-contained browser collector. This function is serialized with
 * Function.prototype.toString and injected before application scripts, so it
 * must not reference imports or module-scope values.
 */

export interface RuntimeSelectorUsage {
  selector: string;
  sheets: string[];
  matchedElements: number;
  stateOnly: boolean;
  media: string[];
  mediaActive: boolean;
  ruleText?: string;
}

export interface RuntimeDomSnapshot {
  classes: string[];
  ids: string[];
  tags: string[];
}

export interface RuntimeResource {
  url: string;
  type: 'js' | 'css' | 'other';
  bytes: number;
  initiatorType?: string;
  startTime: number;
  duration?: number;
}

export interface RuntimeInteraction {
  type: string;
  tag: string;
}

export interface RuntimeDynamicCss {
  text: string;
  route: string;
}

export interface BrowserRouteSnapshot {
  route: string;
  selectors: RuntimeSelectorUsage[];
  dom: RuntimeDomSnapshot;
  stylesheets: string[];
  scripts: string[];
  resources: RuntimeResource[];
  interactions: RuntimeInteraction[];
  dynamicCss: RuntimeDynamicCss[];
  capturedAt: string;
}

export interface BrowserCollectorSnapshot {
  href: string;
  timeOrigin: number;
  routes: BrowserRouteSnapshot[];
  warnings: string[];
}

interface CollectorApi {
  take(): BrowserCollectorSnapshot;
  setRoute(name?: string): void;
}

export function installBrowserCollector(options?: {
  snapshotIntervalMs?: number;
  collectCss?: boolean;
  collectNetwork?: boolean;
}): void {
  const KEY = '__codeUsageMapRuntime';
  const globalRecord = window as unknown as Record<string, unknown>;
  if (globalRecord[KEY]) return;

  const interval = Math.max(250, options?.snapshotIntervalMs ?? 600);
  const collectCss = options?.collectCss !== false;
  const collectNetwork = options?.collectNetwork !== false;
  const MAX_RULES = 30_000;
  const MAX_DYNAMIC_CSS = 200;
  const MAX_INTERACTIONS = 1_000;

  interface SelectorEntry {
    selector: string;
    sheets: Set<string>;
    matchedElements: number;
    stateOnly: boolean;
    media: Set<string>;
    mediaActive: boolean;
    ruleText?: string;
  }

  interface RouteAccumulator {
    selectors: Map<string, SelectorEntry>;
    classes: Set<string>;
    ids: Set<string>;
    tags: Set<string>;
    stylesheets: Set<string>;
    scripts: Set<string>;
    resources: Map<string, RuntimeResource>;
    interactions: RuntimeInteraction[];
    dynamicCss: RuntimeDynamicCss[];
    warnings: Set<string>;
  }

  const createRoute = (): RouteAccumulator => ({
    selectors: new Map(),
    classes: new Set(),
    ids: new Set(),
    tags: new Set(),
    stylesheets: new Set(),
    scripts: new Set(),
    resources: new Map(),
    interactions: [],
    dynamicCss: [],
    warnings: new Set(),
  });

  const state = {
    currentRoute: routeKey(),
    overrideRoute: undefined as string | undefined,
    routes: new Map<string, RouteAccumulator>(),
    seenResources: new Set<string>(),
    seenInlineCss: new Set<string>(),
    warnings: new Set<string>(),
    sweeping: false,
    ruleTruncated: false,
    sheetWarning: false,
  };

  function routeKey(): string {
    const hash = window.location.hash;
    if (/^#\//.test(hash)) return hash.slice(1) || '/';
    return window.location.pathname || '/';
  }

  function currentRoute(): string {
    return state.overrideRoute ?? state.currentRoute;
  }

  function ensureRoute(route = currentRoute()): RouteAccumulator {
    const existing = state.routes.get(route);
    if (existing) return existing;
    const created = createRoute();
    state.routes.set(route, created);
    return created;
  }

  function splitSelectors(value: string): string[] {
    const result: string[] = [];
    let depth = 0;
    let quote: string | undefined;
    let start = 0;
    for (let index = 0; index < value.length; index += 1) {
      const char = value[index];
      if (quote) {
        if (char === '\\') index += 1;
        else if (char === quote) quote = undefined;
        continue;
      }
      if (char === '"' || char === "'") {
        quote = char;
        continue;
      }
      if (char === '(' || char === '[') depth += 1;
      else if (char === ')' || char === ']') depth = Math.max(0, depth - 1);
      else if (char === ',' && depth === 0) {
        const part = value.slice(start, index).trim();
        if (part) result.push(part);
        start = index + 1;
      }
    }
    const tail = value.slice(start).trim();
    if (tail) result.push(tail);
    return result.length > 0 ? result : [value.trim()];
  }

  function selectorVariants(selector: string): string[] {
    const variants = new Set<string>([selector]);
    const withoutPseudoElements = selector.replace(/::[A-Za-z-]+(?:\([^)]*\))?/g, '');
    if (withoutPseudoElements.trim()) variants.add(withoutPseudoElements);
    const withoutState = withoutPseudoElements
      .replace(
        /:(?:hover|focus-within|focus-visible|focus|active|visited|target|checked|disabled|enabled|invalid|valid|placeholder-shown|autofill|open|popover-open|user-invalid|user-valid|fullscreen|modal|picture-in-picture|playing|paused|muted|seeking|buffering|stalled)(?![\w-])/g,
        '',
      )
      .replace(/:not\(\s*\)/g, '');
    if (withoutState.trim()) variants.add(withoutState);
    return [...variants].filter((variant) => {
      if (!variant.trim()) return false;
      try {
        document.createDocumentFragment().querySelector(variant);
        return true;
      } catch {
        return false;
      }
    });
  }

  function collectRoots(): Array<Document | ShadowRoot> {
    const roots: Array<Document | ShadowRoot> = [document];
    const visit = (root: Document | ShadowRoot): void => {
      const elements = Array.from(root.querySelectorAll('*'));
      for (const element of elements) {
        const shadow = (element as HTMLElement).shadowRoot;
        if (shadow) {
          roots.push(shadow);
          visit(shadow);
        }
      }
    };
    visit(document);
    return roots;
  }

  function countMatches(selector: string, roots: Array<Document | ShadowRoot>): number {
    let count = 0;
    for (const root of roots) {
      try {
        count += root.querySelectorAll(selector).length;
      } catch {
        continue;
      }
      if (count > 9_999) return 9_999;
    }
    return count;
  }

  function collectStyleSheets(roots: Array<Document | ShadowRoot>): Array<{ sheet: CSSStyleSheet; key: string }> {
    const result: Array<{ sheet: CSSStyleSheet; key: string }> = [];
    const seen = new Set<CSSStyleSheet>();
    let inlineIndex = 0;

    const add = (sheet: CSSStyleSheet | null | undefined, keyHint?: string): void => {
      if (!sheet || seen.has(sheet)) return;
      seen.add(sheet);
      const key = sheet.href ?? keyHint ?? `inline:${inlineIndex}`;
      inlineIndex += 1;
      result.push({ sheet, key });
    };

    for (const sheet of Array.from(document.styleSheets)) add(sheet);
    const adopted = (document as Document & { adoptedStyleSheets?: CSSStyleSheet[] }).adoptedStyleSheets ?? [];
    for (const sheet of Array.from(adopted)) add(sheet, 'adopted:document');

    for (const root of roots) {
      if (root === document) continue;
      const shadowRoot = root as ShadowRoot;
      const shadowAdopted = (shadowRoot as ShadowRoot & { adoptedStyleSheets?: CSSStyleSheet[] }).adoptedStyleSheets ?? [];
      for (const sheet of Array.from(shadowAdopted)) add(sheet, 'adopted:shadow');
    }

    for (const root of roots) {
      for (const element of Array.from(root.querySelectorAll('style,link[rel="stylesheet"]'))) {
        if (element instanceof HTMLStyleElement) add(element.sheet, `style:${element.textContent?.slice(0, 20) ?? ''}`);
        else if (element instanceof HTMLLinkElement) add(element.sheet, element.href);
      }
    }
    return result;
  }

  interface StyleRuleLike {
    type: number;
    cssRules?: ArrayLike<StyleRuleLike>;
    selectorText?: string;
    style?: { cssText?: string };
    media?: { mediaText?: string };
    conditionText?: string;
    styleSheet?: CSSStyleSheet | null;
    name?: string;
  }

  function mediaMatches(text: string): boolean {
    try {
      return window.matchMedia(text).matches;
    } catch {
      return true;
    }
  }

  function addSelector(
    route: RouteAccumulator,
    sheetKey: string,
    selector: string,
    matched: number,
    stateOnly: boolean,
    media: string[],
    mediaActive: boolean,
    ruleText: string,
  ): void {
    const normalized = selector.replace(/\s+/g, ' ').trim();
    if (!normalized) return;
    const key = normalized;
    const existing = route.selectors.get(key);
    if (existing) {
      existing.sheets.add(sheetKey);
      existing.matchedElements = Math.max(existing.matchedElements, matched);
      existing.stateOnly = existing.stateOnly && stateOnly;
      for (const item of media) existing.media.add(item);
      existing.mediaActive = existing.mediaActive || mediaActive;
      if (!existing.ruleText && ruleText) existing.ruleText = ruleText;
      return;
    }
    route.selectors.set(key, {
      selector: normalized,
      sheets: new Set([sheetKey]),
      matchedElements: matched,
      stateOnly,
      media: new Set(media),
      mediaActive,
      ...(ruleText ? { ruleText } : {}),
    });
  }

  function walkRules(
    rule: StyleRuleLike,
    sheetKey: string,
    roots: Array<Document | ShadowRoot>,
    route: RouteAccumulator,
    media: string[],
    ruleCounter: { count: number },
  ): void {
    if (ruleCounter.count > MAX_RULES) {
      if (!state.ruleTruncated) {
        state.ruleTruncated = true;
        state.warnings.add(`CSS rule sweep stopped after ${MAX_RULES} rules.`);
      }
      return;
    }
    ruleCounter.count += 1;

    if (rule.styleSheet) {
      try {
        visitStyleSheet(rule.styleSheet, rule.styleSheet.href ?? sheetKey, roots, route, media, ruleCounter);
      } catch {
        // Cross-origin or inaccessible imported sheet.
      }
      return;
    }

    const mediaList = rule.media?.mediaText;
    const nextMedia = mediaList ? [...media, mediaList] : media;
    const isStyleRule = typeof rule.selectorText === 'string' && rule.selectorText.trim() !== '';
    if (isStyleRule && rule.selectorText) {
      const ruleText = `${rule.selectorText}{${rule.style?.cssText ?? ''}}`;
      const active = nextMedia.every((item) => mediaMatches(item));
      for (const selector of splitSelectors(rule.selectorText)) {
        let matched = 0;
        let stateOnly = false;
        const variants = selectorVariants(selector);
        for (let index = 0; index < variants.length; index += 1) {
          const variant = variants[index];
          if (!variant) continue;
          const count = countMatches(variant, roots);
          if (count > 0) {
            matched = count;
            stateOnly = index > 0 || !active;
            break;
          }
        }
        if (matched > 0) {
          addSelector(route, sheetKey, selector, matched, stateOnly, nextMedia, active, ruleText.slice(0, 1200));
        }
      }
    }

    if (rule.cssRules) {
      for (const child of Array.from(rule.cssRules)) {
        walkRules(child, sheetKey, roots, route, nextMedia, ruleCounter);
      }
    }
  }

  function visitStyleSheet(
    sheet: CSSStyleSheet,
    key: string,
    roots: Array<Document | ShadowRoot>,
    route: RouteAccumulator,
    media: string[],
    ruleCounter: { count: number },
  ): void {
    let rules: CSSRuleList;
    try {
      rules = sheet.cssRules;
    } catch {
      if (!state.sheetWarning) {
        state.sheetWarning = true;
        state.warnings.add('Some cross-origin stylesheets could not be inspected; CSS coverage is partial.');
      }
      return;
    }
    for (const rule of Array.from(rules)) {
      walkRules(rule as unknown as StyleRuleLike, key, roots, route, media, ruleCounter);
    }
  }

  function recordResource(entry: PerformanceResourceTiming): void {
    if (!collectNetwork) return;
    const type: RuntimeResource['type'] = entry.initiatorType === 'script' || /\.(?:mjs?|cjs)(?:[?#]|$)/i.test(entry.name)
      ? 'js'
      : entry.initiatorType === 'link' || entry.initiatorType === 'css' || /\.css(?:[?#]|$)/i.test(entry.name)
        ? 'css'
        : 'other';
    if (type === 'other') return;
    const key = `${entry.name}|${Math.round(entry.startTime)}`;
    if (state.seenResources.has(key)) return;
    state.seenResources.add(key);
    const route = ensureRoute();
    route.resources.set(key, {
      url: entry.name,
      type,
      bytes: entry.encodedBodySize || entry.transferSize || 0,
      ...(entry.initiatorType ? { initiatorType: entry.initiatorType } : {}),
      startTime: Math.round(entry.startTime),
      ...(entry.duration ? { duration: Math.round(entry.duration) } : {}),
    });
  }

  function scanResourceEntries(): void {
    if (!collectNetwork) return;
    try {
      for (const entry of performance.getEntriesByType('resource')) {
        recordResource(entry as PerformanceResourceTiming);
      }
    } catch {
      // Resource Timing can be unavailable in restrictive contexts.
    }
  }

  function recordDynamicCss(text: string): void {
    if (!collectCss) return;
    const route = ensureRoute();
    if (route.dynamicCss.length >= MAX_DYNAMIC_CSS) return;
    const cleaned = text.replace(/\s+/g, ' ').trim();
    if (!cleaned) return;
    route.dynamicCss.push({ text: cleaned.slice(0, 3000), route: currentRoute() });
  }

  function sweep(): void {
    if (state.sweeping) return;
    state.sweeping = true;
    try {
      const route = ensureRoute();
      if (collectCss) {
        const roots = collectRoots();
        for (const root of roots) {
          for (const element of Array.from(root.querySelectorAll('*'))) {
            for (const token of Array.from(element.classList)) route.classes.add(token);
            if (element.id) route.ids.add(element.id);
            route.tags.add(element.tagName.toLowerCase());
          }
        }

        const sheets = collectStyleSheets(roots);
        for (const { sheet, key } of sheets) {
          route.stylesheets.add(key);
          const ruleCounter = { count: 0 };
          try {
            visitStyleSheet(sheet, key, roots, route, [], ruleCounter);
          } catch {
            if (!state.sheetWarning) {
              state.sheetWarning = true;
              state.warnings.add('A stylesheet could not be inspected completely.');
            }
          }
        }
        for (const rootItem of roots) {
          for (const style of Array.from(rootItem.querySelectorAll('style'))) {
            const text = (style.textContent ?? '').trim();
            if (!text) continue;
            const styleKey = text.slice(0, 160);
            if (state.seenInlineCss.has(styleKey)) continue;
            state.seenInlineCss.add(styleKey);
            recordDynamicCss(text);
          }
        }
      }

      for (const script of Array.from(document.querySelectorAll('script[src]'))) {
        const src = script.getAttribute('src');
        if (src) {
          try {
            route.scripts.add(new URL(src, document.baseURI).href);
          } catch {
            route.scripts.add(src);
          }
        }
      }
      for (const link of Array.from(document.querySelectorAll('link[href]'))) {
        const rel = link.getAttribute('rel') ?? '';
        if (rel.includes('stylesheet')) {
          const href = link.getAttribute('href');
          if (href) {
            try {
              route.stylesheets.add(new URL(href, document.baseURI).href);
            } catch {
              route.stylesheets.add(href);
            }
          }
        }
      }

      scanResourceEntries();
    } catch (error) {
      state.warnings.add(`Runtime snapshot failed: ${error instanceof Error ? error.message : String(error)}`);
    } finally {
      state.sweeping = false;
    }
  }

  let sweepTimer: number | undefined;
  function scheduleSweep(delay = 180): void {
    if (sweepTimer !== undefined) window.clearTimeout(sweepTimer);
    sweepTimer = window.setTimeout(() => {
      sweepTimer = undefined;
      sweep();
    }, delay);
  }

  function afterRouteChange(): void {
    state.currentRoute = routeKey();
    scheduleSweep(120);
    window.setTimeout(() => scheduleSweep(350), 350);
  }

  const originalPushState = history.pushState.bind(history);
  const originalReplaceState = history.replaceState.bind(history);
  const wrappedPushState = function (
    data: unknown,
    title: string,
    url?: string | URL | null,
  ): void {
    sweep();
    originalPushState(data, title, url);
    afterRouteChange();
  };
  const wrappedReplaceState = function (
    data: unknown,
    title: string,
    url?: string | URL | null,
  ): void {
    sweep();
    originalReplaceState(data, title, url);
    afterRouteChange();
  };
  history.pushState = wrappedPushState as typeof history.pushState;
  history.replaceState = wrappedReplaceState as typeof history.replaceState;

  window.addEventListener('popstate', () => {
    sweep();
    afterRouteChange();
  });
  window.addEventListener('hashchange', () => {
    sweep();
    afterRouteChange();
  });

  const interactionTypes = new Set(['click', 'input', 'change', 'submit', 'keydown']);
  const recordInteraction = (event: Event): void => {
    if (!interactionTypes.has(event.type)) return;
    const target = event.target;
    const tag = target instanceof Element ? target.tagName.toLowerCase() : 'unknown';
    const route = ensureRoute();
    if (route.interactions.length < MAX_INTERACTIONS) route.interactions.push({ type: event.type, tag });
  };
  for (const type of interactionTypes) {
    document.addEventListener(type, recordInteraction, { capture: true, passive: true });
  }

  if (collectNetwork) {
    try {
      const observer = new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) {
          if (entry.entryType === 'resource') recordResource(entry as PerformanceResourceTiming);
        }
      });
      observer.observe({ type: 'resource', buffered: true });
    } catch {
      // Fallback to performance.getEntriesByType in sweep().
    }
  }

  try {
    const mutationObserver = new MutationObserver((mutations) => {
      const relevant = mutations.some(
        (mutation) =>
          mutation.type === 'childList' ||
          (mutation.type === 'attributes' &&
            ['class', 'id', 'style'].includes(mutation.attributeName ?? '')),
      );
      if (relevant) scheduleSweep();
    });
    mutationObserver.observe(document.documentElement, {
      subtree: true,
      childList: true,
      attributes: true,
      attributeFilter: ['class', 'id', 'style'],
    });
  } catch {
    // Interval sweeps remain active.
  }

  // Capture runtime-injected CSS, including detached constructable sheets.
  if (collectCss) try {
    const originalInsertRule = CSSStyleSheet.prototype.insertRule;
    CSSStyleSheet.prototype.insertRule = function (this: CSSStyleSheet, rule: string, index?: number): number {
      const result = originalInsertRule.call(this, rule, index);
      recordDynamicCss(rule);
      return result;
    };
  } catch {
    // Older browsers may expose a non-writable prototype.
  }
  if (collectCss) try {
    const originalReplaceSync = CSSStyleSheet.prototype.replaceSync;
    if (typeof originalReplaceSync === 'function') {
      CSSStyleSheet.prototype.replaceSync = function (this: CSSStyleSheet, text: string): void {
        originalReplaceSync.call(this, text);
        recordDynamicCss(text);
      };
    }
  } catch {
    // Ignore read-only implementations.
  }

  window.addEventListener('load', () => scheduleSweep(0));
  scheduleSweep(0);
  const intervalId = window.setInterval(() => sweep(), interval);
  void intervalId;

  const api: CollectorApi = {
    take(): BrowserCollectorSnapshot {
      sweep();
      const routes: BrowserRouteSnapshot[] = [];
      for (const [routeName, route] of state.routes) {
        const hasData =
          route.selectors.size > 0 ||
          route.classes.size > 0 ||
          route.ids.size > 0 ||
          route.resources.size > 0 ||
          route.interactions.length > 0 ||
          route.dynamicCss.length > 0 ||
          route.stylesheets.size > 0;
        if (!hasData) continue;
        routes.push({
          route: routeName,
          selectors: [...route.selectors.values()]
            .map((entry) => ({
              selector: entry.selector,
              sheets: [...entry.sheets].sort(),
              matchedElements: entry.matchedElements,
              stateOnly: entry.stateOnly,
              media: [...entry.media],
              mediaActive: entry.mediaActive,
              ...(entry.ruleText ? { ruleText: entry.ruleText } : {}),
            }))
            .sort((a, b) => a.selector.localeCompare(b.selector)),
          dom: {
            classes: [...route.classes].sort(),
            ids: [...route.ids].sort(),
            tags: [...route.tags].sort(),
          },
          stylesheets: [...route.stylesheets].sort(),
          scripts: [...route.scripts].sort(),
          resources: [...route.resources.values()].sort((a, b) => a.startTime - b.startTime),
          interactions: route.interactions.slice(0, MAX_INTERACTIONS),
          dynamicCss: route.dynamicCss.slice(0, MAX_DYNAMIC_CSS),
          capturedAt: new Date().toISOString(),
        });
        for (const warning of route.warnings) state.warnings.add(warning);
      }
      const snapshot: BrowserCollectorSnapshot = {
        href: window.location.href,
        timeOrigin: performance.timeOrigin || Date.now(),
        routes,
        warnings: [...state.warnings],
      };
      state.routes.clear();
      return snapshot;
    },
    setRoute(name?: string): void {
      state.overrideRoute = name && name.trim() ? name.trim() : undefined;
      if (state.overrideRoute) scheduleSweep(0);
    },
  };

  globalRecord[KEY] = api;
}
