import pc from 'picocolors';
import type { LoggingConfig } from '../types.js';

export type LogLevel = LoggingConfig['level'];

const ORDER: Record<LogLevel, number> = {
  silent: 0,
  error: 1,
  warn: 2,
  info: 3,
  debug: 4,
};

export interface Logger {
  level: LogLevel;
  error(message: string): void;
  warn(message: string): void;
  info(message: string): void;
  debug(message: string): void;
  raw(message: string): void;
}

export function createLogger(level: LogLevel = 'info'): Logger {
  const logger: Logger = {
    level,
    error(message) {
      if (ORDER[logger.level] >= ORDER.error) process.stderr.write(`${pc.red('error')} ${message}\n`);
    },
    warn(message) {
      if (ORDER[logger.level] >= ORDER.warn) process.stderr.write(`${pc.yellow('warn')} ${message}\n`);
    },
    info(message) {
      if (ORDER[logger.level] >= ORDER.info) process.stderr.write(`${message}\n`);
    },
    debug(message) {
      if (ORDER[logger.level] >= ORDER.debug) process.stderr.write(`${pc.gray(message)}\n`);
    },
    raw(message) {
      process.stderr.write(`${message}\n`);
    },
  };
  return logger;
}

export function createTimer(): () => number {
  const start = process.hrtime.bigint();
  return () => Number(process.hrtime.bigint() - start) / 1_000_000;
}

export function formatDuration(ms: number): string {
  if (ms < 1000) return `${Math.round(ms)}ms`;
  if (ms < 60_000) return `${(ms / 1000).toFixed(2)}s`;
  return `${(ms / 60_000).toFixed(1)}min`;
}
