import type {
  AnalysisStatus,
  CodeSnippet,
  Confidence,
  Evidence,
  Finding,
  FindingCategory,
  FindingFix,
  FindingMapping,
  FindingRuntimeEvidence,
  FindingSize,
  Severity,
  SourceLocation,
  SymbolKind,
} from '../types.js';
import { fileType } from '../integrations/detect.js';
import { relativePosix, hashString } from '../util/fs.js';
import { buildSnippet } from '../util/source.js';

export interface FindingInput {
  root: string;
  category: FindingCategory;
  status: AnalysisStatus;
  confidence: Confidence;
  severity?: Severity;
  title: string;
  description: string;
  file: string;
  line: number;
  column: number;
  endLine?: number;
  endColumn?: number;
  symbol?: string;
  symbolKind: SymbolKind;
  parent?: string;
  size?: FindingSize;
  evidence?: Evidence[];
  snippet?: CodeSnippet;
  ruleText?: string;
  fix?: FindingFix;
  mapping?: FindingMapping;
  runtime?: FindingRuntimeEvidence;
  css?: Finding['css'];
  duplicate?: Finding['duplicate'];
  dependency?: Finding['dependency'];
  routeHints?: string[];
  tags?: string[];
  fingerprintSuffix?: string;
  idSuffix?: string;
}

export function defaultSeverity(
  category: FindingCategory,
  status: AnalysisStatus,
  confidence: Confidence,
  bytes = 0,
): Severity {
  if (category === 'css-specificity' || category === 'polyfill-included') return 'info';
  if (category === 'duplicate-code' || category === 'unused-css-declaration') return 'low';
  if (category === 'circular-dependency') return 'medium';
  if (category === 'duplicate-css-rule' || category === 'duplicate-css-selector') return 'low';
  if (category === 'unused-type-parameter' || category === 'unused-type-only-import') return 'low';
  if (status === 'confirmed-unused') {
    if (bytes >= 8_000) return 'high';
    return bytes > 0 ? 'medium' : 'low';
  }
  if (status === 'potentially-unused') {
    return confidence === 'high' && bytes >= 4_000 ? 'medium' : 'low';
  }
  return 'info';
}

export function fingerprintFor(
  category: FindingCategory,
  relativeFile: string,
  symbol: string | undefined,
  symbolKind: SymbolKind,
  suffix?: string,
): string {
  return [category, relativeFile, symbol ?? '', symbolKind, suffix ?? ''].join('|');
}

export function createFinding(input: FindingInput): Finding {
  const relativeFile = relativePosix(input.root, input.file);
  const fingerprint = fingerprintFor(
    input.category,
    relativeFile,
    input.symbol,
    input.symbolKind,
    input.fingerprintSuffix,
  );
  const id = `f_${hashString(`${fingerprint}|${input.line}|${input.column}|${input.idSuffix ?? ''}`, 12)}`;
  const snippet =
    input.snippet ??
    (input.symbolKind === 'css-selector' || input.symbolKind === 'css-rule'
      ? buildSnippet(input.file, input.line, { context: 3, ruleText: input.ruleText })
      : buildSnippet(input.file, input.line, { context: 2 }));
  const size = input.size ?? {};
  const severity =
    input.severity ??
    defaultSeverity(input.category, input.status, input.confidence, size.estimatedRemovableBytes ?? size.sourceBytes ?? 0);

  const location: SourceLocation = {
    file: input.file,
    relativeFile,
    line: input.line,
    column: input.column,
    ...(input.endLine !== undefined ? { endLine: input.endLine } : {}),
    ...(input.endColumn !== undefined ? { endColumn: input.endColumn } : {}),
    fileType: fileType(input.file),
  };

  return {
    id,
    fingerprint,
    category: input.category,
    status: input.status,
    confidence: input.confidence,
    severity,
    title: input.title,
    description: input.description,
    location,
    ...(input.symbol ? { symbol: input.symbol } : {}),
    symbolKind: input.symbolKind,
    ...(input.parent ? { parent: input.parent } : {}),
    ...(input.mapping ? { mapping: input.mapping } : {}),
    ...(input.runtime ? { runtime: input.runtime } : {}),
    ...(input.css ? { css: input.css } : {}),
    ...(input.duplicate ? { duplicate: input.duplicate } : {}),
    ...(input.dependency ? { dependency: input.dependency } : {}),
    size,
    evidence: input.evidence ?? [],
    ...(snippet ? { snippet } : {}),
    ...(input.fix ? { fix: input.fix } : {}),
    routeHints: input.routeHints ?? [],
    recommendationIds: [],
    tags: input.tags ?? [],
  };
}

export function uniqueFindingFingerprints(findings: Finding[]): Finding[] {
  const counts = new Map<string, number>();
  for (const finding of findings) {
    const count = counts.get(finding.fingerprint) ?? 0;
    counts.set(finding.fingerprint, count + 1);
    if (count > 0) {
      finding.fingerprint = `${finding.fingerprint}#${count + 1}`;
    }
  }
  return findings;
}
