import path from 'node:path';
import ts from 'typescript';
import type { SfcExtraction, SfcScriptLanguage } from './sfc.js';
import { extractSfc } from './sfc.js';
import { readSourceText } from './tsconfig.js';

export interface VirtualSource {
  fileName: string;
  originalFile: string;
  content: string;
  scriptKind: ts.ScriptKind;
  extraction: SfcExtraction;
}

export interface StaticProgram {
  program: ts.Program;
  checker: ts.TypeChecker;
  options: ts.CompilerOptions;
  virtualByFile: Map<string, VirtualSource>;
  originalByFile: Map<string, string>;
  warnings: string[];
}

function scriptKindFor(language: SfcScriptLanguage | 'ts' | 'tsx' | 'js' | 'jsx'): ts.ScriptKind {
  if (language === 'tsx') return ts.ScriptKind.TSX;
  if (language === 'jsx') return ts.ScriptKind.JSX;
  if (language === 'ts') return ts.ScriptKind.TS;
  return ts.ScriptKind.JS;
}

/** Builds a TypeScript program with in-memory TypeScript extracted from SFCs. */
export function createStaticProgram(
  scriptFiles: string[],
  options: ts.CompilerOptions,
  warnings: string[],
): StaticProgram {
  const virtualByFile = new Map<string, VirtualSource>();
  const originalByFile = new Map<string, string>();
  const rootNames: string[] = [];
  const virtualWarnings: string[] = [];

  for (const file of scriptFiles) {
    const extension = path.extname(file).toLowerCase();
    if (extension === '.vue' || extension === '.svelte' || extension === '.astro') {
      const content = readSourceText(file);
      if (content === undefined) {
        virtualWarnings.push(`Could not read ${file}.`);
        continue;
      }
      const extraction = extractSfc(file, content);
      if (extraction?.virtualPath && extraction.virtualContent !== undefined) {
        const virtualFile = path.normalize(extraction.virtualPath);
        const scriptKind = scriptKindFor(extraction.scriptKind);
        virtualByFile.set(virtualFile, {
          fileName: virtualFile,
          originalFile: path.normalize(file),
          content: extraction.virtualContent,
          scriptKind,
          extraction,
        });
        originalByFile.set(virtualFile, path.normalize(file));
        rootNames.push(virtualFile);
      }
      continue;
    }
    rootNames.push(path.normalize(file));
  }

  const host = ts.createCompilerHost(options);
  const originalGetSourceFile = host.getSourceFile.bind(host);
  const originalFileExists = host.fileExists.bind(host);
  const originalReadFile = host.readFile.bind(host);
  const originalRealpath = host.realpath?.bind(host);

  const lookupVirtual = (fileName: string): VirtualSource | undefined => {
    return virtualByFile.get(path.normalize(fileName));
  };

  host.getSourceFile = (fileName, languageVersion, onError, shouldCreateNewSourceFile) => {
    const virtual = lookupVirtual(fileName);
    if (virtual) {
      return ts.createSourceFile(
        fileName,
        virtual.content,
        languageVersion,
        true,
        virtual.scriptKind,
      );
    }
    return originalGetSourceFile(fileName, languageVersion, onError, shouldCreateNewSourceFile);
  };
  host.fileExists = (fileName) => lookupVirtual(fileName) !== undefined || originalFileExists(fileName);
  host.readFile = (fileName) => lookupVirtual(fileName)?.content ?? originalReadFile(fileName);
  if (originalRealpath) {
    host.realpath = (fileName) => (lookupVirtual(fileName) ? fileName : originalRealpath(fileName));
  }

  const program = ts.createProgram({
    rootNames,
    options,
    host,
  });
  const checker = program.getTypeChecker();

  const diagnostics = program.getSyntacticDiagnostics();
  const grouped = new Map<string, number>();
  const samples = new Map<string, string>();
  for (const diagnostic of diagnostics) {
    const file = diagnostic.file?.fileName ?? '<program>';
    grouped.set(file, (grouped.get(file) ?? 0) + 1);
    if (!samples.has(file)) {
      samples.set(file, ts.flattenDiagnosticMessageText(diagnostic.messageText, ' '));
    }
  }
  for (const [file, count] of [...grouped].slice(0, 10)) {
    const original = originalByFile.get(path.normalize(file)) ?? file;
    virtualWarnings.push(
      `Parse diagnostics in ${original}: ${count} issue${count === 1 ? '' : 's'} (${samples.get(file) ?? 'unknown'}).`,
    );
  }
  if (grouped.size > 10) {
    virtualWarnings.push(`Parse diagnostics found in ${grouped.size - 10} additional files.`);
  }

  warnings.push(...virtualWarnings);
  return {
    program,
    checker,
    options,
    virtualByFile,
    originalByFile,
    warnings: virtualWarnings,
  };
}
