import ts from 'typescript';
import type {
  AnalysisMode,
  AnalysisStatus,
  Confidence,
  Finding,
  FindingCategory,
  ResolvedCodeUsageMapConfig,
  SymbolKind,
  TypeOnlyDependencyImport,
} from '../types.js';
import type { ProjectDetection } from '../integrations/detect.js';
import type { SourceCollection } from './source-files.js';
import { isDeclarationFile, isTestOrStoryFile } from './source-files.js';
import { extractSfc, templateIdentifiers } from './sfc.js';
import { loadCompilerOptions } from './tsconfig.js';
import { createStaticProgram } from './program.js';
import { buildImportGraph } from './graph.js';
import type {
  StaticAnalysisResult,
  ImportRecord,
  DynamicPatternRecord,
  ModuleRecordInfo,
} from './types.js';
