import { hashString, toPosix } from '../util/fs.js';

interface RefCounts {
  value: number;
  type: number;
  write: number;
}

/**
 * Framework-invoked lifecycle methods are not statically referenced by
 * application code. They are deliberately excluded from unused-method
 * findings; runtime coverage still records whether they executed.
 */
const FRAMEWORK_METHOD_NAMES = new Set([
  'render',
  'componentDidMount',
  'componentDidUpdate',
  'componentWillUnmount',
  'componentWillMount',
  'componentWillReceiveProps',
  'shouldComponentUpdate',
  'getDerivedStateFromProps',
  'getSnapshotBeforeUpdate',
  'getInitialState',
  'ngOnInit',
  'ngOnDestroy',
  'ngOnChanges',
  'ngAfterViewInit',
  'ngAfterViewChecked',
  'ngAfterContentInit',
  'ngAfterContentChecked',
  'ngDoCheck',
  'setup',
  'beforeMount',
  'mounted',
  'beforeUpdate',
  'updated',
  'beforeUnmount',
  'unmounted',
  'created',
  'activated',
  'deactivated',
  'connectedCallback',
  'disconnectedCallback',
  'attributeChangedCallback',
  'adoptedCallback',
  'observedAttributes',
]);

interface DeclRecord {
  node: ts.Node;
  nameNode?: ts.Node;
  sourceFile: ts.SourceFile;
  file: string;
  relativeFile: string;
  symbol?: ts.Symbol;
  canonical?: ts.Symbol;
  name: string;
  category: FindingCategory;
  symbolKind: SymbolKind;
  exported: boolean;
  classExported: boolean;
  defaultExport: boolean;
  typeOnlyDeclaration: boolean;
  decorated: boolean;
  classDecorated: boolean;
  ambient: boolean;
  line: number;
  column: number;
  endLine: number;
  endColumn: number;
  spanBytes: number;
  parent?: string;
  parentRecord?: DeclRecord;
  classRecord?: DeclRecord;
  weakRefs: number;
  importDeclaration?: ts.ImportDeclaration;
  importDeclaredTypeOnly?: boolean;
  importLocalName?: string;
  importSource?: string;
  initializer?: ts.Expression;
  kind: 'import' | 'function' | 'class' | 'variable' | 'type' | 'enum' | 'enum-member' | 'method' | 'property' | 'type-parameter';
  finding?: Finding;
}

export interface StaticAnalysisOptions {
  root: string;
  config: ResolvedCodeUsageMapConfig;
  detection: ProjectDetection;
  files: SourceCollection;
  signal?: AbortSignal;
}

function canonicalSymbol(checker: ts.TypeChecker, symbol: ts.Symbol): ts.Symbol {
  let current = symbol;
  const seen = new Set<ts.Symbol>();
  while ((current.flags & ts.SymbolFlags.Alias) !== 0 && !seen.has(current)) {
    seen.add(current);
    try {
      const next = checker.getAliasedSymbol(current);
      if (!next || next === current) break;
      current = next;
    } catch {
      break;
    }
  }
  return current;
}

function hasModifier(node: ts.Node, flag: ts.ModifierFlags): boolean {
  if (!ts.canHaveModifiers(node)) return false;
  return (ts.getCombinedModifierFlags(node as ts.Declaration) & flag) !== 0;
}

function isDefaultExport(node: ts.Node): boolean {
  return hasModifier(node, ts.ModifierFlags.Default);
}

function isExportedDeclaration(node: ts.Node): boolean {
  if (hasModifier(node, ts.ModifierFlags.Export)) return true;
  const parent = node.parent;
  if (parent && ts.isVariableStatement(parent)) return hasModifier(parent, ts.ModifierFlags.Export);
  return false;
}

function isAmbient(node: ts.Node, sourceFile: ts.SourceFile): boolean {
  if (sourceFile.isDeclarationFile) return true;
  let current: ts.Node | undefined = node;
  while (current) {
    if (hasModifier(current, ts.ModifierFlags.Ambient)) {
      return true;
    }
    if (ts.isModuleDeclaration(current) && (current.flags & ts.NodeFlags.GlobalAugmentation) !== 0) {
      return true;
    }
    current = current.parent;
  }
  return false;
}

function functionParentName(node: ts.Node): string | undefined {
  let current: ts.Node | undefined = node.parent;
  while (current) {
    if (
      (ts.isFunctionDeclaration(current) ||
        ts.isMethodDeclaration(current) ||
        ts.isGetAccessorDeclaration(current) ||
        ts.isSetAccessorDeclaration(current) ||
        ts.isClassDeclaration(current)) &&
      current.name &&
      ts.isIdentifier(current.name)
    ) {
      return current.name.text;
    }
    current = current.parent;
  }
  return undefined;
}

function findEnclosingClass(node: ts.Node): ts.ClassDeclaration | undefined {
  let current: ts.Node | undefined = node.parent;
  while (current) {
    if (ts.isClassDeclaration(current)) return current;
    if (ts.isFunctionLike(current)) return undefined;
    current = current.parent;
  }
  return undefined;
}

function parentRecordFor(node: ts.Node, recordByNode: Map<ts.Node, DeclRecord>): DeclRecord | undefined {
  let current: ts.Node | undefined = node.parent;
  while (current) {
    const record = recordByNode.get(current);
    if (record) return record;
    current = current.parent;
  }
  return undefined;
}

function lineColumn(
  sourceFile: ts.SourceFile,
  node: ts.Node,
): { line: number; column: number; endLine: number; endColumn: number } {
  const start = sourceFile.getLineAndCharacterOfPosition(node.getStart(sourceFile));
  const endPosition = Math.max(node.getStart(sourceFile), node.getEnd() - 1);
  const end = sourceFile.getLineAndCharacterOfPosition(endPosition);
  return {
    line: start.line + 1,
    column: start.character + 1,
    endLine: end.line + 1,
    endColumn: end.character + 2,
  };
}

function symbolCount(counts: Map<ts.Symbol, RefCounts>, symbol: ts.Symbol | undefined): RefCounts {
  if (!symbol) return { value: 0, type: 0, write: 0 };
  return counts.get(symbol) ?? { value: 0, type: 0, write: 0 };
}

function isTypePosition(node: ts.Node): boolean {
  if (!ts.isPartOfTypeNode(node)) return false;
  let current: ts.Node = node;
  while (current.parent) {
    const parent: ts.Node = current.parent;
    if (ts.isHeritageClause(parent)) {
      if (
        parent.token === ts.SyntaxKind.ExtendsKeyword &&
        parent.parent &&
        ts.isClassLike(parent.parent)
      ) {
        return false;
      }
      return true;
    }
    if (ts.isStatement(parent) || ts.isSourceFile(parent)) break;
    current = parent;
  }
  return true;
}

function isExportTypeContext(node: ts.Node): boolean {
  let current: ts.Node | undefined = node;
  while (current) {
    if (ts.isExportSpecifier(current)) {
      const declaration = current.parent?.parent;
      if (declaration && ts.isExportDeclaration(declaration)) return declaration.isTypeOnly;
    }
    if (ts.isStatement(current)) return false;
    current = current.parent;
  }
  return false;
}

function exportSpecifierContext(node: ts.Node): { local: boolean; reExport: boolean } | undefined {
  let current: ts.Node | undefined = node;
  while (current) {
    if (ts.isExportSpecifier(current)) {
      const declaration = current.parent.parent;
      if (declaration && ts.isExportDeclaration(declaration)) {
        return { local: !declaration.moduleSpecifier, reExport: Boolean(declaration.moduleSpecifier) };
      }
      return undefined;
    }
    if (ts.isStatement(current)) return undefined;
    current = current.parent;
  }
  return undefined;
}

function isDeclaredName(node: ts.Identifier | ts.PrivateIdentifier): boolean {
  const parent = node.parent;
  if (!parent) return false;
  if (ts.isImportClause(parent) && parent.name === node) return true;
  if (ts.isImportSpecifier(parent) && (parent.name === node || parent.propertyName === node)) return true;
  if (ts.isNamespaceImport(parent) && parent.name === node) return true;
  if (ts.isNamespaceExport(parent) && parent.name === node) return true;
  if (ts.isExportSpecifier(parent) && parent.propertyName === node) return true;
  if (ts.isImportEqualsDeclaration(parent) && parent.name === node) return true;
  if (ts.isBindingElement(parent) && parent.name === node) return true;
  if (ts.isVariableDeclaration(parent) && parent.name === node) return true;
  if (ts.isParameter(parent) && parent.name === node) return true;
  if (ts.isPropertyDeclaration(parent) && parent.name === node) return true;
  if (ts.isPropertySignature(parent) && parent.name === node) return true;
  if (ts.isPropertyAssignment(parent) && parent.name === node) return true;
  if (ts.isMethodDeclaration(parent) && parent.name === node) return true;
  if (ts.isMethodSignature(parent) && parent.name === node) return true;
  if (ts.isGetAccessorDeclaration(parent) && parent.name === node) return true;
  if (ts.isSetAccessorDeclaration(parent) && parent.name === node) return true;
  if (ts.isFunctionDeclaration(parent) && parent.name === node) return true;
  if (ts.isFunctionExpression(parent) && parent.name === node) return true;
  if (ts.isClassDeclaration(parent) && parent.name === node) return true;
  if (ts.isClassExpression(parent) && parent.name === node) return true;
  if (ts.isInterfaceDeclaration(parent) && parent.name === node) return true;
  if (ts.isTypeAliasDeclaration(parent) && parent.name === node) return true;
  if (ts.isEnumDeclaration(parent) && parent.name === node) return true;
  if (ts.isEnumMember(parent) && parent.name === node) return true;
  if (ts.isTypeParameterDeclaration(parent) && parent.name === node) return true;
  if (ts.isModuleDeclaration(parent) && parent.name === node) return true;
  if (ts.isJsxAttribute(parent) && parent.name === node) return true;
  if (ts.isLabeledStatement(parent) && parent.label === node) return true;
  if ((ts.isBreakStatement(parent) || ts.isContinueStatement(parent)) && parent.label === node) return true;
  if (ts.isNamedTupleMember(parent) && parent.name === node) return true;
  return false;
}

function isWriteReference(node: ts.Node): boolean {
  const direct = node.parent;
  if (direct && ts.isBinaryExpression(direct)) {
    if (direct.left === node && direct.operatorToken.kind === ts.SyntaxKind.EqualsToken) return true;
  }
  if (
    direct &&
    (ts.isPrefixUnaryExpression(direct) || ts.isPostfixUnaryExpression(direct)) &&
    (direct.operator === ts.SyntaxKind.PlusPlusToken || direct.operator === ts.SyntaxKind.MinusMinusToken) &&
    direct.operand === node
  ) {
    return true;
  }
  if (direct && ts.isPropertyAccessExpression(direct) && direct.name === node) {
    let target: ts.Node = direct;
    while (target.parent && ts.isParenthesizedExpression(target.parent)) target = target.parent;
    const parent = target.parent;
    if (parent && ts.isBinaryExpression(parent) && parent.left === target && parent.operatorToken.kind === ts.SyntaxKind.EqualsToken) {
      return true;
    }
  }

  let current: ts.Node = node;
  while (current.parent) {
    const parent = current.parent;
    if (parent && ts.isBinaryExpression(parent) && parent.left === current) {
      return parent.operatorToken.kind === ts.SyntaxKind.EqualsToken;
    }
    if (
      parent &&
      (ts.isPrefixUnaryExpression(parent) || ts.isPostfixUnaryExpression(parent)) &&
      (parent.operator === ts.SyntaxKind.PlusPlusToken || parent.operator === ts.SyntaxKind.MinusMinusToken) &&
      parent.operand === current
    ) {
      return true;
    }
    const assignmentPatternParent =
      ts.isParenthesizedExpression(parent) ||
      ts.isArrayLiteralExpression(parent) ||
      ts.isObjectLiteralExpression(parent) ||
      ts.isPropertyAssignment(parent) ||
      ts.isShorthandPropertyAssignment(parent) ||
      ts.isSpreadElement(parent) ||
      ts.isSpreadAssignment(parent);
    if (assignmentPatternParent) {
      current = parent;
      continue;
    }
    break;
  }
  return false;
}

function expressionHasSideEffects(expression: ts.Expression | undefined): boolean {
  if (!expression) return false;
  let hasSideEffects = false;
  const visit = (node: ts.Node): void => {
    if (hasSideEffects) return;
    if (
      ts.isCallExpression(node) ||
      ts.isNewExpression(node) ||
      ts.isAwaitExpression(node) ||
      ts.isYieldExpression(node) ||
      ts.isDeleteExpression(node) ||
      ts.isTaggedTemplateExpression(node) ||
      ts.isPrefixUnaryExpression(node) ||
      ts.isPostfixUnaryExpression(node) ||
      (ts.isBinaryExpression(node) && node.operatorToken.kind >= ts.SyntaxKind.FirstAssignment && node.operatorToken.kind <= ts.SyntaxKind.LastAssignment)
    ) {
      hasSideEffects = true;
      return;
    }
    ts.forEachChild(node, visit);
  };
  visit(expression);
  return hasSideEffects;
}

function typescriptModuleExports(checker: ts.TypeChecker, sourceFile: ts.SourceFile): Set<ts.Symbol> {
  const result = new Set<ts.Symbol>();
  const moduleSymbol = checker.getSymbolAtLocation(sourceFile);
  if (!moduleSymbol) return result;
  try {
    for (const exported of checker.getExportsOfModule(moduleSymbol)) {
      result.add(canonicalSymbol(checker, exported));
      result.add(exported);
    }
  } catch {
    // Some virtual/broken files have no usable module symbol.
  }
  return result;
}

function sfcHasJsx(sourceFile: ts.SourceFile): boolean {
  let found = false;
  const visit = (node: ts.Node): void => {
    if (found) return;
    if (ts.isJsxElement(node) || ts.isJsxSelfClosingElement(node) || ts.isJsxFragment(node)) {
      found = true;
      return;
    }
    ts.forEachChild(node, visit);
  };
  visit(sourceFile);
  return found;
}

function buildSourceFileMap(staticFiles: Array<string>, program: ReturnType<typeof createStaticProgram>): Map<string, ts.SourceFile> {
  const result = new Map<string, ts.SourceFile>();
  const virtualOriginals = new Map<string, string>();
  for (const virtual of program.virtualByFile.values()) {
    virtualOriginals.set(path.normalize(virtual.originalFile), virtual.fileName);
  }
  for (const file of staticFiles) {
    const normalized = path.normalize(file);
    const virtualPath = virtualOriginals.get(normalized);
    const sourceFile = program.program.getSourceFile(virtualPath ?? normalized);
    if (sourceFile) result.set(normalized, sourceFile);
  }
  return result;
}

/**
 * Static JavaScript/TypeScript analysis. Uses the TypeScript compiler API and
 * never executes project source code.
 */
export function analyzeStatic(options: StaticAnalysisOptions): StaticAnalysisResult {
  const { root, config, files, signal } = options;
  const warnings: string[] = [];
  const compiler = loadCompilerOptions(config.tsconfig);
  warnings.push(...compiler.warnings);

  const staticProgram = createStaticProgram(files.scripts, compiler.options, warnings);
  const checker = staticProgram.checker;
  const sourceFileMap = buildSourceFileMap(files.scripts, staticProgram);
  const analyzedFiles = [...sourceFileMap.keys()];
  const analysisMode: AnalysisMode = config.mode;

  const graph = buildImportGraph(
    staticProgram,
    analyzedFiles,
    root,
    [...config.entryPoints, ...options.detection.detectedEntryPoints],
    files.html,
    signal,
  );
  warnings.push(...graph.warnings);
  const entryLikeFiles = new Set(
    graph.modules.filter((module) => module.entry || module.pageLike).map((module) => module.file),
  );
  const dynamicConsumedFiles = new Set<string>();
  for (const record of graph.imports) {
    if ((record.kind === 'dynamic' || record.kind === 'require') && record.resolvedFile) {
      dynamicConsumedFiles.add(path.normalize(record.resolvedFile));
    }
    if (record.kind === 're-export' && record.bindings.length === 0 && record.resolvedFile) {
      // `export *` re-exports every public member of the target module.
      dynamicConsumedFiles.add(path.normalize(record.resolvedFile));
    }
  }

  const records: DeclRecord[] = [];
  const recordByNode = new Map<ts.Node, DeclRecord>();
  const importAliasSymbols = new Map<ts.Symbol, ImportRecord>();
  const recordsByFile = new Map<string, DeclRecord[]>();
  const moduleExportsByFile = new Map<string, Set<ts.Symbol>>();

  const addRecord = (
    record: Omit<DeclRecord, 'spanBytes' | 'weakRefs' | 'classDecorated' | 'classExported' | 'relativeFile'> & {
      spanBytes?: number;
      weakRefs?: number;
      classDecorated?: boolean;
      classExported?: boolean;
    },
  ): DeclRecord => {
    const relativeFile = toPosix(path.relative(root, record.file));
    const parentRecord = parentRecordFor(record.node, recordByNode);
    const enclosingClass = findEnclosingClass(record.node);
    const classRecord = record.kind === 'class' ? undefined : enclosingClass ? recordByNode.get(enclosingClass) : undefined;
    const finalRecord: DeclRecord = {
      ...record,
      relativeFile,
      spanBytes: record.spanBytes ?? Math.max(0, record.node.getEnd() - record.node.getStart(record.sourceFile)),
      weakRefs: record.weakRefs ?? 0,
      classDecorated: record.classDecorated ?? Boolean(classRecord?.decorated),
      classExported: record.classExported ?? Boolean(classRecord?.exported),
      parentRecord: record.parentRecord ?? parentRecord,
      classRecord: record.classRecord ?? classRecord,
    };
    records.push(finalRecord);
    recordByNode.set(finalRecord.node, finalRecord);
    const list = recordsByFile.get(finalRecord.file);
    if (list) list.push(finalRecord);
    else recordsByFile.set(finalRecord.file, [finalRecord]);
    if (finalRecord.symbol) {
      const exports = moduleExportsByFile.get(finalRecord.file);
      if (!exports) {
        moduleExportsByFile.set(finalRecord.file, typescriptModuleExports(checker, record.sourceFile));
      }
    }
    return finalRecord;
  };

  const getExports = (sourceFile: ts.SourceFile, file: string): Set<ts.Symbol> => {
    const existing = moduleExportsByFile.get(file);
    if (existing) return existing;
    const exports = typescriptModuleExports(checker, sourceFile);
    moduleExportsByFile.set(file, exports);
    return exports;
  };

  for (const [file, sourceFile] of sourceFileMap) {
    if (isTestOrStoryFile(file) || isDeclarationFile(file)) continue;
    const exports = getExports(sourceFile, file);

    const addImportRecords = (): void => {
      const visitImports = (node: ts.Node): void => {
        if (ts.isImportDeclaration(node)) {
          const source = ts.isStringLiteralLike(node.moduleSpecifier) ? node.moduleSpecifier.text : '';
          const clause = node.importClause;
          if (!clause || !source) return;
          const names: Array<{ node: ts.Identifier; imported: string; typeOnly: boolean }> = [];
          if (clause.name) names.push({ node: clause.name, imported: 'default', typeOnly: clause.isTypeOnly });
          if (clause.namedBindings) {
            if (ts.isNamespaceImport(clause.namedBindings)) {
              names.push({
                node: clause.namedBindings.name,
                imported: '*',
                typeOnly: clause.isTypeOnly,
              });
            } else {
              for (const element of clause.namedBindings.elements) {
                names.push({
                  node: element.name,
                  imported: element.propertyName?.text ?? element.name.text,
                  typeOnly: clause.isTypeOnly || element.isTypeOnly,
                });
              }
            }
          }
          for (const binding of names) {
            const symbol = checker.getSymbolAtLocation(binding.node);
            const position = lineColumn(sourceFile, binding.node);
            const category: FindingCategory = binding.typeOnly ? 'unused-type-only-import' : 'unused-import';
            const record = addRecord({
              node,
              nameNode: binding.node,
              sourceFile,
              file,
              symbol,
              canonical: symbol ? canonicalSymbol(checker, symbol) : undefined,
              name: binding.node.text,
              category,
              symbolKind: 'import',
              exported: false,
              defaultExport: false,
              typeOnlyDeclaration: binding.typeOnly,
              decorated: false,
              classDecorated: false,
              ambient: false,
              line: position.line,
              column: position.column,
              endLine: position.endLine,
              endColumn: position.endColumn,
              importDeclaration: node,
              importDeclaredTypeOnly: clause.isTypeOnly,
              importLocalName: binding.node.text,
              importSource: source,
              kind: 'import',
            });
            if (symbol && binding.imported === '*') {
              importAliasSymbols.set(symbol, {
                file,
                relativeFile: toPosix(path.relative(root, file)),
                specifier: source,
                kind: 'static',
                line: position.line,
                column: position.column,
                bindings: [],
                typeOnly: binding.typeOnly,
                isAsset: false,
                sourceNodeKind: 'import',
              });
            }
            void record;
          }
          return;
        }
        ts.forEachChild(node, visitImports);
      };
      visitImports(sourceFile);
    };
    addImportRecords();

    const visit = (node: ts.Node): void => {
      const make = (
        nameNode: ts.Node | undefined,
        kind: DeclRecord['kind'],
        category: FindingCategory,
        symbolKind: SymbolKind,
        extra: {
          typeOnly?: boolean;
          exported?: boolean;
          defaultExport?: boolean;
          parentName?: string;
          initializer?: ts.Expression;
          name?: string;
        } = {},
      ): void => {
        const symbol = nameNode ? checker.getSymbolAtLocation(nameNode) : undefined;
        if (!symbol) return;
        const canonical = canonicalSymbol(checker, symbol);
        const position = lineColumn(sourceFile, nameNode ?? node);
        const classNode = findEnclosingClass(node);
        const classRecord = classNode ? recordByNode.get(classNode) : undefined;
        const decorated = Boolean(ts.canHaveDecorators(node) && ts.getDecorators(node)?.length);
        const classDecorated = Boolean(
          classNode && ts.canHaveDecorators(classNode) && ts.getDecorators(classNode)?.length,
        );
        const moduleExported = exports.has(canonical) || exports.has(symbol);
        const exported =
          extra.exported ?? (moduleExported || isExportedDeclaration(node));
        addRecord({
          node,
          nameNode,
          sourceFile,
          file,
          symbol,
          canonical,
          name: extra.name ?? (nameNode && ts.isIdentifier(nameNode) ? nameNode.text : nameNode?.getText(sourceFile) ?? '<anonymous>'),
          category,
          symbolKind,
          exported,
          classExported: classRecord?.exported ?? Boolean(classNode && (exports.has(canonical) || isExportedDeclaration(classNode))),
          defaultExport: extra.defaultExport ?? isDefaultExport(node),
          typeOnlyDeclaration: extra.typeOnly ?? false,
          decorated,
          classDecorated,
          ambient: isAmbient(node, sourceFile),
          line: position.line,
          column: position.column,
          endLine: position.endLine,
          endColumn: position.endColumn,
          parent: extra.parentName ?? functionParentName(node) ?? (classNode && classNode.name ? classNode.name.text : undefined),
          ...(extra.initializer ? { initializer: extra.initializer } : {}),
          kind,
        });
      };

      if (ts.isFunctionDeclaration(node) && node.name && node.body) {
        make(node.name, 'function', 'unused-function', 'function');
      } else if (ts.isClassDeclaration(node) && node.name) {
        make(node.name, 'class', 'unused-class', 'class');
      } else if (ts.isVariableDeclaration(node) && ts.isIdentifier(node.name)) {
        const constStatement = ts.isVariableDeclarationList(node.parent) && (node.parent.flags & ts.NodeFlags.Const) !== 0;
        make(node.name, 'variable', 'unused-variable', constStatement ? 'constant' : 'variable', {
          initializer: node.initializer,
        });
      } else if (ts.isInterfaceDeclaration(node) && node.name) {
        make(node.name, 'type', 'unused-type', 'interface', { typeOnly: true });
      } else if (ts.isTypeAliasDeclaration(node) && node.name) {
        make(node.name, 'type', 'unused-type', 'type', { typeOnly: true });
      } else if (ts.isEnumDeclaration(node) && node.name) {
        make(node.name, 'enum', 'unused-type', 'enum', { typeOnly: false });
      } else if (ts.isEnumMember(node) && ts.isIdentifier(node.name)) {
        const enumNode = node.parent;
        const enumRecord = recordByNode.get(enumNode);
        make(node.name, 'enum-member', 'unused-enum-member', 'enum-member', {
          parentName: enumRecord?.name ?? (enumNode.name && ts.isIdentifier(enumNode.name) ? enumNode.name.text : undefined),
        });
      } else if (
        (ts.isMethodDeclaration(node) ||
          ts.isGetAccessorDeclaration(node) ||
          ts.isSetAccessorDeclaration(node)) &&
        node.name &&
        ts.isIdentifier(node.name) &&
        findEnclosingClass(node) &&
        !ts.isConstructorDeclaration(node) &&
        !FRAMEWORK_METHOD_NAMES.has(node.name.text)
      ) {
        make(node.name, 'method', 'unused-class-method', 'method');
      } else if (
        ts.isPropertyDeclaration(node) &&
        ts.isIdentifier(node.name) &&
        (hasModifier(node, ts.ModifierFlags.Private) || ts.isPrivateIdentifier(node.name))
      ) {
        make(node.name, 'property', 'unused-variable', 'property', { initializer: node.initializer });
      } else if (ts.isTypeParameterDeclaration(node)) {
        const enclosing = parentRecordFor(node, recordByNode);
        make(node.name, 'type-parameter', 'unused-type-parameter', 'type-parameter', {
          parentName: enclosing?.name,
        });
      }

      ts.forEachChild(node, visit);
    };
    visit(sourceFile);
  }

  if (signal?.aborted) throw new Error('Analysis aborted');

  // Reference collection -----------------------------------------------------------------
  const valueRefs = new Map<ts.Symbol, RefCounts>();
  const bump = (map: Map<ts.Symbol, RefCounts>, symbol: ts.Symbol, kind: 'value' | 'type' | 'write'): void => {
    const current = map.get(symbol) ?? { value: 0, type: 0, write: 0 };
    current[kind] += 1;
    map.set(symbol, current);
  };
  const recordsByCanonical = new Map<ts.Symbol, DeclRecord[]>();
  for (const record of records) {
    if (record.canonical) {
      const list = recordsByCanonical.get(record.canonical);
      if (list) list.push(record);
      else recordsByCanonical.set(record.canonical, [record]);
    }
  }
  const dynamicNamespaceAliases = new Set<ts.Symbol>();
  const jsxFiles = new Set<string>();

  const incrementReference = (symbol: ts.Symbol, kind: 'value' | 'type' | 'write', node: ts.Node, sourceFile: ts.SourceFile): void => {
    const file = staticProgram.virtualByFile.get(path.normalize(sourceFile.fileName))?.originalFile ?? path.normalize(sourceFile.fileName);
    if (symbol.flags & ts.SymbolFlags.Alias) {
      bump(valueRefs, symbol, kind);
      let target: ts.Symbol;
      try {
        target = canonicalSymbol(checker, symbol);
      } catch {
        return;
      }
      const selfRecords = recordsByCanonical.get(target) ?? [];
      const isSelf = selfRecords.some(
        (record) =>
          record.file === file &&
          node.getStart(sourceFile) >= record.node.getStart(record.sourceFile) &&
          node.getEnd() <= record.node.getEnd(),
      );
      if (!isSelf) bump(valueRefs, target, kind);
    } else {
      const selfRecords = recordsByCanonical.get(symbol) ?? [];
      const isSelf = selfRecords.some(
        (record) =>
          record.file === file &&
          node.getStart(sourceFile) >= record.node.getStart(record.sourceFile) &&
          node.getEnd() <= record.node.getEnd(),
      );
      if (!isSelf) bump(valueRefs, symbol, kind);
    }
  };

  const walkProgramFile = (sourceFile: ts.SourceFile): void => {
    if (sourceFile.isDeclarationFile) return;
    const normalized = path.normalize(sourceFile.fileName);
    if (normalized.includes(`${path.sep}node_modules${path.sep}`)) return;
    if (sfcHasJsx(sourceFile)) jsxFiles.add(normalized);

    const visit = (node: ts.Node): void => {
      if (ts.isIdentifier(node) || ts.isPrivateIdentifier(node)) {
        if (!isDeclaredName(node)) {
          const symbol = checker.getSymbolAtLocation(node);
          if (symbol) {
            const kind: 'value' | 'type' | 'write' = isWriteReference(node)
              ? 'write'
              : isTypePosition(node) || isExportTypeContext(node)
                ? 'type'
                : 'value';
            const exportContext = exportSpecifierContext(node);
            if (exportContext?.local) {
              // A local export clause keeps an import binding alive, but it does
              // not prove the exported declaration has a consumer. Count only
              // local aliases so unused exports remain visible.
              if ((symbol.flags & ts.SymbolFlags.Alias) !== 0) {
                bump(valueRefs, symbol, kind);
              }
            } else {
              incrementReference(symbol, kind, node, sourceFile);
            }
          }
        }
      }

      if (ts.isElementAccessExpression(node) && ts.isStringLiteralLike(node.argumentExpression)) {
        try {
          const type = checker.getTypeAtLocation(node.expression);
          const property = checker.getPropertyOfType(type, node.argumentExpression.text);
          if (property) {
            incrementReference(property, isWriteReference(node) ? 'write' : 'value', node, sourceFile);
          }
        } catch {
          // Unresolvable dynamic property; ignored.
        }
      }

      if (ts.isElementAccessExpression(node) && !ts.isStringLiteralLike(node.argumentExpression) && !ts.isNumericLiteral(node.argumentExpression)) {
        const symbol = checker.getSymbolAtLocation(node.expression);
        if (symbol && (symbol.flags & ts.SymbolFlags.Alias) !== 0) {
          dynamicNamespaceAliases.add(symbol);
        }
      }

      if (ts.isCallExpression(node) && ts.isPropertyAccessExpression(node.expression)) {
        const name = node.expression.name.text;
        if ((name === 'keys' || name === 'values' || name === 'entries') && node.arguments.length > 0) {
          const argument = node.arguments[0];
          if (argument) {
            const symbol = checker.getSymbolAtLocation(argument);
            if (symbol && (symbol.flags & ts.SymbolFlags.Alias) !== 0) dynamicNamespaceAliases.add(symbol);
          }
        }
      }

      if (
        (ts.isSpreadElement(node) || ts.isSpreadAssignment(node)) &&
        ts.isIdentifier(node.expression)
      ) {
        const symbol = checker.getSymbolAtLocation(node.expression);
        if (symbol && (symbol.flags & ts.SymbolFlags.Alias) !== 0) dynamicNamespaceAliases.add(symbol);
      }

      ts.forEachChild(node, visit);
    };
    visit(sourceFile);

    // React's classic JSX transform does not produce an identifier reference.
    if (jsxFiles.has(normalized)) {
      for (const record of records) {
        if (
          record.kind === 'import' &&
          record.importLocalName === 'React' &&
          record.file === (staticProgram.virtualByFile.get(normalized)?.originalFile ?? normalized)
        ) {
          record.weakRefs += 1;
        }
      }
    }
  };

  for (const sourceFile of staticProgram.program.getSourceFiles()) {
    if (signal?.aborted) break;
    walkProgramFile(sourceFile);
  }
  if (signal?.aborted) throw new Error('Analysis aborted');

  // Vue/Svelte/Astro template identifiers are conservative weak references.
  for (const [file, sourceFile] of sourceFileMap) {
    const extension = path.extname(file).toLowerCase();
    if (!['.vue', '.svelte', '.astro'].includes(extension)) continue;
    let content = '';
    try {
      content = ts.sys.readFile(file) ?? '';
    } catch {
      continue;
    }
    const extraction = extractSfc(file, content);
    if (!extraction) continue;
    const names = templateIdentifiers(extraction.templateText);
    for (const record of recordsByFile.get(file) ?? []) {
      if (names.has(record.name)) record.weakRefs += 1;
    }
    void sourceFile;
  }

  // Dynamic namespace imports consume arbitrary exports of their target module.
  for (const [aliasSymbol, record] of importAliasSymbols) {
    if (!dynamicNamespaceAliases.has(aliasSymbol)) continue;
    const importRecord = graph.imports.find(
      (item) =>
        item.file === record.file &&
        item.specifier === record.specifier &&
        item.bindings.some((binding) => binding.imported === '*'),
    );
    if (importRecord?.resolvedFile) dynamicConsumedFiles.add(path.normalize(importRecord.resolvedFile));
  }

  const dynamicPatterns: DynamicPatternRecord[] = graph.dynamicPatterns;
  const patternsByFile = new Map<string, Set<DynamicPatternRecord['kind']>>();
  for (const pattern of dynamicPatterns) {
    const set = patternsByFile.get(pattern.file) ?? new Set<DynamicPatternRecord['kind']>();
    set.add(pattern.kind);
    patternsByFile.set(pattern.file, set);
  }
  const projectDynamicRisk = dynamicPatterns.some((pattern) =>
    ['eval', 'new-function', 'dynamic-member', 'reflection', 'dynamic-module'].includes(pattern.kind),
  );

  // Findings ---------------------------------------------------------------------------------
  const findings: Finding[] = [];
  const typeOnlyUsage = new Map<string, TypeOnlyDependencyImport>();
  const importRecords = records.filter((record) => record.kind === 'import');

  for (const record of importRecords) {
    const counts = symbolCount(valueRefs, record.symbol);
    const total = counts.value + counts.type + record.weakRefs;
    if (total === 0) {
      const filePatterns = patternsByFile.get(record.file) ?? new Set<DynamicPatternRecord['kind']>();
      const dynamicRisk = filePatterns.has('eval') || filePatterns.has('new-function');
      const category: FindingCategory = record.importDeclaredTypeOnly
        ? 'unused-type-only-import'
        : record.typeOnlyDeclaration
          ? 'unused-type-only-import'
          : 'unused-import';
      const status: AnalysisStatus = dynamicRisk ? 'potentially-unused' : 'confirmed-unused';
      const confidence: Confidence = dynamicRisk ? 'medium' : 'high';
      const finding = createFinding({
        root,
        category,
        status,
        confidence,
        title: `Unused import "${record.name}"`,
        description: `The imported binding "${record.name}" from "${record.importSource ?? 'a module'}" has no static references. ${
          dynamicRisk
            ? 'Dynamic eval was detected in this file, so removal needs review.'
            : 'The import binding can be removed safely; module evaluation side effects must be preserved.'
        }`,
        file: record.file,
        line: record.line,
        column: record.column,
        endLine: record.endLine,
        endColumn: record.endColumn,
        symbol: record.name,
        symbolKind: 'import',
        ...(record.parent ? { parent: record.parent } : {}),
        size: {
          sourceBytes: record.spanBytes,
          estimatedRemovableBytes: dynamicRisk ? 0 : record.name.length + 6,
          basis: 'Import binding syntax only; module evaluation is preserved.',
        },
        evidence: [
          {
            kind: 'no-static-reference',
            description: `No value or type references found for "${record.name}".`,
            file: toPosix(record.relativeFile),
            line: record.line,
          },
          ...(dynamicRisk
            ? [
                {
                  kind: 'dynamic-access' as const,
                  description: 'Dynamic eval/new Function in the same file can access local bindings.',
                  file: toPosix(record.relativeFile),
                  line: record.line,
                },
              ]
            : []),
        ],
        tags: ['import', ...(record.importDeclaredTypeOnly ? ['type-only'] : [])],
        fingerprintSuffix: record.importSource ?? '',
      });
      record.finding = finding;
      findings.push(finding);
    } else if (!record.importDeclaredTypeOnly && counts.value === 0 && counts.type > 0) {
      const entry: TypeOnlyDependencyImport = {
        source: record.importSource ?? '',
        file: record.file,
        relativeFile: record.relativeFile,
        names: [record.name],
      };
      const packageName = graph.externalImports.find(
        (external) =>
          external.file === record.file && external.specifier === record.importSource,
      )?.packageName;
      if (packageName) entry.packageName = packageName;
      const key = `${entry.file}|${entry.source}`;
      const existing = typeOnlyUsage.get(key);
      if (existing) {
        if (!existing.names.includes(record.name)) existing.names.push(record.name);
      } else {
        typeOnlyUsage.set(key, entry);
      }
    }
  }

  const parentHasFinding = (record: DeclRecord): boolean => {
    let current = record.parentRecord;
    while (current) {
      if (current.finding) return true;
      current = current.parentRecord;
    }
    return false;
  };

  const importDeclGroups = new Map<ts.ImportDeclaration, DeclRecord[]>();
  for (const record of importRecords) {
    if (!record.importDeclaration) continue;
    const group = importDeclGroups.get(record.importDeclaration);
    if (group) group.push(record);
    else importDeclGroups.set(record.importDeclaration, [record]);
  }

  for (const record of records) {
    if (record.kind === 'import') continue;
    if (record.ambient) continue;
    if (record.decorated || record.classDecorated) continue;
    if (record.exported && analysisMode === 'library') continue;
    if (record.exported && entryLikeFiles.has(record.file)) continue;
    if (record.exported && dynamicConsumedFiles.has(record.file)) continue;
    if (record.kind === 'method' && record.classExported && (analysisMode === 'library' || entryLikeFiles.has(record.file))) {
      continue;
    }
    if (parentHasFinding(record)) continue;
    if (record.kind === 'method' && record.parentRecord?.kind === 'class' && parentHasFinding(record.parentRecord)) {
      continue;
    }

    const counts = symbolCount(valueRefs, record.canonical);
    const total = counts.value + counts.type + record.weakRefs;
    if (total > 0) continue;

    const filePatterns = patternsByFile.get(record.file) ?? new Set<DynamicPatternRecord['kind']>();
    const dynamicEval = filePatterns.has('eval') || filePatterns.has('new-function');
    const dynamicMember = filePatterns.has('dynamic-member') || filePatterns.has('reflection');
    const exportedRisk =
      record.exported &&
      (graph.hasDynamicModuleLoading || projectDynamicRisk || dynamicConsumedFiles.has(record.file));
    const isTypeOnly = record.typeOnlyDeclaration;
    const category = isTypeOnly || record.kind === 'type-parameter' || record.kind === 'enum-member'
      ? record.category
      : record.exported
        ? 'unused-export'
        : record.category;

    let status: AnalysisStatus;
    let confidence: Confidence;
    let severity: Finding['severity'] | undefined;
    if (exportedRisk) {
      status = 'dynamically-referenced';
      confidence = 'low';
      severity = 'info';
    } else if (record.exported) {
      status = 'potentially-unused';
      confidence = record.kind === 'method' ? 'medium' : 'high';
      severity = 'low';
    } else if (record.kind === 'method' && !isTypeOnly) {
      const privateMethod = record.nameNode ? ts.isPrivateIdentifier(record.nameNode) || hasModifier(record.node, ts.ModifierFlags.Private) : false;
      const memberRisk = dynamicMember || dynamicEval || !privateMethod;
      status = memberRisk ? 'potentially-unused' : 'confirmed-unused';
      confidence = privateMethod && !dynamicMember && !dynamicEval ? 'high' : 'medium';
      severity = privateMethod ? undefined : 'low';
    } else if (record.kind === 'enum-member') {
      status = 'potentially-unused';
      confidence = 'medium';
      severity = 'low';
    } else if (record.kind === 'type-parameter') {
      status = 'confirmed-unused';
      confidence = 'high';
      severity = 'low';
    } else if (record.kind === 'variable' && counts.write > 0) {
      status = 'confirmed-unused';
      confidence = dynamicEval ? 'medium' : 'high';
      severity = 'low';
    } else if (dynamicEval) {
      status = 'potentially-unused';
      confidence = 'medium';
    } else {
      status = 'confirmed-unused';
      confidence = 'high';
    }
    if (record.kind === 'type-parameter' && record.parentRecord?.exported) continue;
    if (record.kind === 'enum-member' && record.parentRecord?.finding) continue;
    if (record.kind === 'method' && record.parentRecord?.finding) continue;

    const parentKind = record.symbolKind;
    const typeBasis = isTypeOnly ? 'Type-only source span.' : 'Declaration source span.';
    const sideEffectInitializer = record.kind === 'variable' && expressionHasSideEffects(record.initializer);
    const canEstimate = (status === 'confirmed-unused' || status === 'potentially-unused') && !record.exported;
    const estimated =
      canEstimate && status === 'confirmed-unused' && !sideEffectInitializer && record.kind !== 'method'
        ? record.spanBytes
        : canEstimate && status === 'confirmed-unused' && record.kind === 'method'
          ? record.spanBytes
          : 0;
    const titlePrefix =
      status === 'confirmed-unused'
        ? 'Unused'
        : status === 'dynamically-referenced'
          ? 'Dynamically referenced'
          : 'Potentially unused';
    const title = `${titlePrefix} ${humanizeKind(parentKind)} "${record.name}"`;
    const evidence = [
      {
        kind: 'no-static-reference' as const,
        description: `No static value or type references were found for "${record.name}".`,
        file: record.relativeFile,
        line: record.line,
      },
      ...(record.exported
        ? [
            {
              kind: 'static-reference' as const,
              description: 'The declaration is exported. External consumers cannot be fully enumerated.',
              file: record.relativeFile,
              line: record.line,
            },
          ]
        : []),
      ...(status === 'dynamically-referenced'
        ? [
            {
              kind: 'dynamic-access' as const,
              description: 'Dynamic module loading or reflection was detected in the project.',
              file: record.relativeFile,
              line: record.line,
            },
          ]
        : []),
      ...(dynamicEval
        ? [
            {
              kind: 'dynamic-access' as const,
              description: 'eval/new Function is present in this file.',
              file: record.relativeFile,
              line: record.line,
            },
          ]
        : []),
      ...(sideEffectInitializer
        ? [
            {
              kind: 'parser' as const,
              description: 'The initializer contains calls/assignments; removing it can change behavior.',
              file: record.relativeFile,
              line: record.line,
            },
          ]
        : []),
    ];
    const finding = createFinding({
      root,
      category,
      status,
      confidence,
      ...(severity ? { severity } : {}),
      title,
      description:
        status === 'confirmed-unused'
          ? `${capitalize(humanizeKind(parentKind))} "${record.name}" is not referenced inside the analyzed project. ${
              record.exported ? '' : 'Static evidence supports removal after checking for reflection. '
            }${isTypeOnly ? 'This is a type-only declaration.' : ''}${
              sideEffectInitializer ? ' Preserve initializer side effects.' : ''
            }`
          : status === 'dynamically-referenced'
            ? `No static references were found, but dynamic module loading/reflection means this export may be consumed externally. Do not remove without verification.`
            : `No static references were found. ${record.exported ? 'It is exported, so external or framework consumers may still use it.' : 'Runtime states not observed by static analysis may still use it.'}`,
      file: record.file,
      line: record.line,
      column: record.column,
      endLine: record.endLine,
      endColumn: record.endColumn,
      symbol: record.name,
      symbolKind: parentKind,
      ...(record.parent ? { parent: record.parent } : {}),
      size: {
        sourceBytes: record.spanBytes,
        ...(estimated > 0 ? { estimatedRemovableBytes: estimated } : {}),
        basis:
          estimated > 0
            ? `${typeBasis} Overlapping spans are not guaranteed to add up.`
            : sideEffectInitializer
              ? 'Initializer has side effects; no removable-byte estimate is claimed.'
              : 'Removal is not recommended without external/runtime verification; no savings estimate claimed.',
      },
      evidence,
      tags: [
        record.exported ? 'exported' : 'local',
        ...(isTypeOnly ? ['type-only'] : []),
        ...(record.kind === 'method' ? ['class-member'] : []),
        ...(sideEffectInitializer ? ['side-effect-initializer'] : []),
      ],
      fingerprintSuffix: record.defaultExport ? 'default' : undefined,
    });
    record.finding = finding;
    findings.push(finding);
  }

  // Attach conservative unused-import fixes: only when an entire import
  // declaration is unused. Value imports become side-effect imports so module
  // evaluation semantics are preserved. Type-only imports are deleted.
  for (const [declaration, group] of importDeclGroups) {
    if (group.length === 0) continue;
    if (!group.every((record) => record.finding && record.finding.status === 'confirmed-unused')) continue;
    const first = group[0];
    const firstFinding = first?.finding;
    if (!first || !firstFinding) continue;
    const sourceFile = first.sourceFile;
    const start = declaration.getStart(sourceFile);
    const end = declaration.getEnd();
    const expectedText = sourceFile.text.slice(start, end);
    if (/\b(?:with|assert)\s*\{/.test(expectedText)) continue;
    // Do not delete comments attached to an import declaration. A developer
    // should review those manually rather than have an autofix erase intent.
    if (expectedText.includes('/*') || expectedText.includes('//')) continue;
    const clause = declaration.importClause;
    if (!clause) continue;
    if (clause.isTypeOnly) {
      firstFinding.fix = {
        kind: 'remove-range',
        startOffset: start,
        endOffset: end,
        expectedText,
        safe: true,
        description: 'Delete a fully unused type-only import. Type-only code has no runtime effect.',
      };
      firstFinding.size.estimatedRemovableBytes = expectedText.length;
      firstFinding.size.basis = 'Type-only import declaration removed.';
    } else if (!group.every((record) => record.typeOnlyDeclaration)) {
      const moduleText = declaration.moduleSpecifier.getText(sourceFile);
      firstFinding.fix = {
        kind: 'replace-range',
        startOffset: start,
        endOffset: end,
        replacement: `import ${moduleText};`,
        expectedText,
        safe: true,
        description:
          'Replace the fully unused import with a side-effect import, preserving module evaluation.',
      };
      firstFinding.size.estimatedRemovableBytes = 0;
      firstFinding.size.basis = 'Only binding syntax is removed; module evaluation is preserved.';
    }
  }

  // Unused modules ---------------------------------------------------------------------------
  if (graph.entryPoints.length > 0 && !graph.hasGlobImports) {
    for (const module of graph.modules) {
      if (module.reachable || module.entry || module.importerCount > 0 || module.dynamicImportTarget) continue;
      if (module.isTest || module.pageLike) continue;
      if (isDeclarationFile(module.file)) continue;
      if (!['js', 'jsx', 'mjs', 'cjs', 'ts', 'tsx', 'mts', 'cts'].includes(module.type)) continue;
      const relative = module.relativeFile.toLowerCase();
      const basename = path.basename(relative);
      if (
        /\/(scripts|tools|bin|config|configs|migrations|seeds)\//.test(`/${relative}/`) ||
        /\.(config|setup)\.[^.]+$/.test(relative) ||
        /^(build|esbuild|webpack|rollup|vite|vitest|playwright|jest|tsup|babel|postcss|tailwind)(\.config)?\.(?:[cm]?[jt]s)$/i.test(basename) ||
        relative.includes('vite-env') ||
        relative.includes('env.d.ts')
      ) {
        continue;
      }
      const text = ts.sys.readFile(module.file);
      if (text?.startsWith('#!')) continue;
      const finding = createFinding({
        root,
        category: 'unused-module',
        status: 'potentially-unused',
        confidence: 'medium',
        title: `Unreferenced module ${module.relativeFile}`,
        description:
          'No entry point, HTML reference, static import, or dynamic import reaches this module. Framework file conventions and non-literal dynamic loading are excluded from this check.',
        file: module.file,
        line: 1,
        column: 1,
        symbol: module.relativeFile,
        symbolKind: 'module',
        size: {
          sourceBytes: module.bytes,
          estimatedRemovableBytes: 0,
          basis: 'Whole-module removal is not claimed until imports and external usage are verified.',
        },
        evidence: [
          {
            kind: 'no-static-reference',
            description: 'No reachable importer or entry point was found.',
            file: module.relativeFile,
            line: 1,
          },
        ],
        tags: ['module'],
      });
      findings.push(finding);
    }
  } else if (graph.entryPoints.length > 0 && graph.hasGlobImports) {
    warnings.push('Glob imports were detected; unused-module findings were skipped because reachability is dynamic.');
  }

  // Circular dependencies ------------------------------------------------------------------
  for (const cycle of graph.circularDependencies) {
    const first = cycle.files[0];
    if (!first) continue;
    const finding = createFinding({
      root,
      category: 'circular-dependency',
      status: 'unknown',
      confidence: 'high',
      title: `Circular dependency (${cycle.relativeFiles.length} modules)`,
      description: cycle.typeOnly
        ? 'These modules form a type-only import cycle. It is erased at runtime but can still complicate type architecture.'
        : 'These modules import each other through a runtime import cycle. This can cause partially initialized modules and bundler ordering problems.',
      file: first,
      line: cycle.line ?? 1,
      column: 1,
      symbol: cycle.relativeFiles.join(' → '),
      symbolKind: 'module',
      size: {},
      evidence: [
        {
          kind: 'parser',
          description: `Cycle: ${cycle.relativeFiles.join(' → ')}`,
          file: cycle.relativeFiles[0],
        },
      ],
      tags: ['dependency-graph', ...(cycle.typeOnly ? ['type-only'] : [])],
      fingerprintSuffix: hashString([...cycle.relativeFiles].sort().join('|'), 12),
    });
    findings.push(finding);
  }

  // Unreachable code -----------------------------------------------------------------------
  if (config.analysis.unreachableCode) {
    for (const [file, sourceFile] of sourceFileMap) {
      if (isTestOrStoryFile(file) || isDeclarationFile(file)) continue;
      findings.push(...findUnreachableCode(root, file, sourceFile));
    }
  }

  // Duplicate logic ------------------------------------------------------------------------
  if (config.analysis.duplicates) {
    const duplicateInput = [...sourceFileMap]
      .filter(([file]) => !isTestOrStoryFile(file) && !isDeclarationFile(file))
      .map(([file, sourceFile]) => ({
        file,
        relativeFile: toPosix(path.relative(root, file)),
        sourceFile,
      }));
    findings.push(...findDuplicateCode(root, duplicateInput));
  }

  // Type-only imports summary ----------------------------------------------------------------
  const typeOnlyImports: TypeOnlyDependencyImport[] = [...graph.typeOnlyImports];
  for (const entry of typeOnlyUsage.values()) {
    const existing = typeOnlyImports.find(
      (item) => item.file === entry.file && item.source === entry.source,
    );
    if (existing) {
      for (const name of entry.names) if (!existing.names.includes(name)) existing.names.push(name);
      if (!existing.packageName && entry.packageName) existing.packageName = entry.packageName;
    } else {
      typeOnlyImports.push(entry);
    }
  }

  const finalFindings = uniqueFindingFingerprints(findings).sort((a, b) => {
    const severityOrder: Record<Finding['severity'], number> = {
      critical: 0,
      high: 1,
      medium: 2,
      low: 3,
      info: 4,
    };
    const severity = severityOrder[a.severity] - severityOrder[b.severity];
    if (severity !== 0) return severity;
    if (a.location.relativeFile !== b.location.relativeFile) {
      return a.location.relativeFile.localeCompare(b.location.relativeFile);
    }
    return a.location.line - b.location.line;
  });

  if (dynamicPatterns.length > 0) {
    warnings.push(
      `${dynamicPatterns.length} dynamic/reflection pattern${dynamicPatterns.length === 1 ? '' : 's'} detected. Findings affected by dynamic access are marked conservatively.`,
    );
  }
  if (graph.entryPoints.length === 0) {
    warnings.push('No reachable entry point was detected; unused-module analysis was skipped.');
  }

  const moduleMap = new Map(graph.modules.map((module) => [module.file, module]));
  const normalizedModules: ModuleRecordInfo[] = [...moduleMap.values()];
  const totalLines = graph.sourceFiles.reduce((sum, file) => sum + file.lines, 0);

  return {
    findings: finalFindings,
    modules: normalizedModules,
    files: graph.sourceFiles,
    imports: graph.imports,
    externalImports: graph.externalImports,
    typeOnlyImports: dedupeTypeOnlyImports(typeOnlyImports),
    assetImports: graph.assetImports,
    dynamicPatterns,
    warnings: [...new Set(warnings)],
    entryPoints: graph.entryPoints,
    reachableFiles: graph.reachableFiles,
    circularDependencies: graph.circularDependencies,
    totalLines,
    symbolCount: records.length,
    hasDynamicModuleLoading: graph.hasDynamicModuleLoading,
    hasGlobImports: graph.hasGlobImports,
    htmlReferences: graph.htmlReferences,
  };
}

function dedupeTypeOnlyImports(entries: TypeOnlyDependencyImport[]): TypeOnlyDependencyImport[] {
  const map = new Map<string, TypeOnlyDependencyImport>();
  for (const entry of entries) {
    const key = `${entry.file}|${entry.source}`;
    const existing = map.get(key);
    if (existing) {
      for (const name of entry.names) if (!existing.names.includes(name)) existing.names.push(name);
      if (!existing.packageName && entry.packageName) existing.packageName = entry.packageName;
    } else {
      map.set(key, { ...entry, names: [...entry.names] });
    }
  }
  return [...map.values()];
}

function humanizeKind(kind: SymbolKind): string {
  switch (kind) {
    case 'function':
      return 'function';
    case 'class':
      return 'class';
    case 'method':
      return 'method';
    case 'property':
      return 'property';
    case 'interface':
      return 'interface';
    case 'type':
      return 'type';
    case 'enum':
      return 'enum';
    case 'enum-member':
      return 'enum member';
    case 'type-parameter':
      return 'type parameter';
    case 'variable':
      return 'variable';
    case 'constant':
      return 'constant';
    case 'module':
      return 'module';
    default:
      return 'declaration';
  }
}

function capitalize(value: string): string {
  return value.length > 0 ? `${value[0]?.toUpperCase() ?? ''}${value.slice(1)}` : value;
}
