import ts from 'typescript';
import type { Finding } from '../types.js';
import { createFinding } from './finding-utils.js';
import { hashString } from '../util/fs.js';

interface Candidate {
  file: string;
  relativeFile: string;
  line: number;
  column: number;
  endLine: number;
  symbol?: string;
  sourceBytes: number;
  tokenCount: number;
  hash: string;
}

interface DuplicateGroup {
  hash: string;
  tokenCount: number;
  candidates: Candidate[];
}

function normalizedTokens(text: string): { hash: string; tokenCount: number; punctuationCount: number } {
  const scanner = ts.createScanner(ts.ScriptTarget.Latest, true, ts.LanguageVariant.Standard, text);
  const tokens: string[] = [];
  let punctuationCount = 0;
  let token = scanner.scan();
  while (token !== ts.SyntaxKind.EndOfFileToken) {
    if (token === ts.SyntaxKind.Identifier) {
      tokens.push('ID');
    } else if (
      token === ts.SyntaxKind.StringLiteral ||
      token === ts.SyntaxKind.NoSubstitutionTemplateLiteral ||
      token === ts.SyntaxKind.TemplateHead ||
      token === ts.SyntaxKind.TemplateMiddle ||
      token === ts.SyntaxKind.TemplateTail
    ) {
      tokens.push('STR');
    } else if (token === ts.SyntaxKind.NumericLiteral || token === ts.SyntaxKind.BigIntLiteral) {
      tokens.push('NUM');
    } else {
      const value = scanner.getTokenText();
      if (/[^\w\s]/.test(value)) punctuationCount += 1;
      tokens.push(value);
    }
    token = scanner.scan();
  }
  return {
    hash: hashString(tokens.join(' '), 16),
    tokenCount: tokens.length,
    punctuationCount,
  };
}

function candidateName(node: ts.FunctionLikeDeclaration): string | undefined {
  if (node.name && ts.isIdentifier(node.name)) return node.name.text;
  if (ts.isConstructorDeclaration(node)) return 'constructor';
  const parent = node.parent;
  if (ts.isVariableDeclaration(parent) && ts.isIdentifier(parent.name)) return parent.name.text;
  if (ts.isPropertyDeclaration(parent) && ts.isIdentifier(parent.name)) return parent.name.text;
  return undefined;
}

function collectCandidates(
  file: string,
  relativeFile: string,
  sourceFile: ts.SourceFile,
): Array<{ candidate: Candidate; node: ts.Node }> {
  const candidates: Array<{ candidate: Candidate; node: ts.Node }> = [];

  const visit = (node: ts.Node): void => {
    const isCandidate =
      (ts.isFunctionDeclaration(node) ||
        ts.isMethodDeclaration(node) ||
        ts.isConstructorDeclaration(node) ||
        ts.isGetAccessorDeclaration(node) ||
        ts.isSetAccessorDeclaration(node) ||
        ts.isArrowFunction(node) ||
        ts.isFunctionExpression(node)) &&
      Boolean(node.body);
    if (isCandidate && node.body) {
      const body = node.body.getText(sourceFile);
      const normalized = normalizedTokens(body);
      if (normalized.tokenCount >= 50 && normalized.punctuationCount >= 12) {
        const start = sourceFile.getLineAndCharacterOfPosition(node.getStart(sourceFile));
        const end = sourceFile.getLineAndCharacterOfPosition(Math.max(node.getStart(sourceFile), node.getEnd() - 1));
        const name = candidateName(node);
        candidates.push({
          node,
          candidate: {
            file,
            relativeFile,
            line: start.line + 1,
            column: start.character + 1,
            endLine: end.line + 1,
            ...(name ? { symbol: name } : {}),
            sourceBytes: node.getEnd() - node.getStart(sourceFile),
            tokenCount: normalized.tokenCount,
            hash: normalized.hash,
          },
        });
      }
    }
    ts.forEachChild(node, visit);
  };
  visit(sourceFile);
  return candidates;
}

/** Token-normalized duplicate logic detection. Advisory only. */
export function findDuplicateCode(
  root: string,
  files: Array<{ file: string; relativeFile: string; sourceFile: ts.SourceFile }>,
  maxGroups = 30,
): Finding[] {
  const groups = new Map<string, DuplicateGroup>();
  for (const entry of files) {
    for (const { candidate } of collectCandidates(entry.file, entry.relativeFile, entry.sourceFile)) {
      const existing = groups.get(candidate.hash);
      if (existing) {
        // Avoid reporting two identical one-line function shims repeatedly.
        existing.candidates.push(candidate);
      } else {
        groups.set(candidate.hash, {
          hash: candidate.hash,
          tokenCount: candidate.tokenCount,
          candidates: [candidate],
        });
      }
    }
  }

  const findings: Finding[] = [];
  for (const group of [...groups.values()].sort((a, b) => b.tokenCount - a.tokenCount)) {
    if (findings.length >= maxGroups) break;
    if (group.candidates.length < 2) continue;
    const uniqueLocations = new Set(
      group.candidates.map((candidate) => `${candidate.relativeFile}:${candidate.line}`),
    );
    if (uniqueLocations.size < 2) continue;
    const first = group.candidates[0];
    if (!first) continue;
    findings.push(
      createFinding({
        root,
        category: 'duplicate-code',
        status: 'unknown',
        confidence: 'medium',
        title: `${group.candidates.length} functions share identical normalized logic`,
        description:
          'Bodies match after normalizing identifiers and literals. This is an advisory refactor opportunity; framework boilerplate can be intentionally duplicated.',
        file: first.file,
        line: first.line,
        column: first.column,
        endLine: first.endLine,
        ...(first.symbol ? { symbol: first.symbol } : {}),
        symbolKind: first.symbol ? 'function' : 'unknown',
        duplicate: {
          groupId: `dup_${group.hash}`,
          occurrences: group.candidates.slice(0, 20).map((candidate) => ({
            file: candidate.file,
            relativeFile: candidate.relativeFile,
            line: candidate.line,
            ...(candidate.symbol ? { symbol: candidate.symbol } : {}),
          })),
          normalizedHash: group.hash,
          tokenCount: group.tokenCount,
        },
        size: {
          sourceBytes: first.sourceBytes,
          basis: 'Size of the first occurrence; duplicates are overlapping candidates.',
        },
        evidence: [
          {
            kind: 'parser',
            description: `${group.tokenCount} normalized tokens matched across ${group.candidates.length} functions.`,
          },
        ],
        tags: ['advisory', 'refactor'],
        fingerprintSuffix: group.hash,
      }),
    );
  }
  return findings;
}
