import path from 'node:path';
import { existsSync } from 'node:fs';
import { createInterface } from 'node:readline/promises';
import { stdin, stderr } from 'node:process';
import type { Browser, BrowserContext, CDPSession, Page } from 'playwright';
import type {
  ResolvedCodeUsageMapConfig,
  RouteInput,
  RuntimeAction,
  RuntimeCollectionOptions,
  RuntimeCollectionResult,
  RuntimeScenario,
} from '../types.js';
import {
  installBrowserCollector,
  type BrowserCollectorSnapshot,
} from './browser-collector.js';
import type {
  RuntimeCoverage,
  RuntimeCoverageFunction,
  RuntimeRouteVisit,
  RuntimeScriptCoverage,
  RuntimeSession,
} from './types.js';
import { saveRuntimeSession } from './store.js';
import { hashString, throwIfAborted } from '../util/fs.js';

export interface CollectRuntimeInput {
  root: string;
  config: ResolvedCodeUsageMapConfig;
  options?: RuntimeCollectionOptions;
  persist?: boolean;
}

export interface CollectRuntimeOutput {
  sessions: RuntimeSession[];
  result: RuntimeCollectionResult;
}

interface ResolvedRoute {
  id: string;
  name: string;
  path: string;
  url: string;
}

interface CoverageRawEntry {
  scriptId: string;
  url: string;
  functions: Array<{
    functionName: string;
    ranges: Array<{ startOffset: number; endOffset: number; count: number }>;
    isBlockCoverage: boolean;
  }>;
}

interface CollectorRuntimeApi {
  take(): BrowserCollectorSnapshot;
  setRoute(name?: string): void;
}

function normalizeBaseUrl(value: string): URL {
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    throw new Error(`Runtime base URL must be absolute: ${value}`);
  }
  if (url.protocol !== 'http:' && url.protocol !== 'https:') {
    throw new Error(`Runtime base URL must use http or https: ${value}`);
  }
  return url;
}

function canonicalRouteId(pathname: string, basePath: string): string {
  let value = pathname || '/';
  if (!value.startsWith('/')) value = `/${value}`;
  const normalizedBase = basePath.replace(/\/+$/, '');
  if (normalizedBase && normalizedBase !== '/') {
    if (value === normalizedBase) value = '/';
    else if (value.startsWith(`${normalizedBase}/`)) value = value.slice(normalizedBase.length);
  }
  if (value.length > 1) value = value.replace(/\/+$/, '');
  return value || '/';
}

function routePathFromUrl(url: URL): string {
  if (/^#\//.test(url.hash)) return url.hash.slice(1) || '/';
  return canonicalRouteId(url.pathname, '');
}

function resolveRoutes(
  baseUrl: URL,
  inputs: RouteInput[],
  basePath: string,
): ResolvedRoute[] {
  const basePathname = baseUrl.pathname.endsWith('/') ? baseUrl.pathname : `${baseUrl.pathname}/`;
  const routes: ResolvedRoute[] = [];
  for (const input of inputs) {
    let pathValue: string | undefined;
    let urlValue: string | undefined;
    let nameValue: string | undefined;
    if (typeof input === 'string') {
      if (/^https?:\/\//i.test(input)) urlValue = input;
      else pathValue = input;
    } else {
      pathValue = input.path;
      urlValue = input.url;
      nameValue = input.name;
    }
    if (!pathValue && !urlValue) continue;
    let target: URL;
    if (urlValue) {
      target = new URL(urlValue);
    } else {
      const cleanPath = (pathValue ?? '/').trim();
      if (/^#\//.test(cleanPath)) {
        target = new URL(baseUrl.toString());
        target.hash = cleanPath;
      } else {
        const relative = cleanPath.replace(/^\/+/, '');
        target = new URL(relative, `${baseUrl.origin}${basePathname}`);
      }
    }
    const routePath = pathValue ?? routePathFromUrl(target);
    const id = canonicalRouteId(
      /^#\//.test(target.hash) ? target.hash.slice(1) : routePath.startsWith('/') ? routePath : routePathFromUrl(target),
      basePath,
    );
    routes.push({
      id,
      name: nameValue ?? id,
      path: routePath,
      url: target.href,
    });
  }
  return routes;
}

class ChromiumCoverage {
  readonly available = true;
  private client?: CDPSession;
  private active = false;
  private scriptUrls = new Map<string, string>();
  private scriptSources = new Map<string, string | undefined>();
  private warnings: string[] = [];
  private browserName = 'chromium';

  static async create(
    context: BrowserContext,
    page: Page,
    browserName: string,
  ): Promise<ChromiumCoverage | undefined> {
    if (browserName !== 'chromium') return undefined;
    try {
      const client = await context.newCDPSession(page);
      const coverage = new ChromiumCoverage();
      coverage.client = client;
      client.on('Debugger.scriptParsed', (event: unknown) => {
        const parsed = event as { scriptId?: string; url?: string };
        if (parsed.scriptId) coverage.scriptUrls.set(parsed.scriptId, parsed.url ?? '');
      });
      await client.send('Profiler.enable');
      await client.send('Debugger.enable');
      return coverage;
    } catch {
      return undefined;
    }
  }

  async start(): Promise<boolean> {
    if (!this.client) return false;
    if (this.active) await this.stop();
    try {
      await this.client.send('Profiler.startPreciseCoverage', {
        callCount: true,
        detailed: true,
      });
      this.active = true;
      return true;
    } catch (error) {
      this.warnings.push(
        `Precise coverage could not start: ${error instanceof Error ? error.message : String(error)}`,
      );
      return false;
    }
  }

  async stop(): Promise<void> {
    if (!this.client || !this.active) return;
    try {
      await this.client.send('Profiler.stopPreciseCoverage');
    } catch {
      // Coverage may already be stopped.
    }
    this.active = false;
  }

  async take(): Promise<RuntimeCoverage> {
    const empty: RuntimeCoverage = {
      available: false,
      browser: this.browserName,
      functions: [],
      scripts: [],
      truncated: false,
      note: this.warnings.join(' '),
    };
    if (!this.client || !this.active) return empty;
    let raw: { result: CoverageRawEntry[] };
    try {
      raw = (await this.client.send('Profiler.takePreciseCoverage')) as unknown as {
        result: CoverageRawEntry[];
      };
    } catch (error) {
      this.warnings.push(
        `Precise coverage could not be read: ${error instanceof Error ? error.message : String(error)}`,
      );
      await this.stop();
      return { ...empty, note: this.warnings.join(' ') };
    }
    await this.stop();

    const functions: RuntimeCoverageFunction[] = [];
    const scripts: RuntimeScriptCoverage[] = [];
    let truncated = false;
    const MAX_FUNCTIONS = 50_000;

    for (const entry of raw.result) {
      if (!entry.url || entry.url.startsWith('data:') || entry.url.startsWith('blob:')) continue;
      if (this.scriptUrls.get(entry.scriptId) === undefined) {
        this.scriptUrls.set(entry.scriptId, entry.url);
      }
      let totalFunctions = 0;
      let executedFunctions = 0;
      let totalFunctionBytes = 0;
      let executedFunctionBytes = 0;
      let text: string | undefined;
      const needsText = entry.functions.some((fn) => fn.ranges.some((range) => range.count > 0));
      if (needsText) {
        text = await this.getScriptSource(entry.scriptId);
      }
      const lineStarts = text ? buildLineStarts(text) : undefined;
      for (const fn of entry.functions) {
        const first = fn.ranges[0];
        if (!first) continue;
        totalFunctions += 1;
        const spanBytes = Math.max(0, first.endOffset - first.startOffset);
        totalFunctionBytes += spanBytes;
        const maxCount = fn.ranges.reduce((max, range) => Math.max(max, range.count), 0);
        if (maxCount <= 0) continue;
        executedFunctions += 1;
        executedFunctionBytes += spanBytes;
        if (!lineStarts) continue;
        if (functions.length >= MAX_FUNCTIONS) {
          truncated = true;
          continue;
        }
        const start = offsetToPosition(lineStarts, first.startOffset);
        const end = offsetToPosition(lineStarts, first.endOffset);
        functions.push({
          url: entry.url,
          functionName: fn.functionName,
          startOffset: first.startOffset,
          endOffset: first.endOffset,
          startLine: start.line,
          startColumn: start.column,
          endLine: end.line,
          endColumn: end.column,
          bytes: spanBytes,
          count: maxCount,
        });
      }
      if (totalFunctions > 0) {
        scripts.push({
          url: entry.url,
          totalFunctions,
          executedFunctions,
          totalFunctionBytes,
          executedFunctionBytes,
        });
      }
    }

    return {
      available: true,
      browser: this.browserName,
      functions,
      scripts,
      truncated,
      ...(this.warnings.length > 0 ? { note: this.warnings.join(' ') } : {}),
    };
  }

  private async getScriptSource(scriptId: string): Promise<string | undefined> {
    if (this.scriptSources.has(scriptId)) return this.scriptSources.get(scriptId);
    if (!this.client) return undefined;
    try {
      const result = (await this.client.send('Debugger.getScriptSource', { scriptId })) as unknown as {
        scriptSource: string;
      };
      this.scriptSources.set(scriptId, result.scriptSource);
      return result.scriptSource;
    } catch {
      this.scriptSources.set(scriptId, undefined);
      return undefined;
    }
  }

  async close(): Promise<void> {
    await this.stop();
    try {
      await this.client?.detach();
    } catch {
      // Session may already be detached.
    }
    this.client = undefined;
  }
}

function buildLineStarts(text: string): number[] {
  const starts = [0];
  for (let index = 0; index < text.length; index += 1) {
    if (text.charCodeAt(index) === 10) starts.push(index + 1);
  }
  return starts;
}

function offsetToPosition(lineStarts: number[], offset: number): { line: number; column: number } {
  let low = 0;
  let high = lineStarts.length - 1;
  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    if ((lineStarts[mid] ?? 0) <= offset) low = mid + 1;
    else high = mid - 1;
  }
  const lineIndex = Math.max(0, high);
  return {
    line: lineIndex + 1,
    column: offset - (lineStarts[lineIndex] ?? 0) + 1,
  };
}

async function launchBrowser(
  browserName: 'chromium' | 'firefox' | 'webkit',
  headless: boolean,
): Promise<Browser> {
  let playwrightModule: typeof import('playwright');
  try {
    playwrightModule = await import('playwright');
  } catch {
    throw new Error(
      'Runtime collection requires Playwright. Install it with "npm i -D playwright" and then "npx playwright install chromium".',
    );
  }
  const browserType = playwrightModule[browserName];
  const options = { headless };
  try {
    return await browserType.launch(options);
  } catch (error) {
    if (browserName === 'chromium') {
      for (const channel of ['chrome', 'msedge'] as const) {
        try {
          return await browserType.launch({ headless, channel });
        } catch {
          // Try the next installed browser channel.
        }
      }
    }
    const message = error instanceof Error ? error.message : String(error);
    throw new Error(
      `Failed to launch ${browserName}: ${message}\nInstall browsers with "npx playwright install ${browserName}" or run with --interactive using an installed browser.`,
    );
  }
}

function findScenario(
  scenarios: RuntimeScenario[],
  route: ResolvedRoute,
): RuntimeScenario | undefined {
  return scenarios.find((scenario) => {
    if (scenario.route === '*') return true;
    return (
      scenario.route === route.id ||
      scenario.route === route.path ||
      scenario.route === route.name ||
      scenario.route === route.url
    );
  });
}

async function runActions(
  page: Page,
  actions: RuntimeAction[],
  route: ResolvedRoute,
  scenario: RuntimeScenario | undefined,
  timeoutMs: number,
  settleMs: number,
  warnings: string[],
): Promise<string[]> {
  const performed: string[] = [];
  for (const action of actions) {
    const timeout = action.timeoutMs ?? timeoutMs;
    const selector = action.selector;
    try {
      switch (action.type) {
        case 'click':
          if (!selector) throw new Error('click requires a selector');
          await page.locator(selector).first().click({ timeout });
          break;
        case 'hover':
          if (!selector) throw new Error('hover requires a selector');
          await page.locator(selector).first().hover({ timeout });
          break;
        case 'fill':
          if (!selector) throw new Error('fill requires a selector');
          await page.locator(selector).first().fill(action.value ?? '', { timeout });
          break;
        case 'press':
          if (selector) await page.locator(selector).first().press(action.key ?? 'Enter', { timeout });
          else await page.keyboard.press(action.key ?? 'Enter');
          break;
        case 'waitForSelector':
          if (!selector) throw new Error('waitForSelector requires a selector');
          await page.locator(selector).first().waitFor({ state: 'visible', timeout });
          break;
        case 'wait':
          await page.waitForTimeout(action.ms ?? settleMs);
          break;
        case 'select':
          if (!selector) throw new Error('select requires a selector');
          await page.locator(selector).first().selectOption(action.value ?? '', { timeout });
          break;
      }
      performed.push(`${action.type}${selector ? ` ${selector}` : ''}`);
      if (action.type !== 'wait' && action.ms) await page.waitForTimeout(action.ms);
      else await page.waitForTimeout(Math.min(200, settleMs));
    } catch (error) {
      const message = `Scenario action "${action.type}${selector ? ` ${selector}` : ''}" failed on ${route.id}: ${error instanceof Error ? error.message : String(error)}`;
      warnings.push(message);
      if (scenario?.strict) throw new Error(message);
    }
  }
  return performed;
}

async function takeSnapshot(
  page: Page,
  basePath: string,
  warnings: string[],
): Promise<BrowserCollectorSnapshot> {
  try {
    const snapshot = await page.evaluate(() => {
      const globalWindow = window as unknown as { __codeUsageMapRuntime?: CollectorRuntimeApi };
      return globalWindow.__codeUsageMapRuntime?.take() ?? null;
    });
    if (!snapshot) {
      warnings.push('The in-page collector was not available. CSS/DOM runtime data is incomplete.');
      return {
        href: page.url(),
        timeOrigin: Date.now(),
        routes: [],
        warnings: ['Collector unavailable.'],
      };
    }
    return {
      ...snapshot,
      routes: snapshot.routes.map((route) => ({
        ...route,
        route: canonicalRouteId(route.route, basePath),
      })),
    };
  } catch (error) {
    warnings.push(`Runtime snapshot failed: ${error instanceof Error ? error.message : String(error)}`);
    return {
      href: page.url(),
      timeOrigin: Date.now(),
      routes: [],
      warnings: [error instanceof Error ? error.message : String(error)],
    };
  }
}

async function tryLinkNavigation(
  page: Page,
  route: ResolvedRoute,
  timeoutMs: number,
): Promise<boolean> {
  try {
    const target = new URL(route.url);
    const index = await page.evaluate((targetUrl) => {
      const targetParsed = new URL(targetUrl);
      const anchors = Array.from(document.querySelectorAll('a[href]'));
      for (let index = 0; index < anchors.length; index += 1) {
        const anchor = anchors[index];
        if (!(anchor instanceof HTMLAnchorElement)) continue;
        let href: URL;
        try {
          href = new URL(anchor.href, document.baseURI);
        } catch {
          continue;
        }
        if (href.origin !== targetParsed.origin) continue;
        if (href.pathname !== targetParsed.pathname) continue;
        if (targetParsed.hash && href.hash !== targetParsed.hash) continue;
        return index;
      }
      return -1;
    }, target.href);
    if (index < 0) return false;
    await page.locator('a[href]').nth(index).click({ timeout: Math.min(timeoutMs, 10_000) });
    try {
      await page.waitForURL(
        (url) =>
          url.pathname === target.pathname &&
          (!target.hash || url.hash === target.hash),
        { timeout: Math.min(timeoutMs, 10_000) },
      );
    } catch {
      // A client-side router can update the URL after the click; settle below.
    }
    return true;
  } catch {
    return false;
  }
}

async function waitForEnter(signal?: AbortSignal): Promise<void> {
  const readline = createInterface({ input: stdin, output: stderr });
  const aborted = new Promise<void>((resolve) => {
    if (!signal) return;
    signal.addEventListener('abort', () => {
      readline.close();
      resolve();
    }, { once: true });
  });
  try {
    await Promise.race([
      readline.question('Interactive runtime analysis is active. Navigate the app, then press Enter to finish. '),
      aborted,
    ]);
  } finally {
    readline.close();
  }
}

/**
 * Collects runtime usage with Playwright. Automated mode visits configured
 * routes and can preserve SPA state through same-origin link clicks. Interactive
 * mode requires a TTY and records route-scoped CSS/DOM plus session-level JS
 * coverage.
 */
export async function collectRuntime(input: CollectRuntimeInput): Promise<CollectRuntimeOutput> {
  const options = input.options ?? {};
  const runtime = input.config.runtime;
  const baseUrlValue = options.baseUrl ?? runtime.baseUrl;
  if (!baseUrlValue) {
    throw new Error(
      'Runtime collection needs a base URL. Pass --url http://localhost:3000, set runtime.baseUrl, or let the CLI serve an existing build directory.',
    );
  }
  const baseUrl = normalizeBaseUrl(baseUrlValue);
  const basePath = baseUrl.pathname;
  const browserName = options.browser ?? runtime.browser;
  const interactive = options.interactive ?? runtime.interactive;
  const headless = interactive ? false : (options.headless ?? runtime.headless);
  if (interactive && !stdin.isTTY) {
    throw new Error('Interactive mode requires a TTY. Use automated --routes for CI.');
  }
  throwIfAborted(options.signal);

  const routeInputs = options.routes ?? runtime.routes;
  const configuredRoutes = resolveRoutes(
    baseUrl,
    routeInputs.length > 0 ? routeInputs : ['/'],
    basePath,
  );

  options.onProgress?.({
    phase: 'runtime',
    message: interactive
      ? `Opening ${baseUrl.href} for interactive collection.`
      : `Opening ${baseUrl.href} and visiting ${configuredRoutes.length} route${configuredRoutes.length === 1 ? '' : 's'}.`,
  });

  const browser = await launchBrowser(browserName, headless);
  let context: BrowserContext | undefined;
  let page: Page | undefined;
  let coverage: ChromiumCoverage | undefined;
  const visits: RuntimeRouteVisit[] = [];
  const sessionWarnings: string[] = [];
  const startedAt = new Date().toISOString();
  const sessionId = `rt_${Date.now()}_${hashString(Math.random().toString(), 6)}`;
  let userAgent: string | undefined;

  try {
    const storageState = runtime.storageState
      ? path.isAbsolute(runtime.storageState)
        ? runtime.storageState
        : path.resolve(input.root, runtime.storageState)
      : undefined;
    context = await browser.newContext({
      viewport: runtime.viewport,
      ignoreHTTPSErrors: runtime.ignoreHTTPSErrors,
      ...(storageState && existsSync(storageState) ? { storageState } : {}),
    });
    page = await context.newPage();
    page.setDefaultTimeout(runtime.timeoutMs);
    userAgent = await page.evaluate(() => navigator.userAgent).catch(() => undefined);

    const collectorSource = `(${installBrowserCollector.toString()})(${JSON.stringify({
      snapshotIntervalMs: runtime.snapshotIntervalMs,
      collectCss: runtime.collectCss,
      collectNetwork: runtime.collectNetwork,
    })});`;
    await page.addInitScript({ content: collectorSource });

    page.on('pageerror', (error) => {
      if (sessionWarnings.length < 30) {
        sessionWarnings.push(`Page error: ${String(error.message).slice(0, 500)}`);
      }
    });

    if (browserName !== 'chromium') {
      sessionWarnings.push(
        `Precise JavaScript coverage is Chromium-only. ${browserName} collection includes script loading, route CSS/DOM and resources but not function coverage.`,
      );
    } else if (runtime.collectCoverage) {
      coverage = await ChromiumCoverage.create(context, page, browserName);
      if (!coverage) {
        sessionWarnings.push('Unable to attach Chromium precise coverage; route analysis will use script/resource loading only.');
      }
    }

    if (interactive) {
      if (coverage) await coverage.start();
      await page.goto(baseUrl.href, {
        waitUntil: runtime.waitUntil,
        timeout: runtime.timeoutMs,
      });
      await page.waitForTimeout(runtime.settleMs);
      options.onProgress?.({
        phase: 'runtime',
        message: 'Interactive browser is ready. Navigate routes and interactions, then press Enter in the terminal.',
      });
      throwIfAborted(options.signal);
      await waitForEnter(options.signal);
      throwIfAborted(options.signal);
      await page.waitForTimeout(runtime.settleMs);
      const snapshot = await takeSnapshot(page, basePath, sessionWarnings);
      const sessionCoverage = coverage ? await coverage.take() : undefined;
      const routeSnapshots =
        snapshot.routes.length > 0
          ? snapshot.routes
          : [
              {
                route: canonicalRouteId(new URL(page.url()).pathname, basePath),
                selectors: [],
                dom: { classes: [], ids: [], tags: [] },
                stylesheets: [],
                scripts: [],
                resources: [],
                interactions: [],
                dynamicCss: [],
                capturedAt: new Date().toISOString(),
              },
            ];
      const now = new Date().toISOString();
      for (const routeSnapshot of routeSnapshots) {
        visits.push({
          route: routeSnapshot.route,
          name: routeSnapshot.route,
          path: routeSnapshot.route,
          url: page.url(),
          navigation: 'interactive',
          startedAt,
          finishedAt: now,
          durationMs: Date.parse(now) - Date.parse(startedAt),
          snapshot: { ...snapshot, routes: [routeSnapshot] },
          actions: [],
          warnings: [...snapshot.warnings],
        });
      }
      const session: RuntimeSession = {
        schemaVersion: 1,
        id: sessionId,
        startedAt,
        finishedAt: now,
        baseUrl: baseUrl.href,
        browser: browserName,
        headless,
        interactive: true,
        navigationMode: runtime.navigation,
        viewport: runtime.viewport,
        ...(userAgent ? { userAgent } : {}),
        visits,
        ...(sessionCoverage ? { coverageSession: sessionCoverage } : {}),
        warnings: [...new Set([...sessionWarnings, ...snapshot.warnings])],
      };
      if (input.persist !== false) saveRuntimeSession(input.root, session);
      for (const visit of visits) {
        options.onProgress?.({
          phase: 'runtime',
          message: `Captured route ${visit.route}${sessionCoverage?.available ? ' (session-level JS coverage)' : ''}.`,
        });
      }
      return {
        sessions: [session],
        result: {
          sessionIds: [session.id],
          routes: visits.map((visit) => visit.route),
          baseUrl: baseUrl.href,
        },
      };
    }

    for (let routeIndex = 0; routeIndex < configuredRoutes.length; routeIndex += 1) {
      throwIfAborted(options.signal);
      const route = configuredRoutes[routeIndex];
      if (!route) continue;
      const started = new Date();
      const visitWarnings: string[] = [];
      let navigation: RuntimeRouteVisit['navigation'] = routeIndex === 0 ? 'initial' : 'goto';
      if (coverage) {
        const startedCoverage = await coverage.start();
        if (!startedCoverage) visitWarnings.push('Coverage did not start for this route.');
      }

      try {
        if (routeIndex === 0) {
          await page.goto(route.url, {
            waitUntil: runtime.waitUntil,
            timeout: runtime.timeoutMs,
          });
        } else if (runtime.navigation === 'auto') {
          const linked = await tryLinkNavigation(page, route, runtime.timeoutMs);
          if (linked) {
            navigation = 'link';
          } else {
            await page.goto(route.url, {
              waitUntil: runtime.waitUntil,
              timeout: runtime.timeoutMs,
            });
          }
        } else {
          await page.goto(route.url, {
            waitUntil: runtime.waitUntil,
            timeout: runtime.timeoutMs,
          });
        }
        await page.waitForTimeout(runtime.settleMs);
        const scenario = findScenario(runtime.scenarios, route);
        const actions = scenario
          ? await runActions(
              page,
              scenario.actions,
              route,
              scenario,
              runtime.timeoutMs,
              runtime.settleMs,
              visitWarnings,
            )
          : [];
        await page.waitForTimeout(runtime.settleMs);
        const routeCoverage = coverage ? await coverage.take() : undefined;
        const snapshot = await takeSnapshot(page, basePath, visitWarnings);
        const matchingRoutes = snapshot.routes.filter((item) => item.route === route.id);
        const selectedRoutes =
          matchingRoutes.length > 0
            ? matchingRoutes
            : snapshot.routes.length > 0
              ? [snapshot.routes[snapshot.routes.length - 1] as (typeof snapshot.routes)[number]]
              : [];
        const visitSnapshot = { ...snapshot, routes: selectedRoutes };
        const canonical = route.id;
        const finished = new Date();
        visits.push({
          route: canonical,
          name: route.name,
          path: route.id,
          url: page.url(),
          navigation,
          startedAt: started.toISOString(),
          finishedAt: finished.toISOString(),
          durationMs: finished.getTime() - started.getTime(),
          snapshot: visitSnapshot,
          ...(routeCoverage ? { coverage: routeCoverage } : {}),
          actions,
          warnings: [...visitWarnings, ...snapshot.warnings],
        });
        options.onProgress?.({
          phase: 'runtime',
          message: `Captured ${canonical} (${navigation}${routeCoverage?.available ? `, ${routeCoverage.functions.length} executed function records` : ', no function coverage'}).`,
        });
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        visitWarnings.push(`Route ${route.id} failed: ${message}`);
        sessionWarnings.push(`Route ${route.id} failed: ${message}`);
        // Capture whatever the browser is showing so a broken route does not
        // discard the rest of the session.
        const routeCoverage = coverage ? await coverage.take() : undefined;
        const snapshot = await takeSnapshot(page, basePath, visitWarnings);
        const finished = new Date();
        visits.push({
          route: route.id,
          name: route.name,
          path: route.id,
          url: page.url(),
          navigation,
          startedAt: started.toISOString(),
          finishedAt: finished.toISOString(),
          durationMs: finished.getTime() - started.getTime(),
          snapshot,
          ...(routeCoverage ? { coverage: routeCoverage } : {}),
          actions: [],
          warnings: [...visitWarnings, ...snapshot.warnings],
        });
        options.onProgress?.({
          phase: 'runtime',
          message: `Route ${route.id} reported an error but was captured for diagnostics.`,
        });
      }
    }

    if (coverage) await coverage.close();
    const finishedAt = new Date().toISOString();
    const session: RuntimeSession = {
      schemaVersion: 1,
      id: sessionId,
      startedAt,
      finishedAt,
      baseUrl: baseUrl.href,
      browser: browserName,
      headless,
      interactive: false,
      navigationMode: runtime.navigation,
      viewport: runtime.viewport,
      ...(userAgent ? { userAgent } : {}),
      visits,
      warnings: [...new Set([...sessionWarnings, ...visits.flatMap((visit) => visit.warnings)])],
    };
    if (input.persist !== false) saveRuntimeSession(input.root, session);
    return {
      sessions: [session],
      result: {
        sessionIds: [session.id],
        routes: visits.map((visit) => visit.route),
        baseUrl: baseUrl.href,
      },
    };
  } finally {
    await coverage?.close().catch(() => undefined);
    await context?.close().catch(() => undefined);
    await browser.close().catch(() => undefined);
  }
}

export function routeInputsFromPaths(paths: string[]): RouteInput[] {
  return paths.map((value) => (value.startsWith('http') ? { url: value } : { path: value }));
}
