import path from 'node:path';
import { copyFileSync, existsSync, readFileSync, writeFileSync } from 'node:fs';
import type { Finding, ResolvedCodeUsageMapConfig } from '../types.js';
import { ensureDir, relativePosix, toPosix, writeJsonFile, writeTextFile } from '../util/fs.js';

export interface PlannedFix {
  findingId: string;
  file: string;
  relativeFile: string;
  startOffset: number;
  endOffset: number;
  replacement: string;
  expectedText: string;
  description: string;
  startLine: number;
  endLine: number;
}

export interface FixPreview {
  fixes: PlannedFix[];
  skipped: Array<{ findingId: string; reason: string }>;
  patch: string;
  patchPath?: string;
}

export interface FixApplyResult extends FixPreview {
  applied: boolean;
  backupDir?: string;
  changedFiles: string[];
  manifestPath?: string;
}

function lineAt(text: string, offset: number): number {
  let line = 1;
  for (let index = 0; index < offset && index < text.length; index += 1) {
    if (text.charCodeAt(index) === 10) line += 1;
  }
  return line;
}

function makePatch(fixes: PlannedFix[], root: string): string {
  const chunks: string[] = [];
  for (const fix of fixes) {
    const relative = toPosix(path.relative(root, fix.file));
    const oldLines = fix.expectedText.split(/\r\n|\r|\n/);
    const newLines = fix.replacement.split(/\r\n|\r|\n/);
    const header = `--- a/${relative}\n+++ b/${relative}\n@@ -${fix.startLine},${oldLines.length} +${fix.startLine},${newLines.length} @@\n`;
    const removed = oldLines.map((line) => `-${line}`).join('\n');
    const added = newLines.map((line) => `+${line}`).join('\n');
    chunks.push(`${header}${removed}\n${added}`);
  }
  return chunks.length > 0 ? `${chunks.join('\n')}\n` : '';
}

/** Builds a preview for safe, statically-verified fixes only. */
export function buildFixPreview(options: {
  root: string;
  config: ResolvedCodeUsageMapConfig;
  findings: Finding[];
  findingIds?: string[];
  writePatch?: boolean;
}): FixPreview {
  const { root, findings } = options;
  const selected = options.findingIds?.length
    ? findings.filter((finding) => options.findingIds?.includes(finding.id))
    : findings;
  const fixes: PlannedFix[] = [];
  const skipped: Array<{ findingId: string; reason: string }> = [];
  const rangesByFile = new Map<string, Array<{ start: number; end: number }>>();

  for (const finding of selected) {
    if (!finding.fix) {
      if (options.findingIds?.includes(finding.id)) {
        skipped.push({ findingId: finding.id, reason: 'No automatic safe fix is available for this finding.' });
      }
      continue;
    }
    if (!finding.fix.safe) {
      skipped.push({ findingId: finding.id, reason: 'The available fix is marked for manual review.' });
      continue;
    }
    const file = finding.location.file;
    let content: string;
    try {
      content = readFileSync(file, 'utf8');
    } catch {
      skipped.push({ findingId: finding.id, reason: 'Source file is no longer readable.' });
      continue;
    }
    const fix = finding.fix;
    if (content.slice(fix.startOffset, fix.endOffset) !== fix.expectedText) {
      skipped.push({
        findingId: finding.id,
        reason: 'File content changed since analysis; refusing to apply a stale edit.',
      });
      continue;
    }
    const ranges = rangesByFile.get(file) ?? [];
    if (ranges.some((range) => fix.startOffset < range.end && fix.endOffset > range.start)) {
      skipped.push({ findingId: finding.id, reason: 'The edit overlaps another planned fix.' });
      continue;
    }
    ranges.push({ start: fix.startOffset, end: fix.endOffset });
    rangesByFile.set(file, ranges);
    fixes.push({
      findingId: finding.id,
      file,
      relativeFile: relativePosix(root, file),
      startOffset: fix.startOffset,
      endOffset: fix.endOffset,
      replacement: fix.replacement ?? '',
      expectedText: fix.expectedText,
      description: fix.description,
      startLine: lineAt(content, fix.startOffset),
      endLine: lineAt(content, fix.endOffset),
    });
  }

  fixes.sort((a, b) => (a.relativeFile === b.relativeFile ? a.startOffset - b.startOffset : a.relativeFile.localeCompare(b.relativeFile)));
  const patch = makePatch(fixes, root);
  let patchPath: string | undefined;
  if (options.writePatch && patch) {
    patchPath = path.join(options.config.output, 'autofix.patch');
    writeTextFile(patchPath, patch);
  }
  return { fixes, skipped, patch, ...(patchPath ? { patchPath } : {}) };
}

/** Applies a previewed patch set with backups and a revert manifest. */
export function applyFixPreview(options: {
  root: string;
  config: ResolvedCodeUsageMapConfig;
  preview: FixPreview;
}): FixApplyResult {
  const { root, config, preview } = options;
  if (preview.fixes.length === 0) {
    return { ...preview, applied: false, changedFiles: [] };
  }
  const timestamp = new Date().toISOString().replace(/[^0-9A-Za-z]/g, '-');
  const backupDir = path.join(config.output, '.autofix-backups', timestamp);
  ensureDir(backupDir);
  const files = [...new Set(preview.fixes.map((fix) => fix.file))];
  const manifestFiles: Array<{ file: string; relativeFile: string; backup: string }> = [];
  const contents = new Map<string, string>();
  for (const file of files) {
    const relative = relativePosix(root, file);
    const backup = path.join(backupDir, relative);
    ensureDir(path.dirname(backup));
    copyFileSync(file, backup);
    manifestFiles.push({ file, relativeFile: relative, backup });
    contents.set(file, readFileSync(file, 'utf8'));
  }
  for (const [file, original] of contents) {
    const edits = preview.fixes.filter((fix) => fix.file === file).sort((a, b) => b.startOffset - a.startOffset);
    let updated = original;
    for (const edit of edits) {
      updated = `${updated.slice(0, edit.startOffset)}${edit.replacement}${updated.slice(edit.endOffset)}`;
    }
    writeFileSync(file, updated, 'utf8');
  }
  const manifestPath = path.join(backupDir, 'manifest.json');
  writeJsonFile(manifestPath, {
    createdAt: new Date().toISOString(),
    root,
    files: manifestFiles,
    findings: preview.fixes.map((fix) => fix.findingId),
  });
  writeJsonFile(path.join(config.output, '.autofix-latest.json'), {
    backupDir,
    manifestPath,
    createdAt: new Date().toISOString(),
  });
  return {
    ...preview,
    applied: true,
    backupDir,
    changedFiles: files.map((file) => relativePosix(root, file)),
    manifestPath,
  };
}

export interface RevertResult {
  reverted: boolean;
  files: string[];
  backupDir?: string;
  reason?: string;
}

/** Restores the most recent autofix backup. */
export function revertLatestFix(outputDir: string): RevertResult {
  const pointer = path.join(outputDir, '.autofix-latest.json');
  if (!existsSync(pointer)) {
    return { reverted: false, files: [], reason: 'No autofix backup pointer was found.' };
  }
  try {
    const latest = JSON.parse(readFileSync(pointer, 'utf8')) as {
      backupDir?: string;
      manifestPath?: string;
    };
    if (!latest.manifestPath || !existsSync(latest.manifestPath)) {
      return { reverted: false, files: [], reason: 'The latest autofix manifest is missing.' };
    }
    const manifest = JSON.parse(readFileSync(latest.manifestPath, 'utf8')) as {
      files?: Array<{ file?: string; backup?: string }>;
    };
    const files: string[] = [];
    for (const entry of manifest.files ?? []) {
      if (!entry.file || !entry.backup || !existsSync(entry.backup)) continue;
      copyFileSync(entry.backup, entry.file);
      files.push(entry.file);
    }
    return {
      reverted: files.length > 0,
      files,
      ...(latest.backupDir ? { backupDir: latest.backupDir } : {}),
      ...(files.length === 0 ? { reason: 'No backup files were restored.' } : {}),
    };
  } catch (error) {
    return {
      reverted: false,
      files: [],
      reason: error instanceof Error ? error.message : String(error),
    };
  }
}

export function formatFixPreview(preview: FixPreview): string {
  const lines: string[] = [];
  lines.push(`${preview.fixes.length} safe fix(es) planned${preview.skipped.length > 0 ? `, ${preview.skipped.length} skipped` : ''}.`);
  for (const fix of preview.fixes) {
    lines.push(`  ${fix.relativeFile}:${fix.startLine}  ${fix.description}`);
  }
  for (const skipped of preview.skipped) {
    lines.push(`  skipped ${skipped.findingId}: ${skipped.reason}`);
  }
  if (preview.patch) {
    lines.push('');
    lines.push(preview.patch);
  }
  return lines.join('\n');
}

export function findReportFile(outputDir: string): string | undefined {
  const file = path.join(outputDir, 'code-usage-map.json');
  return existsSync(file) ? file : undefined;
}

export function readReportFile<T>(file: string): T {
  return JSON.parse(readFileSync(file, 'utf8')) as T;
}
